window.POEM_SHARD={"open_22000":["秦中吟十首 立碑","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["勳德既下衰，文章亦陵夷。","但见山中石，立作路旁碑。","铭勳悉太公，叙德皆仲尼。","复以多爲贵，千言直万赀。","爲文彼何人，想见下笔时。","但欲愚者悦，不思贤者嗤。","岂独贤者嗤，仍传後代疑。","古石苍苔字，安知是媿词。","我闻望江县，麴令抚惸嫠。","在官有仁政，名不闻京师。","身殁欲归葬，百姓遮路岐。","攀辕不得归，留葬此江湄。","至今道其名，男女涕皆垂。","无人立碑碣，唯有邑人知。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22001":["秦中吟十首 轻肥","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["意气骄满路，鞍马光照尘。","借问何爲者，人称是内臣。","朱绂皆大夫，紫绶或将军。","夸赴军中宴，走马去如云。","尊罍溢九酝，水陆罗八珍。","果擘洞庭橘，脍切天池鳞。","食饱心自若，酒酣气益振。","是岁江南旱，衢州人食人。"],"",[["古注·《才調集》","或刻江南旱"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《才调集》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/才調集_(四庫全書本)）"]],"open_22002":["秦中吟十首 五弦","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["清歌且罢唱，红袂亦停舞。","赵叟抱五弦，宛转当胸抚。","大声麄若散，飒飒风和雨。","小声细欲绝，切切鬼神语。","又如鹊报喜，转作猨啼苦。","十指无定音，颠倒宫徵羽。","坐客闻此声，形神若无主。","行客闻此声，驻足不能举。","嗟嗟俗人耳，好今不好古。","所以绿窗琴，日日生尘土。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22003":["秦中吟十首 歌舞","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["秦中岁云暮，大雪满皇州。","雪中退朝者，朱紫尽公候。","贵有风雪兴，富无饥寒忧。","所营唯第宅，所务在追游。","朱门车马客，红烛歌舞楼。","欢酣促密坐，醉煖脱重裘。","秋官爲主人，廷尉居上头。","日中爲一乐，夜半不能休。","岂知阌乡狱，中有冻死囚。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22004":["秦中吟十首 买花","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["帝城春欲暮，喧喧车马度。","共道牡丹时，相随买花去。","贵贱无常价，酬直看花数。","灼灼百朵红，戋戋五束素。","上张幄幕庇，旁织巴篱护。","水洒复泥封，移来色如故。","家家习爲俗，人人迷不悟。","有一田舍翁，偶来买花处。","低头独长叹，此叹无人喻。","一丛深色花，十户中人赋。"],"",[],{"source":"殷志佳","body":["《买花》是《秦中吟》组诗中的一首。与白居易同时的李肇在《唐国史补》里说：“京城贵游，尚牡丹三十余年矣。每春暮，车马若狂，以不耽玩为耻。执金吾铺官围外寺观，种以求利，一本有直（值）数万者。”这首诗就真切地反映了这种状况。","从内容上看，本诗可分为两部分，自首句至“人人迷不悟”以上的十四句，是第一部分，浓墨重彩极尽铺陈；自“有一田舍翁”以下的六句，为第二部分，白描勾勒以少胜多。","暮春时节，也正是青黄不接的农忙时分，长安城内却车马喧嚣熙来攘往，繁华的街道和鼎沸的声音给人以视觉和听觉上的双重冲击。诗人用平静的笔调将中心事件娓娓道出：“共道牡丹时，相随买花去。”所有的人都在为同一件事着迷痴狂——暮春的暖风中，牡丹正盛，我们一起去买牡丹吧！作者似乎有意在渲染这种表面上的热烈与祥和，给人留下非太平盛世不能如此的感叹。这也正是作者的高明之处，他别有用心地采用了欲擒故纵的手法，为后文的转折预先埋下了伏笔。","继而作者分别用同样的手法大肆渲染了高价买花和精心移花这两个细节。买花的人争先恐后，花的价格自然也就随行就市、水涨船高，买家只选称心的牡丹，根本不在乎价格的高低贵贱，以至于出现了“灼灼百朵红，戋戋五束素”这样叹为观止的现象。“戋戋”，众多貌。“一束”，是五匹。“素”，白色的丝织品。一株开了百朵花的牡丹，竟然卖到二十五匹帛的价钱！每一株花都被精心地呵护，上面支起帐篷（“幄幕”），四周又用篱笆围上，防晒、挡风、遮雨，继而浇水、培土，细心移栽，歆享无微不至的关怀。","所有这些虽然极尽铺陈，但也只是客观描绘，直到“人人迷不悟”，才轻描淡写地表露出作者的主观倾向。正欲感慨，作者忽然发现一位穿着异于买花人的庄稼汉（“田舍翁”）偶来此处，看见达官贵人如此挥金如土，他只得低头默默长叹，那些“迷不悟”的“人人”全然没有闲情去理会他的长吁短叹，更不会有人懂得他的心思。诗人不失时机地摄下了这一特写镜头，在这花市上，大概他是唯一一位能理解田舍翁的人——当自己和一家老小拼死拼活地一年忙到头，到头来还不能过上温饱的生活，这些城里的贵人们却有这么多的闲钱来随意挥霍，“一丛深色花，十户中人赋”，一丛深色牡丹花的价格，竟然抵得上十户中等人家一年的税赋！暮春时分，正是庄稼人披星戴月抢种抢播的农忙时节，可是“帝城”中的富贵人家，也正忙得不可开交，买花、护花、移花、赏花，而他们所花费的哪一项不是来自田舍翁们辛勤血汗的劳动果实，哪一项不是来自他们节衣缩食缴纳上来的赋税呀？作者对买花者的批判，对田舍翁的同情，对世道不公的愤恨，在此借助田舍翁的感叹全盘托出。","全诗通过一种人人都习以为常的风俗，开掘出鲜明重大的社会主题。从暮春时节由来已久的高价买花事件中，诗人却看出社会的不平等，看出尖锐的阶级矛盾。白居易就是这样一位伟大的诗人，用他为民请命的诗歌，实践着自己“文章合为时而著，歌诗合为事而作”（《与元九书》）的文学主张。"]},[],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》（清·曹寅等编，康熙扬州诗局本）"]],"open_22005":["赠友五首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["一年十二月，每月有常令。","君出臣奉行，谓之握金镜。","由兹六气顺，以遂万物性。","时令一反常，生灵受其病。","周汉德下衰，王风始不竞。","又从斩鼂错，诸侯益强盛。","百里不同禁，四时自爲政。","盛夏兴土功，方春剿人命。","谁能救其失，待君佐邦柄。","峨峨象魏门，悬法彝伦正。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22006":["赠友五首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["银生楚山曲，金生鄱谿滨。","南人弃农业，求之多苦辛。","披砂复凿石，矻矻无冬春。","手足尽皴胝，爱利不爱身。","畲田既慵斫，稻田亦嬾耘。","相携作游手，皆道求金银。","毕竟金与银，何殊泥与尘。","且非衣食物，不济饥寒人。","弃本以趋末，日富而岁贫。","所以先圣王，弃藏不爲珍。","谁能反古风，待君秉国钧。","捐金复抵璧，勿使劳生民。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22007":["赠友五首 三","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["私家无钱炉，平地无铜山。","胡爲秋夏税，岁岁输铜钱。","钱力日已重，农力日已殚。","贱粜粟与麦，贱贸丝与緜。","岁暮衣食尽，焉得无饥寒。","吾闻国之初，有制垂不刊。","庸必算丁口，租必计桑田。","不求土所无，不强人所难。","量入以爲出，上足下亦安。","兵兴一变法，兵息遂不还。","使我农桑人，顦顇畎亩间。","谁能革此弊，待君秉利权。","复彼租庸法，令如贞观年。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22008":["赠友五首 四","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["京师四方则，王化之本根。","长吏久於政，然後风教敦。","如何尹京者，迁次不逡巡。","请君屈指数，十年十五人。","科条日相矫，吏力亦已勤。","宽猛政不一，民心安得淳。","九州雍爲首，羣牧之所遵。","天下率如此，何以安吾民。","谁能变此法，待君赞弥纶。","慎择循良吏，令其长子孙。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22009":["赠友五首 五","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["三十男有室，二十女有归。","近代多离乱，婚姻多过期。","嫁娶既不早，生育常苦迟。","儿女未成人，父母已衰羸。","凡人贵达日，多在长大时。","欲报亲不待，孝心无所施。","哀哉三牲养，少得及庭闱。","惜哉万锺粟，多用饱妻儿。","谁能正婚礼，待君张国维。","庶使孝子心，皆无风树悲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22010":["寓意诗五首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["豫樟生深山，七年而後知。","挺高二百尺，本末皆十围。","天子建明堂，此材独中规。","匠人执斤墨，采度将有期。","孟冬草木枯，烈火燎山陂。","疾风吹猛焰，从根烧到枝。","养材三十年，方成栋梁姿。","一朝爲灰烬，柯叶无孑遗。","地虽生尔材，天不与尔时。","不如粪土英，犹有人掇之。","已矣勿重陈，重陈令人悲。","不悲焚烧苦，但悲采用迟。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22011":["寓意诗五首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["赫赫京内史，炎炎中书郎。","昨传徵拜日，恩赐颇殊常。","貂冠水苍玉，紫绶黄金章。","佩服身未暖，已闻窜遐荒。","亲戚不得别，吞声泣路旁。","宾客亦已散，门前雀罗张。","富贵来不久，倏如瓦沟霜。","权势去尤速，瞥若石火光。","不如守贫贱，贫贱可久长。","传语宦游子，且来归故乡。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22012":["寓意诗五首 三","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["促织不成章，提壶但闻声。","嗟哉虫与鸟，无实有虚名。","与君定交日，久要如弟兄。","何以示诚信，白水指爲盟。","云雨一爲别，飞沈两难幷。","君爲得风鹏，我爲失水鲸。","音信日已疎，恩分日已轻。","穷通尚如此，何况死与生。","乃知择交难，须有知人明。","莫将山上松，结托水上萍。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22013":["寓意诗五首 四","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["翩翩两玄鸟，本是同巢燕。","分飞来几时，秋夏炎凉变。","一宿蓬筚庐，一栖明光殿。","偶因衔泥处，复得重相见。","彼矜杏梁贵，此嗟茅栋贱。","眼看秋社至，两处俱难恋。","所托各暂时，胡爲相叹羡。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22014":["寓意诗五首 五","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["婆娑园中树，根株大合围。","蠢尔树间虫，形质一何微。","孰谓虫之微，虫蠹已无期。","孰谓树之大，花叶有衰时。","花衰夏未实，叶病秋先萎。","树心半爲土，观者安得知。","借问虫何在，在身不在枝。","借问虫何食，食心不食皮。","岂无啄木鸟，觜长将何爲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22015":["读史五首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楚怀放灵均，国政亦荒淫。","彷徨未忍决，绕泽行悲吟。","汉文疑贾生，谪置湘之阴。","是时刑方措，此去难爲心。","士生一代间，谁不有浮沈。","良时真可惜，乱世何足钦。","乃知汨罗恨，未抵长沙深。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22016":["读史五首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["祸患如棼丝，其来无端绪。","马迁下蚕室，嵇康就囹圄。","抱冤志气屈，忍耻形神沮。","当彼戮辱时，奋飞无翅羽。","商山有黄绮，颍川有巢许。","何不从之游？超然离网罟。","山林少羁鞅，世路多艰阻。","寄谢伐檀人，慎勿嗟穷处。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22017":["读史五首 三","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["汉日大江军，少爲乞食子。","秦时故列侯，老作锄瓜士。","春华何暐晔，园中发桃李。","秋风忽萧条，堂上生荆杞。","深谷变爲岸，桑田成海水。","势去未须悲，时来何足喜。","寄言荣枯者，反复殊未已。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22018":["读史五首 四","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["含沙射人影，虽病人不知。","巧言构人罪，至死人不疑。","掇蠭杀爱子，掩鼻戮宠姬。","弘恭陷萧望，赵高谋李斯。","阴德既必报，阴祸岂虚施。","人事虽可罔，天道终难欺。","明则有刑辟，幽则有神祗。","苟免勿私喜，鬼得而诛之。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22019":["读史五首 五","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["季子顦顇时，妇见不下机。","买臣负薪日，妻亦弃如遗。","一朝黄金多，佩印衣锦归。","去妻不敢视，妇嫂强依依。","富贵家人重，贫贱妻子欺。","奈何贫富间，可移亲爱志。","遂使中人心，汲汲求富贵。","又令下人力，各竞锥刀利。","随分归舍来，一取妻孥意。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22020":["和荅诗十首 和思归乐","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["山中不栖鸟，夜半声嘤嘤。","似道思归乐，行人掩泣听。","皆疑此山路，迁客多南征。","忧愤气不散，结化爲精灵。","我谓此山鸟，本不因人生。","人心自怀土，想作思归鸣。","孟尝平居时，娱耳琴泠泠。","雍门一言感，未奏泪沾缨。","魏武铜雀妓，日与欢乐幷。","一旦西陵望，欲歌先涕零。","峡猨亦何意，陇水复何情。","爲入愁人耳，皆爲肠断声。","请看元侍御，亦宿此邮亭。","因听思归鸟，神气独安宁。","问君何以然，道胜心自平。","虽爲南迁客，如在长安城。","云得此道来，何虑复何营。","穷达有前定，忧喜无交争。","所以事君日，持宪立大庭。","虽有回天力，挠之终不倾。","况始三十余，年少有直名。","心中志气大，眼前爵禄轻。","君恩若雨露，君威若雷霆。","退不苟免难，进不曲求荣。","在火辨玉性，经霜识松贞。","展禽任三黜，灵均长独醒。","获戾自东洛，贬官向南荆。","再拜辞阙下，长揖别公卿。","荆州又非远，驿路半月程。","汉水照天碧，楚山插云青。","江陵橘似珠，宜城酒如饧。","谁谓谴谪去，未妨游赏行。","人生百岁内，天地暂寓形。","太仓一稊米，大海一浮萍。","身委逍遥篇，心付头陀经。","尚达死生观，宁爲宠辱惊。","中怀苟有主，外物安能萦。","任意思归乐，声声啼到明。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22021":["和荅诗十首 和阳城驿","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["商山阳城驿，中有叹者谁。","云是元监察，江陵谪去时。","忽见此驿名，良久涕欲垂。","何故阳道州，名姓同於斯。","怜君一寸心，宠辱誓不移。","疾恶若巷伯，好贤如缁衣。","沈吟不能去，意者欲改爲。","改爲避贤驿，大署於门楣。","荆人爱羊祜，户曹改爲辞。","一字不忍道，况兼姓呼之。","因题八百言，言直文甚奇。","诗成寄与我，锵若金和丝。","上言阳公行，友悌无等夷。","骨肉同衾裯，至死不相离。","次言阳公迹，夏邑始栖迟。","乡人化其风，少长皆孝慈。","次言阳公道，终日对酒巵。","兄弟笑相顾，醉貌红怡怡。","次言阳公节，謇謇居谏司。","誓心除国蠹，决死犯天威。","终言阳公命，左迁天一涯。","道州炎瘴地，身不得生归。","一一皆实录，事事无孑遗。","凡是爲善者，闻之恻然悲。","道州既已矣，往者不可追。","何世无其人，来者亦可思。","愿以君子文，告彼大乐师。","附於雅歌末，奏之白玉墀。","天子闻此章，教化如法施。","直谏从如流，佞臣恶如疵。","宰相闻此章，政柄端正持。","进贤不知倦，去邪勿复疑。","宪臣闻此章，不敢怀依违。","谏官闻此章，不忍纵诡随。","然後告史氏，旧史有前规。","若作阳公传，欲令後世知。","不劳叙世家，不用费文辞。","但於国史上，全录元稹诗。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22022":["和荅诗十首 荅桐花","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["山木多蓊郁，兹桐独亭亭。","叶重碧云片，花簇紫霞英。","是时三月天，春暖山雨晴。","夜色向月浅，闇香随风轻。","行者多商贾，居者悉黎氓。","无人解赏爱，有客独屏营。","手攀花枝立，足蹋花影行。","生怜不得所，死欲扬其声。","截爲天子琴，刻作古人形。","云待我成器，荐之於穆清。","诚是君子心，恐非草木情。","胡爲爱其华，而反伤其生。","老龟被刳肠，不如无神灵。","雄鸡自断尾，不愿爲牺牲。","况此好颜色，花紫叶青青。","宜遂天地性，忍加刀斧刑。","我思五丁力，拔入九重城。","当君正殿栽，花叶生光晶。","上对月中桂，下覆阶前蓂。","泛拂香炉烟，隐映斧藻屏。","爲君布绿阴，当暑荫轩楹。","沈沈绿满地，桃李不敢争。","爲君发清韵，风来如叩琼。","泠泠声满耳，郑卫不足听。","受君封植力，不独吐芬馨。","助君行春令，开花应晴明。","受君雨露恩，不独含芳荣。","戒君无戏言，翦叶封弟兄。","受君岁月功，不独资生成。","爲君长高枝，凤皇上头鸣。","一鸣君万岁，寿如山不倾。","再鸣万人泰，泰阶爲之平。","如何有此用，幽滞在岩垧。","岁月不尔驻，孤芳坐凋零。","请向桐枝上，爲余题姓名。","待余有势力，移尔献丹庭。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22023":["和荅诗十首 和大觜乌","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["乌者种有二，名同性不同。","觜小者慈孝，觜大者贪庸。","觜大命又长，生来十余冬。","物老颜色变，头毛白茸茸。","飞来庭树上，初但惊儿童。","老巫生奸计，与乌意潜通。","云此非凡鸟，遥见起敬恭。","千岁乃一出，喜贺主人翁。","祥瑞来白日，神圣占知风。","阴作北斗使，能爲人吉凶。","此乌所止家，家产日夜丰。","上以致寿考，下可宜田农。","主人富家子，身老心童蒙。","随巫拜复祝，妇姑亦相从。","杀鸡荐其肉，敬若禋六宗。","乌喜张大觜，飞接在虚空。","乌既饱羶腥，巫亦飨甘浓。","乌巫互相利，不复两西东。","日日营巢窟，稍稍近房栊。","虽生八九子，谁辨其雌雄。","羣雏又成长，衆觜逞残凶。","探巢吞燕卵，入蔟啄蚕虫。","岂无乘秋隼，羁绊委高墉。","但食乌残肉，无施搏击功。","亦有能言鹦，翅碧觜距红。","暂曾说乌罪，囚闭在深笼。","青青窗前柳，郁郁井上桐。","贪乌占栖息，慈乌独不容。","慈鸟尔奚爲，来往何憧憧。","晓去先晨鼓，暮归後昏钟。","辛苦尘土间，飞啄禾黍丛。","得食将哺母，饥肠不自充。","主人憎慈乌，命子削弹弓。","弦续会稽竹，丸铸荆山铜。","慈乌求母食，飞下尔庭中。","数粒未入口，一丸已中胸。","仰天号一声，似欲诉苍穹。","反哺日未足，非是惜微躬。","谁能持此冤，一爲问化工。","胡然大觜乌，竟得天年终。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22024":["和荅诗十首 答四皓庙","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["天下有道见，无道卷怀之。","此乃圣人语，吾闻诸仲尼。","矫矫四先生，同禀希世资。","随时有显晦，秉道无磷缁。","秦皇肆暴虐，二世遘乱离。","先生相随去，商岭采紫芝。","君看秦狱中，戮辱者李斯。","刘项争天下，谋臣竟悦随。","先生如鸾鹤，去入冥冥飞。","君看齐鼎中，焦烂者郦其。","子房得沛公，自谓相遇迟。","八难掉舌枢，三略役心机。","辛苦十数年，昼夜形神疲。","竟杂霸者道，徒称帝者师。","子房尔则能，此非吾所宜。","汉高之季年，嬖宠锺所私。","冢嫡欲废夺，骨肉相忧疑。","岂无子房口，口舌无所施。","亦有陈平心，心计将何爲。","皤皤四先生，高冠危映眉。","从容下南山，顾盼入东闱。","前瞻惠太子，左右生羽仪。","却顾戚夫人，楚舞无光辉。","心不画一计，口不吐一词。","闇定天下本，遂安刘氏危。","子房吾则能，此非尔所知。","先生道既光，太子礼甚卑。","安车留不住，功成弃如遗。","如彼旱天云，一雨百谷滋。","泽则在天下，云复归稀夷。","勿高巢与由，勿尚吕与伊。","巢由往不返，伊吕去不归。","岂如四先生，出处两逶迤。","何必长隐逸，何必长济时。","由来圣人道，无朕不可窥。","卷之不盈握，舒之亘八陲。","先生道甚明，夫子犹或非。","愿子辨其惑，爲予吟此诗。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22025":["和荅诗十首 和雉媒","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["吟君雉媒什，一哂一复叹。","和之一何晚，今日乃成篇。","岂唯鸟有之，抑亦人复然。","张陈刎颈交，竟以势不完。","至今不平气，塞绝泜水源。","赵襄骨肉亲，亦以利相残。","至今不善名，高於磨笄山。","况此笼中雉，志在饮啄间。","稻粱暂入口，性已随人迁。","身苦亦自忘，同族何足言。","但恨爲媒拙，不足以自全。","劝君今日後，养鸟养青鸾。","青鸾一失侣，至死守孤单。","劝君今日後，结客结任安。","主人宾客去，独住在门阑。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22026":["和荅诗十首 和松树","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["亭亭山上松，一一生朝阳。","森耸上参天，柯条百尺长。","漠漠尘中槐，两两夹康庄。","婆娑低覆地，枝干亦寻常。","八月白露降，槐叶次第黄。","岁暮满山雪，松色郁青苍。","彼如君子心，秉操贯冰霜。","此如小人面，变态随炎凉。","共知松胜槐，诚欲栽道傍。","粪土种瑶草，瑶草终不芳。","尚可以斧斤，伐之爲栋梁。","杀身获其所，爲君构明堂。","不然终天年，老死在南冈。","不愿亚枝叶，低随槐树行。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22027":["和荅诗十首 荅箭镞","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["矢人职司忧，爲箭恐不精。","精在利其镞，错磨锋镝成。","插以青竹簳，羽之赤雁翎。","勿言分寸铁，爲用乃长兵。","闻有狗盗者，昼伏夜潜行。","摩弓拭箭镞，夜射不待明。","一盗既流血，百犬同吠声。","狺狺嘷不已，主人爲之惊。","盗心憎主人，主人不知情。","反责镞太利，矢人获罪名。","寄言控弦者，愿君少留听。","何不向西射？西天有狼星。","何不向东射？东海有长鲸。","不然学仁贵，三矢平虏庭。","不然学仲连，一发下燕城。","胡爲射小盗，此用无乃轻。","徒沾一点血，虚汚箭头腥。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22028":["和荅诗十首 和古社","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["废村多年树，生在古社隈。","爲作妖狐窟，心空身未摧。","妖狐变美女，社树成楼台。","黄昏行人过，见者心裴回。","饥鵰竟不捉，老犬反爲媒。","岁媚少年客，十去九不回。","昨夜云雨合，烈风驱迅雷。","风拔树根出，雷劈社坛开。","飞电化爲火，妖狐烧作灰。","天明至其所，清旷无氛埃。","旧地葺村落，新田辟荒莱。","始知天降火，不必常爲灾。","勿谓神默默，勿谓天恢恢。","勿喜犬不捕，勿夸鵰不猜。","寄言狐媚者，天火有时来。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22029":["和荅诗十首 和分水岭","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["高岭峻棱棱，细泉流亹亹。","势分合不得，东西随所委。","悠悠草蔓底，溅溅石罅里。","分流来几年，昼夜两如此。","朝宗远不及，去海三千里。","浸润小无功，山苗长旱死。","萦纡用无所，奔迫流不已。","唯作呜咽声，夜入行人耳。","有源殊不竭，无坎终难止。","同出而异流，君看何所似。","有似骨肉亲，派别从兹始。","又似势利交，波澜相背起。","所以赠君诗，将君何所比。","不比山上泉，比君井中水。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22030":["有木诗八首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["有木名弱柳，结根近清池。","风烟借颜色，雨露助华滋。","峨峨白雪花，嫋嫋青丝枝。","渐密阴自庇，转高梢四垂。","截枝扶爲杖，輭弱不自持。","折条用樊圃，柔脆非其宜。","爲树信可玩，论材何所施。","可惜金堤地，栽之徒尔爲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22031":["有木诗八首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["有木名樱桃，得地早滋茂。","叶密独承日，花繁偏受露。","迎风闇摇动，引鸟潜来去。","鸟啄子难成，风来枝莫住。","低輭易攀玩，佳人屡回顾。","色求桃李饶，心向松筠妬。","好是映墙花，本非当轩树。","所以姓萧人，曾爲伐樱赋。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22032":["有木诗八首 三","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["有木秋不凋，青青在江北。","谓爲洞庭橘，美人自移植。","上受顾盼恩，下勤浇溉力。","实成乃是枳，臭苦不堪食。","物有似是者，真僞何由识。","美人默无言，对之长叹息。","中含害物意，外矫凌霜色。","仍向枝叶间，潜生刺如棘。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22033":["有木诗八首 四","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["有木名杜棃，阴森覆丘壑。","心蠹已空朽，根深尚盘薄。","狐媚言语巧，鸟妖声音恶。","凭此爲巢穴，往来互栖托。","四傍五六本，叶枝相交错。","借问因何生，秋风吹子落。","爲长社坛下，无人敢芟斫。","几度野火来，风回烧不着。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22034":["有木诗八首 五","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["有木香苒苒，山头生一蕟。","主人不知名，移种近轩闼。","爱其有芳味，因以调麴糵。","前後曾饮者，十人无一活。","岂徒悔封植，兼亦误采掇。","试问识药人，始知名野葛。","年深已滋蔓，刀斧不可伐。","何时猛风来，爲我连根拔。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22035":["有木诗八首 六","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["有木名水柽，远望青童童。","根株非劲挺，柯叶多蒙笼。","彩翠色如柏，鳞皴皮似松。","爲同松柏类，得列嘉树中。","枝弱不胜雪，势高常惧风。","雪压低还举，风吹西复东。","柔芳甚杨柳，早落先梧桐。","惟有一堪赏，中心无蠹虫。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22036":["有木诗八首 七","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["有木名凌霄，擢秀非孤标。","偶依一株树，遂抽百尺条。","托根附树身，开花寄树梢。","自谓得其势，无因有动摇。","一旦树摧倒，独立暂飘颻。","疾风从东起，吹折不终朝。","朝爲拂云花，暮爲委地樵。","寄言立身者，勿学柔弱苗。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22037":["有木诗八首 八","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["有木名丹桂，四时香馥馥。","花团夜雪明，叶翦春云绿。","风影清似水，霜枝冷如玉。","独占小山幽，不容凡鸟宿。","匠人爱芳直，裁截爲厦屋。","干细力未成，用之君自速。","重任虽大过，直心终不曲。","纵非梁栋材，犹胜寻常木。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22038":["叹鲁二首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["季桓心岂忠，其富过周公。","阳货道岂正，其权执国命。","由来富与权，不系才与贤。","所托得其地，虽愚亦获安。","彘肥因粪壤，鼠稳依社坛。","虫兽尚如是，岂谓无因缘。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22039":["叹鲁二首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["展禽胡爲者，直道竟三黜。","颜子何如人，屡空聊过日。","皆怀王佐道，不践陪臣秩。","自古无奈何，命爲时所屈。","有如草木分，天各与其一。","荔枝非名花，牡丹无甘实。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22040":["反鲍明远白头吟","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["炎炎者烈火，营营者小蝇。","火不热贞玉，蝇不点清冰。","此苟无所受，彼莫能相仍。","乃知物性中，各有能不能。","古称怨恨死，则人有所惩。","惩淫或应可，在道未爲弘。","譬如蜩鷃徒，啾啾啅龙鹏。","宜当委之去，寥廓高飞腾。","岂能泥尘下，区区酬怨憎。","胡爲坐自苦，吞悲仍抚膺。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22041":["青冢","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["上有饥鹰号，下有枯蓬走。","茫茫边雪里，一掬沙培塿。","传是昭君墓，埋闭蛾眉久。","凝脂化爲泥，铅黛复何有。","唯有阴怨气，时生坟左右。","郁郁如苦雾，不随骨销朽。","妇人无他才，荣枯系妍否。","何乃明妃命，独悬画工手。","丹青一诖误，白黑相纷纠。","遂使君眼中，西施作嫫母。","同侪倾宠幸，异类爲配偶。","祸福安可知，美颜不如丑。","何言一时事，可戒千年後。","特报後来姝，不须倚眉首。","无辞插荆钗，嫁作贫家妇。","不见青冢上，行人爲浇酒。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22042":["杂感","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["君子防悔尤，贤人戒行藏。","嫌疑远瓜李，言动慎毫芒。","立教固如此，抚事有非常。","爲君持所感，仰面问苍苍。","犬啮桃树根，李树反见伤。","老龟烹不烂，延祸及枯桑。","城门自焚爇，池鱼罹其殃。","阳货肆凶暴，仲尼畏於匡。","鲁酒薄如水，邯郸开战场。","伯禽鞭见血，过失由成王。","都尉身降虏，宫刑加子长。","吕安兄不道，都市杀嵇康。","斯人死已久，其事甚昭彰。","是非不由己，祸患安可防。","使我千载後，涕泗满衣裳。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22043":["新乐府 七德舞\t美拨乱，陈王业也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["七德舞，七德歌，传自武德至元和。","元和小臣白居易，观舞听歌知乐意。","乐终稽首陈其事，太宗十八举义兵。","白旄黄钺定两京，擒充戮窦四海清。","二十有四功业成，二十有九即帝位。","三十有五致太平，功成理定何神速。","速在推心置人腹，亡卒遗骸散帛收。","饥人卖子分金赎，魏徵梦见子夜泣。","张谨哀闻辰日哭，怨女三千放出宫。","死囚四百来归狱，翦须烧药赐功臣。","李积呜咽思杀身含血吮创抚战士，思摩奋呼乞効死。","则知不独善战善乘时，以心感人人心归。","尔来一百九十载，天下至今歌舞之。","歌七德，舞七德，圣人有作垂无极。","岂徒耀神武，岂徒夸圣文。","太宗意在陈王业，王业艰难示子孙。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22044":["新乐府 法曲\t美列圣，正华声也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["法曲法曲歌大定，积德重熙有余庆。","永徽之人舞而咏，法曲法曲舞霓裳。","政和世理音洋洋，开元之人乐且康。","法曲法曲歌堂堂，堂堂之庆垂无疆。","中宗肃宗复鸿业，唐祚中兴万万叶。","法曲法曲合夷歌，夷声邪乱华声和。","以乱干和天宝末，明年胡尘犯宫阙。","乃知法曲本华风，苟能审音与政通。","一从胡曲相参错，不辨兴衰与哀乐。","愿求牙旷正华音，不令夷夏相交侵。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22045":["新乐府 二王後\t明祖宗之意也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["二王後，彼何人，介公酅公爲国宾。","周武隋文之子孙，古人有言天下者，非是一人之天下。","周亡天下传於隋，隋人失之唐得之。","唐兴十叶岁二百，介公酅公世爲客。","明堂太庙朝享时，引居宾位备威仪。","备威仪，助郊祭，高祖太宗之遗制。","不独兴灭国，不独继绝世。","欲令嗣位守文君，亡国之孙取爲戒。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22046":["新乐府 海漫漫\t戒求仙也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["海漫漫，直下无底傍无边。","云涛烟浪最深处，人传中有三神山。","山上多生不死药，服之羽化爲天仙。","秦皇汉武信此语，方士年年采药去。","蓬莱今古但闻名，烟水茫茫无觅处。","海漫漫，风浩浩，眼穿不见蓬莱岛。","不见蓬莱不敢归，童男丱女舟中老。","徐福文成多诳诞，上元太一虚祈祷。","君看骊山顶上茂陵头，毕竟悲风吹蔓草。","何况玄元圣祖五千言，不言药，不言仙，不言白日升青天。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22047":["新乐府 立部伎\t刺雅乐之替也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["立部伎，鼓笛諠，舞双劒，跳七丸，嫋巨索，掉长竿。","太常部伎有等级，堂上者坐堂下立。","堂上坐部笙歌清，堂下立部鼓笛鸣。","笙歌一声衆侧耳，鼓笛万曲无人听。","立部贱，坐部贵，坐部退爲立部伎。","击鼓吹笙和杂戏，立部又退何所任。","始就乐悬操雅音，雅音替坏一至此。","长令尔辈调宫徵，圆丘后土郊祀时。","言将此乐感神只，欲望凤来百兽舞。","何异北辕将适楚，工师愚贱安足云。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22048":["新乐府 华原磬\t刺乐工非其人也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["华原磬，华原磬，古人不听今人听。","泗滨石，泗滨石，今人不击古人击。","今人古人何不同？用之舍之由乐工。","乐工虽在耳如壁，不分清浊即爲聋。","棃园弟子调律吕，知有新声不如古。","古称浮磬出泗滨，立辨致死声感人。","宫悬一听华原石，君心遂忘封疆臣。","果然胡寇从燕起，武臣少肯封疆死。","始知乐与时政通，岂听铿锵而已矣。","磬襄入海去不归，长安市儿爲乐师。","华原磬与泗滨石，清浊两声谁得知。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22049":["新乐府 上阳白发人\t愍怨旷也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["上阳人，红颜闇老白发新。","绿衣监使守宫门，一闭上阳多少春。","玄宗末岁初选入，入时十六今六十。","同时采择百余人，零落年深残此身。","忆昔吞悲别亲族，扶入车中不教哭。","皆云入内便承恩，脸似芙蓉胸似玉。","未容君王得见面，已被杨妃遥侧目。","妬令潜配上阳宫，一生遂向空房宿。","宿空房，秋夜长，夜长无寐天不明。","耿耿残灯背壁影，萧萧暗雨打窗声。","春日迟，日迟独坐天难暮。","宫莺百啭愁厌闻，梁燕双栖老休妬。","莺归燕去长悄然，春往秋来不记年。","唯向深宫望明月，东西四五百回圆。","今日宫中年最老，大家遥赐尚书号。","小头鞋履窄衣裳，青黛点眉眉细长。","外人不见见应笑，天宝末年时世妆。","上阳人，苦最多，少亦苦，老亦苦，少苦老苦两如何？","君不见昔时吕向美人赋，又不见今日上阳白发歌。"],"",[],{"source":"周啸天","body":["“今日宫中年最老”到“天宝末年时世妆”六句为三段，以“今日”为标记，写宫人年老的寂寞。不耐幽怨的宫人大多早死，而进入老年的宫人，赢得的是深深的寂寞和一个女尚书的虚衔，这虚衔还是皇帝（“大家”）遥赐的，抵偿得了她一生幸福的代价吗？诗中细写与世隔绝的老宫女的妆容，四十五年如一日，还是天宝末年的妆扮，殊不知外边早已不穿小鞋窄袖，而衣尚宽大，早已不兴细长眉样，而兴短阔眉样，时代潮流更新复更新，上阳人早已跟不上趟，成了活的文物。几笔淡淡的嘲谑，饱含作者多少同情之泪。“上阳人，苦最多”以下七句卒章显其志，直抒感喟。吕向是作者的老前辈，其《美人赋》自注“天宝末极密采艳色者，当时号花鸟使”，因作赋以讽之。诗人表明本篇的主题与吕赋一脉相承，是为宫女请命的。","这首诗在写作上是以个别见一般。作者没有概叙宫女共同的悲惨遭遇，而是通过“这一个”来表现一般。诗中有具体环境、人物外貌衣着及心理的描写，给人的感受是生动形象的。其次是通过环境气氛的渲染，如用绵绵秋雨、双双春燕来烘托主人公的凄清和孤单，增强了形象表现力。其三是细节描写，如对老宫女早不入时的衣着服饰的具体描写，形象地暗示出其幽禁的时间之长，有恍如隔世之感。"]},[],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》（清·曹寅等编，康熙扬州诗局本）"]],"open_22050":["新乐府 胡旋女\t戒近习也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["胡旋女，胡旋女，心应弦，手应鼓。","弦鼓一声双袖举，回雪飘颻转蓬舞。","左旋右转不知疲，千匝万周无已时。","人间物类无可比，奔车轮缓旋风迟。","曲终再拜谢天子，天子爲之微啓齿。","胡旋女，出康居，徒劳东来万里余。","中原自有胡旋者，鬬妙争能尔不如。","天宝季年时欲变，臣妾人人学圜转。","中有太真外禄山，二人最道能胡旋。","棃花园中册作妃，金鸡障下养爲儿。","禄山胡旋迷君眼，兵过黄河疑未反。","贵妃胡旋惑君心，死弃马嵬念更深。","从兹地轴天维转，五十年来制不禁。","胡旋女，莫空舞，数唱此歌悟明主。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22051":["新乐府 新丰折臂翁\t戒边功也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["新丰老翁八十八，头鬓眉须皆似雪。","玄孙扶向店前行，左臂凭肩右臂折。","问翁臂折来几年，兼问致折何因缘。","翁云贯属新丰县，生逢圣代无征战。","惯听棃园歌管声，不识旗枪与弓箭。","无何天宝大徵兵，户有三丁点一丁。","点得驱将何处去，五月万里云南行。","闻道云南有泸水，椒花落时瘴烟起。","大军徒涉水如汤，未过十人二三死。","村南村北哭声哀，儿别爷娘夫别妻。","皆云前後征蛮者，千万人行无一回。","是时翁年二十四，兵部牒中有名字。","夜深不敢使人知，偷将大石搥折臂。","张弓簸旗俱不堪，从兹始免征云南。","骨碎筋伤非不苦，且图拣退归乡土。","此臂折来六十年，一肢虽废一身全。","至今风雨阴寒夜，直到天明痛不眠。","痛不眠，终不悔，且喜老身今独在。","不然当时泸水头，身死魂孤骨不收。","应作云南望乡鬼，万人冢上哭呦呦。","老人言，君听取。","君不闻开元宰相宋开府，不赏边功防黩武。","又不闻天宝宰相杨国忠，欲求恩幸立边功。","边功未立生人怨，请问新丰折臂翁。"],"",[],{"source":"王英志","body":["全诗可分为三段。第一段自首句“新丰老翁八十八”至“兼问：‘致折何因缘？’”。主要是描绘折臂翁的外观形象，并向第二段过渡。“新丰老翁八十八”，属于“首句标其目”（《新乐府序》）。此句一作“新丰老翁年八十”按后面诗云“是时（天宝十三载）翁年二十四”推算，当以“年八十”为是。此言“八十八”是为了押韵之故。“头鬓眉须皆似雪”的比喻，则是对老翁“八十八”高龄的具象化；亦暗示其作为历史见证人的可信性，如同元稹笔下的“闲坐说玄宗”的“白头宫女”（《行宫》）一样。这一段的关键在于“左臂凭肩右臂折”一句。老翁左臂搭在玄孙的肩头上“向店前行”，而“右臂”却已折断。这一奇特的残肢形象是全诗立意之本。诗人见老翁之“右臂折”不禁产生关切之意，于是问：“臂折来几年？”又问：“致折何因缘？”从而引出第二段老翁之叙述。这两句起到承上启下的作用。","第二段是全诗的主体，自“翁云：‘贯属新丰县。’”至“万人冢上哭呦呦”，长达三十四句。此段以第一人称的口吻来叙事，不仅使诗产生了真切自然之感，而且增强了叙事内容的可信程度。此段又由四小层组成，基本采用历时性结构。","第一小层写老翁先回忆“天宝大征兵”之前“圣代无征战”的安居乐业生活。“圣代”指开元年间，那是唐代国富民强、天下太平的全盛时期，“惯听梨园歌管声，不识旗枪与弓箭”，从正反两个角度描绘了开元“圣代”安定太平的景象，并充满了怀念之情。","自“无何天宝大征兵”至“千万人行无一回”为第二小层。老翁转而回忆“圣代”之后即天宝十三年（754），杨国忠广征壮丁及重新派兵攻打南诏国而全军覆没的悲惨情景。这一小层采用空间转换的结构，即由此及彼，再由彼及此，把新丰的征兵与云南的征战相联系，从而揭示出征兵等于送死的实质。“无何天宝大征兵，户有三丁征一丁”，此写新丰征兵数额之大。而“点得驱将何处去”一句，又使空间转向“五月万里云南行”。那里气候恶劣，特别是“泸水”即金沙江在“椒花落”的夏末时节，有有毒的“瘴气”，而大军渡河无舟桥可资，只能徒步过河。但水热如汤，“未过十人二三死”，这是出征南诏者的可悲命运。正因为“闻道”彼处是如此可怕，故诗再回写此地征兵之情景时就更充满悲戚之情：“村南村北哭声哀，儿别爷娘夫别妻。”此时生离即是死别。“千万人行无一回”乃前车之鉴。这一小层实际上是写老翁对诗人“致折何因缘”之问的回答。","第三小层自“是时翁年二十四”至“且图拣退归乡土”。此层继写老翁自己“折臂”的经过。当年老翁年二十四，正是应征之年，其名列入兵部征兵名册上，无法逃避。但为免重蹈出征者之覆辙，乃有“夜深不敢使人知，偷将大石锤折臂”的自戕惨剧。一个身体健全的青年，为了“免征云南”，而被迫采取如此残酷的手段，真令人“心折骨惊”！但这不是“老翁”不自惜，实乃统治集团穷兵黩武之政策更残酷。在死与残二者之间，“老翁”毅然选择后者，却是明智之举。因为他终于逃脱了“云南行”的必死厄运，能“拣退归乡土”，则是不幸中之大幸。","自“此臂折来六十年”至“万人冢上哭呦呦”，为第四小层，写老翁折臂后六十年来的感慨。“此臂折来六十年”又是答诗人“臂折来几年”的问题。“一肢虽废一身全”，是对自己折臂价值的总评价，亦寓有未作他乡之鬼的庆幸。但“一肢”之废，六十年来毕竟给老翁带来巨大的痛苦：“至今风雨阴寒夜，直到天明痛不眠。”但他却“终不悔”，“且喜老身今独在”。这种肢废而“喜”的“反常”的心态实际上是正常的，它深刻地揭示出穷兵黩武给百姓带来的灾难远胜于折臂残废。当年“千万人行无一回”就是未折臂者的更可悲的结局。老翁先从正面来说，然后又从反面来说：“不然当时泸水头，身死魂孤骨不收；应作云南望乡鬼，万人冢上哭呦呦。”“万人冢”，据作者自注，云南有万人冢，即鲜于仲通、李密（当作“宓”）曾覆军之所也。通过对比，更显示老翁“折臂”是十分值得的。","诗写至此原本可以结束，但白居易于新乐府倡导“其辞质而径，欲见之者易谕也；其言直而切，欲闻之者深诫也”，并要“卒章显其志”（《新乐府序》）；因此在“老翁”之言结束后，诗人又直接出面，发表议论。这就是第三段的内容。这几句虽属于议论，但能“带情韵以行”（清沈德潜《说诗晬语》），与枯燥的“以议论为诗”不同。诗人通过开元宰相“宋开府”宋璟与天宝宰相杨国忠相对比，褒前者而贬后者，挑明“防黩武”之旨。据作者自注：开元初年，突厥数犯边，当时天武军牙将郝灵筌出使，斩了突厥默啜首级献给朝廷，自谓有不世之功。时宋璟为相，因天子年少好武，恐好大喜功者因而生黩武之心，没有给郝氏任何奖赏，次年才授郎将。诗人对宋璟“不赏边功防黩武”是极为赞赏的。相反，据作者注：天宝末，杨国忠为相，重新发动征讨阁罗凤的战争，前后征兵二十余万人，皆一去不返。但仍征兵不止，甚至捉人连枷赴役，天下怨恨，民不聊生，故安禄山得乘机而造反。对杨国忠“欲求恩幸立边功”而黩武以及造成的灾难，诗人则痛恨之至！诗人提醒统治者与世人：切勿“边功未立生人怨”，而“新丰折臂翁”即是历史的见证！","这首诗的题材十分独特，引人注目。尽管自我折臂之人十分罕见，但“新丰折臂翁”的形象具有很高的典型价值。读者借助这“一斑”，足以窥见杨国忠穷兵黩武之“全豹”。对于“新丰折臂翁”，诗人除了作外貌的描绘外，主要是刻画其心理，以肢废“痛不眠”却“终不悔”而“喜”的“反常”心态，来塑造“老翁”的反战形象；而当年他敢于自戕，亦反映其刚毅、果断的性格。此诗与其他新乐府诗一样，具有“意深词浅，思苦言甘”（清袁枚《续诗品》）的特色；而且善于“用常得奇”（清刘熙载《艺概》），即以平浅的语言表现惊警之意，如“此臂折来六十年，一肢虽废一身全”，“痛不眠，终不悔”，都发人深思，耐人寻味。"]},[],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》（清·曹寅等编，康熙扬州诗局本）"]],"open_22052":["新乐府 太行路\t借夫妇以讽君臣之不终也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["太行之路能摧车，若比人心是坦途。","巫峡之水能覆舟，若比人心是安流。","人心好恶苦不常，好生毛羽恶生疮。","与君结发未五载，岂期牛女爲参商。","古称色衰相弃背，当时美人犹怨悔。","何况如今鸾镜中，妾颜未改君心改。","爲君熏衣裳，君闻兰麝不馨香。","爲君盛容饰，君看金翠无颜色。","行路难，难重陈。","人生莫作妇人身，百年苦乐由他人。","行路难，难於山，险於水。","不独人间夫与妻，近代君臣亦如此。","君不见左纳言，右纳史，朝承恩，暮赐死。","行路难，不在水，不在山，只在人情反覆间。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22053":["新乐府 司天台\t引古以儆今也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["司天台，仰观俯察天人际。","羲和死来职事废，官不求贤空取艺。","昔闻西汉元成间，上陵下替谪见天。","北辰微闇少光色，四星煌煌如火赤。","耀芒动角射三台，上台半灭中台坼。","是时非无太史官，眼见心知不敢言。","明朝趋入明光殿，唯奏庆云寿星见。","天文时变两如斯，九重天子不得知。","不得知，安用台高百尺爲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22054":["新乐府 捕蝗\t\t刺长吏也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["捕蝗捕蝗谁家子，天热日长饥欲死。","兴元兵後伤阴阳，和气蛊蠹化爲蝗。","始自两河及三辅，荐食如蚕飞似雨。","雨飞蚕食千里间，不见青苗空赤土。","河南长吏言忧农，课人昼夜捕蝗虫。","是时粟斗钱三百，蝗虫之价与粟同。","捕蝗捕蝗竟何利，徒使饥人重劳费。","一虫虽死百虫来，岂将人力定天灾。","我闻古之良吏有善政，以政驱蝗蝗出境。","又闻贞观之初道欲昌，文皇仰天吞一蝗。","一人有庆兆民赖，是岁虽蝗不爲害。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22055":["新乐府 昆明春\t思王泽之广被也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昆明春，昆明春，春池岸古春流新。","影浸南山青滉瀁，波沈西日红奫沦。","往年因旱池枯竭，龟尾曳涂鱼喣沫。","诏开八水注恩波，千介万鳞同日活。","今来净绿水照天，游鱼鱍鱍莲田田。","洲香杜若抽心短，沙暖鸳鸯铺翅眠。","动植飞沈皆遂性，皇泽如春无不被。","渔者仍丰网罟资，贫人久获菰蒲利。","诏以昆明近帝城，官家不得收其征。","菰蒲无租鱼无税，近水之人感君惠。","感君惠，独何人。","吾闻率土皆王民，远民何疎近何亲。","愿推此惠及天下，无远无近同欣欣。","吴兴山中罢榷茗，鄱阳坑里休封银。","天涯地角无禁利，熙熙同似昆明春。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22056":["新乐府 城盐州\t美圣谟而诮边将也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["城盐州，城盐州，城在五原原上头。","蕃东节度鉢阐布，忽见新城当要路。","金鸟飞传赞普闻，建牙传箭集羣臣。","君臣赬面有忧色，皆言勿谓唐无人。","自筑盐州十余载，左衽毡裘不犯塞。","昼牧牛羊夜捉生，长去新城百里外。","诸边急警劳戍人，唯此一道无烟尘。","灵夏潜安谁复辨，秦原闇通何处见。","鄜州驿路好马来，长安药肆黄蓍贱。","城盐州，盐州未城天子忧。","德宗按图自定计，非关将略与庙谋。","吾闻高宗中宗世，北虏猖狂最难制。","韩公创筑受降城，三城鼎峙屯汉兵。","东西亘绝数千里，耳冷不闻胡马声。","如今边将非无策，心笑韩公筑城壁。","相看养寇爲身谋，各握强兵固恩泽。","愿分今日边将恩，褒赠韩公封子孙。","谁能将此盐州曲，飜作歌词闻至尊。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22057":["新乐府 道州民\t美臣遇明主也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["道州民，多侏儒，长者不过三尺余。","市作矮奴年进送，号爲道州任土贡。","任土贡，宁若斯。","不闻使人生别离，老翁哭孙母哭儿。","一自阳城来守郡，不进矮奴频诏问。","城云臣按六典书，任土贡有不贡无。","道州水土所生者，只有矮民无矮奴。","吾君感悟玺书下，岁贡矮奴宜悉罢。","道州民，老者幼者何欣欣。","父兄子弟始相保，从此得作良人身。","道州民，民到于今受其赐，欲说使君先下泪。","仍恐儿孙忘使君，生男多以阳爲字。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22058":["新乐府 驯犀\t\t感爲政之难终也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["驯犀驯犀通天犀，躯貌骇人角骇鸡。","海蛮闻有明天子，驱犀乘传来万里。","一朝得谒大明宫，欢呼拜舞自论功。","五年驯养始堪献，六译语言方得通。","上嘉人兽俱来远，蛮馆四方犀入苑。","秣以瑶刍鏁以金，故乡迢遰君门深。","海鸟不知钟鼓乐，池鱼空结江湖心。","驯犀生处南方热，秋无白露冬无雪。","一入上林三四年，又逢今岁苦寒月。","饮冰卧霰苦蜷局，角骨冻伤鳞甲蹜。","驯犀死，蛮儿啼，向阙再拜颜色低。","奏乞生归本国去，恐身冻死似驯犀。","君不见建中初，驯象生还放林邑。","君不见贞元年末，驯犀冻死蛮儿泣。","所嗟建中异贞元，象生犀死何足言。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22059":["新乐府 五弦弹\t恶郑之夺雅也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["五弦弹，五弦弹，听者倾耳心寥寥。","赵璧知君入骨爱，五弦一一爲君调。","第一第二弦索索，秋风拂松疎韵落。","第三第四弦泠泠，夜鹤忆子笼中鸣。","第五弦声最掩抑，陇水冻咽流不得。","五弦竝奏君试听，凄凄切切复铮铮。","铁击珊瑚一两曲，冰泻玉盘千万声。","铁声杀，冰声寒。","杀声入耳肤血憯，寒气中人肌骨酸。","曲终声尽欲半日，四坐相对愁无言。","座中有一远方士，唧唧咨咨声不已。","自叹今朝初得闻，始知孤负平生耳。","唯忧赵璧白发生，老死人间无此声。","远方士，尔听五弦信爲美，吾闻正始之音不如是。","正始之音其若何，朱弦疏越清庙歌。","一弹一唱再三叹，曲澹节稀声不多。","融融曳曳召元气，听之不觉心平和。","人情重今多贱古，古琴有弦人不抚。","更从赵璧艺成来，二十五弦不如五。"],"",[["古评·《唐诗镜》","掩抑悲壮"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_22060":["新乐府 蛮子朝\t刺将骄而相备位也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["蛮子朝，泛皮船兮渡绳桥，来自巂州道路遥。","入界先经蜀川过，蜀将收功先表贺。","臣闻云南六诏蛮，东连牂牁西连蕃。","六诏星居初琐碎，合爲一诏渐强大。","开元皇帝虽圣神，唯蛮倔强不来宾。","鲜于仲通六万卒，征蛮一阵全军没。","至今西洱河岸边，箭孔刀痕满枯骨。","谁知今日慕华风，不劳一人蛮自通。","诚由陛下休明德，亦赖微臣诱谕功。","德宗省表知如此，笑令中使迎蛮子。","蛮子导从者谁何，摩挲俗羽双隈伽。","清平官持赤藤杖，大将军系金呿喈。","异牟寻男寻合劝，特敕召对延英殿。","上心贵在怀远蛮，引临玉座近天颜。","冕旒不垂亲劳倈，赐衣赐食移时对。","移时对，不可得，大臣相看有羡色。","可怜宰相拖紫佩金章，朝日唯闻对一刻。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22061":["新乐府 骠国乐\t欲王化之先迩後远也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["骠国乐，骠国乐，出自大海西南角。","雍羌之子舒难陀，来献南音奉正朔。","德宗立仗御紫庭，黈纩不塞爲尔听。","玉螺一吹椎髻耸，铜鼓一击文身踊。","珠缨炫转星宿摇，花鬘斗薮龙蛇动。","曲终王子啓圣人，臣父愿爲唐外臣。","左右欢呼何翕习，至尊德广之所及。","须臾百辟诣合门，俯伏拜表贺至尊。","伏见骠人献新乐，请书国史传子孙。","时有击壤老农父，暗测君心闲独语。","闻君政化甚圣明，欲感人心致太平。","感人在近不在远，太平由实非由声。","观身理国国可济，君如心兮民如体。","体生疾苦心憯凄，民得和平君恺悌。","贞元之民若未安，骠乐虽闻君不欢。","贞元之民苟无病，骠乐不来君亦圣。","骠乐骠乐徒喧喧，不如闻此刍荛言。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22062":["新乐府 缚戎人\t达穷民之情也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["缚戎人，缚戎人，耳穿面破驱入秦。","天子矜怜不忍杀，诏徙东南吴与越。","黄衣小使录姓名，领出长安乘递行。","身被金创面多瘠，扶病徒行日一驿。","朝餐饥渴费杯盘，夜卧腥臊汚牀席。","忽逢江水忆交河，垂手齐声呜咽歌。","其中一虏语诸虏，尔苦非多我苦多。","同伴行人因借问，欲说喉中气愤愤。","自云乡管本凉原，大历年中没落蕃。","一落蕃中四十载，遣着皮裘系毛带。","唯许正朝服汉仪，敛衣整巾潜泪垂。","誓心密定归乡计，不使蕃中妻子知。","暗思幸有残筋力，更恐年衰归不得。","蕃候严兵鸟不飞，脱身冒死奔逃归。","昼伏宵行经大漠，云阴月黑风沙恶。","惊藏青冢寒草疎，偷渡黄河夜冰薄。","忽闻汉军鼙鼓声，路傍走出再拜迎。","游骑不听能汉语，将军遂缚作蕃生。","配向东南卑湿地，定无存恤空防备。","念此吞声仰诉天，若爲辛苦度残年。","凉原乡井不得见，胡地妻儿虚弃捐。","没蕃被囚思汉土，归汉被劫爲蕃虏。","早知如此悔归来，两地宁如一处苦。","缚戎人，戎人之中我苦辛。","自古此冤应未有，汉心汉语吐蕃身。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22063":["新乐府 骊宫高\t美天子重惜人之财力也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["高高骊山上有宫，朱楼紫殿三四重。","迟迟兮春日，玉甃暖兮温泉溢。","嫋嫋兮秋风，山蝉鸣兮宫树红。","翠华不来岁月久，墙有衣兮瓦有松。","吾君在位已五载，何不一幸乎其中？","西去都门几多地，吾君不游有深意。","一人出兮不容易，六宫从兮百司备。","八十一车千万骑，朝有宴饫暮有赐。","中人之产数百家，未足充君一日费。","吾君修己人不知，不自逸兮不自嬉。","吾君爱人人不识，不伤财兮不伤力。","骊宫高兮高入云，君之来兮爲一身，君之不来兮爲万人。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22064":["新乐府 百链镜\t辨皇王鉴也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["百链镜，熔范非常规，日辰处所灵且只。","江心波上舟中铸，五月五日日午时。","琼粉金膏磨莹已，化爲一片秋潭水。","镜成将献蓬莱宫，扬州长吏手自封。","人间臣妾不合照，背有九五飞天龙。","人人呼爲天子镜，我有一言闻太宗。","太宗常以人爲镜，鉴古鉴今不鉴容。","四海安危居掌内，百王治乱悬心中。","乃知天子别有镜，不是扬州百链铜。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22065":["新乐府 青石\t\t激忠烈也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["青石出自蓝田山，兼车运载来长安。","工人磨琢欲何用，石不能言我代言。","不愿作人家墓前神道碣，坟土未乾名已灭。","不愿作官家道旁德政碑，不镌实录镌虚辞。","愿爲颜氏段氏碑，雕镂太尉与太师。","刻此两片坚贞质，状彼二人忠烈姿。","义心如石屹不转，死节如石确不移。","如观奋击朱泚日，似见叱诃希烈时。","各於其上题名諡，一置高山一沈水。","陵谷虽迁碑独存，骨化爲尘名不死。","长使不忠不烈臣，观碑改节慕爲人。","慕爲人，劝事君。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22066":["新乐府 两朱阁\t刺佛寺寖多也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["两朱阁，南北相对起。","借问何人家，贞元双帝子。","帝子吹箫双得仙，五云飘颻飞上天。","第宅亭台不将去，化爲佛寺在人间。","妆合伎楼何寂静，柳似舞腰池似镜。","花落黄昏悄悄时，不闻歌吹闻钟磬。","寺门敕牓金字书，尼院佛庭宽有余。","青苔明月多闲地，比屋疲人无处居。","忆昨平阳宅初置，吞幷平人几家地。","仙去双双作梵宫，渐恐人间尽爲寺。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22067":["新乐府 西凉伎\t刺封疆之臣也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["西凉伎，假面胡人假狮子。","刻木爲头丝作尾，金镀眼睛银帖齿。","奋迅毛衣摆双耳，如从流沙来万里。","紫髯深目两胡儿，鼓舞跳梁前致辞。","应似凉州未陷日，安西都护进来时。","须臾云得新消息，安西路绝归不得。","泣向狮子涕双垂，凉州陷没知不知。","狮子回头向西望，哀吼一声观者悲。","贞元边将爱此曲，醉坐笑看看不足。","娱宾犒士宴监军，狮子胡儿长在目。","有一征夫年七十，见弄凉州低面泣。","泣罢敛手白将军，主忧臣辱昔所闻。","自从天宝兵戈起，犬戎日夜吞西鄙。","凉州陷来四十年，河陇侵将七千里。","平时安西万里疆，今日边防在凤翔。","缘边空屯十万卒，饱食温衣闲过日。","遗民肠断在凉州，将卒相看无意收。","天子每思长痛惜，将军欲说合慙羞。","奈何仍看西凉伎，取笑资欢无所媿。","纵无智力未能收，忍取西凉弄爲戏。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22068":["新乐府 八骏图\t戒奇物惩佚游也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["穆王八骏天马驹，後人爱之写爲图。","背如龙兮颈如象，骨耸筋高脂肉壮。","日行万里疾如飞，穆王独乘何所之。","四荒八极蹋欲徧，三十二蹄无歇时。","属车轴折趁不及，黄屋草生弃若遗。","瑶池西赴王母宴，七庙经年不亲荐。","璧台南与盛姬游，明堂不复朝诸侯。","白云黄竹歌声动，一人荒乐万人愁。","周从后稷至文武，积德累功世勤苦。","岂知才及四代孙，心轻王业如灰土。","由来尤物不在大，能荡君心则爲害。","文帝却之不肯乘，千里马去汉道兴。","穆王得之不爲戒，八骏驹来周室坏。","至今此物尚称珍，不知房星之精下爲怪。","八骏图，君莫爱。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22069":["新乐府 涧底松\t念寒儁也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["有松百尺大十围，生在涧底寒且卑。","涧深山险人路绝，老死不逢工度之。","天子明堂欠梁木，此求彼有两不知。","谁喻苍苍造物意，但与之材不与地。","金张世禄原宪贫，牛衣寒贱貂蝉贵。","貂蝉与牛衣，高下虽有殊。","高者未必贤，下者未必愚。","君不见沈沈海底生珊瑚，历历天上种白榆。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22070":["新乐府 牡丹芳\t美天子忧农也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["牡丹芳，牡丹芳，黄金蘂绽红玉房。","千片赤英霞烂烂，百枝绦点灯煌煌。","照地初开锦绣段，当风不结兰麝囊。","仙人琪树白无色，王母桃花小不香。","宿露轻盈泛紫艳，朝阳照耀生红光。","红紫二色间深浅，向背万态随低昂。","映叶多情隐羞面，卧丛无力含醉妆。","低娇笑容疑掩口，凝思怨人如断肠。","穠姿贵彩信奇绝，杂卉乱花无比方。","石竹金钱何细碎，芙蓉芍药苦寻常。","遂使王公与乡士，游花冠盖日相望。","庳车輭轝贵公主，香衫细马豪家郎。","卫公宅静闭东院，西明寺深开北廊。","戏蝶双舞看人久，残莺一声春日长。","共愁日照芳难驻，仍张帷幕垂阴凉。","花开花落二十日，一城之人皆若狂。","三代以还文胜质，人心重华不重实。","重华直至牡丹芳，其来有渐非今日。","元和天子忧农桑，恤下动天天降祥。","去岁嘉禾生九穗，田中寂莫无人至。","今年瑞麦分两岐，君心独喜无人知。","无人知，可叹息，我愿暂求造化力。","减却牡丹妖艳色，少回乡士爱花心，同似吾君忧稼穑。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22071":["新乐府 红线毯\t忧蚕桑之费也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["红线毯，择蠒缲丝清水煮。","拣丝练线红蓝染，染爲红线红於蓝。","织作披香殿上毯，披香殿广十丈余。","红线织成可殿铺，彩丝茸茸香拂拂。","线輭花虚不胜物，美人蹋上歌舞来。","罗韤绣鞋随步没，太原毯涩毳缕硬。","蜀都褥薄锦花冷，不如此毯温且柔。","年年十月来宣州，宣城太守加样织。","自谓爲臣能竭力，百夫同担进宫中。","线厚丝多卷不得，宣城太守知不知。","一丈毯，千两丝，地不知寒人要暖，少夺人衣作地衣。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22072":["新乐府 杜陵叟\t伤农夫之困也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["杜陵叟，杜陵居，岁种薄田一顷余。","三月无雨旱风起，麦苗不秀多黄死。","九月降霜秋早寒，禾穗未熟皆青乾。","长吏明知不申破，急敛暴徵求考课。","典桑卖地纳官租，明年衣食将何如。","剥我身上帛，夺我口中粟。","虐人害物即豺狼，何必钩爪锯牙食人肉。","不知何人奏皇帝，帝心恻隐知人弊。","白麻纸上书德音，京畿尽放今年税。","昨日里胥方到门，手持尺牒牓乡村。","十家租税九家毕，虚受吾君蠲免恩。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22073":["新乐府 缭绫\t\t念女工之劳也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["缭绫缭绫何所似，不似罗绡与纨绮。","应似天台山上月明前，四十五尺瀑布泉。","中有文章又奇绝，地铺白烟花簇雪。","织者何人衣者谁，越溪寒女汉宫姬。","去年中使宣口敕，天上取样人间织。","织爲云外秋雁行，染作江南春水色。","广裁衫袖长制帬，金斗熨波刀翦纹。","异彩奇文相隐映，转侧看花花不定。","昭阳舞人恩正深，春衣一对直千金。","汗沾粉污不再着，曳土蹋泥无惜心。","缭绫织成费功绩，莫比寻常缯与帛。","丝细缲多女手疼，扎扎千声不盈尺。","昭阳殿里歌舞人，若见织时应也惜。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22074":["新乐府 卖炭翁\t苦官市也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["卖炭翁，伐薪烧炭南山中。","满面尘灰烟火色，两鬓苍苍十指黑。","卖炭得钱何所营，身上衣裳口中食。","可怜身上衣正单，心忧炭贱愿天寒。","夜来城上一尺雪，晓驾炭车辗冰辙。","牛困人饥日已高，市南门外泥中歇。","翩翩两骑来是谁，黄衣使者白衫儿。","手把文书口称敕，回车叱牛牵向北。","一车炭，千余斤，官使驱将惜不得。","半匹红纱一丈绫，系向牛头充炭直。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22075":["新乐府 母别子\t刺新间旧也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["母别子，子别母，白日无光哭声苦。","关西骠骑大将军，去年破虏新策勳。","敕赐金钱二百万，洛阳迎得如花人。","新人迎来旧人弃，掌上莲花眼中刺。","迎新弃旧未足悲，悲在君家留两儿。","一始扶行一初坐，坐啼行哭牵人衣。","以汝夫妇新燕婉，使我母子生别离。","不如林中乌与鹊，母不失雏雄伴雌。","应似园中桃李树，花落随风子在枝。","新人新人听我语，洛阳无限红楼女。","但愿将军重立功，更有新人胜於汝。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22076":["新乐府 阴山道\t疾贪虏也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["阴山道，阴山道，纥逻敦肥水泉好。","每至戎人送马时，道旁千里无纤草。","草尽泉枯马病羸，飞龙但印骨与皮。","五十匹缣易一匹，缣去马来无了日。","养无所用去非宜，每岁死伤十六七。","缣丝不足女工苦，疎织短截充匹数。","藕丝蛛网三丈余，回纥诉称无用处。","咸安公主号可敦，远爲可汗频奏论。","元和二年下新敕，内出金帛酬马直。","仍诏江淮马价缣，从此不令疎短织。","合罗将军呼万岁，捧授金银与缣彩。","谁知黠虏啓贪心，明年马多来一倍。","缣渐好，马渐多，阴山虏，奈尔何。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22077":["新乐府 时世妆\t儆戎也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["时世妆，时世妆，出自城中传四方。","时世流行无远近，顋不施朱面无粉。","乌膏注唇唇似泥，双眉画作八字低。","妍媸黑白失本态，妆成尽似含悲啼。","圆鬟无鬓堆髻样，斜红不晕赭面状。","昔闻被发伊川中，辛有见之知有戎。","元和妆梳君记取，髻堆面赭非华风。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22078":["新乐府 李夫人\t鉴嬖惑也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["汉武帝，初丧李夫人。","夫人病时不肯别，死後留得生前恩。","君恩不尽念未已，甘泉殿里令写真。","丹青画出竟何益，不言不笑愁杀人。","又令方士合灵药，玉釜煎链金鑪焚。","九华帐深夜悄悄，反魂香降夫人魂。","夫人之魂在何许，香烟引到焚香处。","既来何苦不须臾，缥缈悠扬还灭去。","去何速兮来何迟，是耶非耶两不知。","翠蛾髣髴平生貌，不似昭阳寝疾时。","魂之不来君心苦，魂之来兮君亦悲。","背灯隔帐不得语，安用暂来还见违。","伤心不独汉武帝，自古及今皆若斯。","君不见穆王三日哭，重璧台前伤盛姬。","又不见泰陵一掬泪，马嵬坡下念杨妃。","纵令妍姿艳质化爲土，此恨长在无销期。","生亦惑，死亦惑，尤物惑人忘不得。","人非木石皆有情，不如不遇倾城色。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22079":["新乐府 陵园妾\t怜幽闭也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["陵园妾，颜色如花命如叶。","命如叶薄将奈何，一奉寝宫年月多。","年月多，时光换，春愁秋思知何限。","青丝发落丛鬓疎，红玉肤销系帬慢。","忆昔宫中被妬猜，因谗得罪配陵来。","老母啼呼趁车别，中官监送鏁门回。","山宫一闭无开日，未死此身不令出。","松门到晓月裴回，柏城尽日风萧瑟。","松门柏城幽闭深，闻蝉听燕感光阴。","眼看菊蘂重阳泪，手把棃花寒食心。","把花掩泪无人见，绿芜墙绕青苔院。","四季徒支妆粉钱，三朝不识君王面。","遥想六宫奉至尊，宣徽雪夜浴堂春。","雨露之恩不及者，犹闻不啻三千人。","三千人，我尔君恩何厚薄。","愿令轮转直陵园，三岁一来均苦乐。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22080":["新乐府 盐商妇\t恶幸人也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["盐商妇，多金帛，不事田农与蚕绩。","南北东西不失家，风水爲乡船作宅。","本是扬州小家女，嫁得西江大商客。","绿鬟富去金钗多，皓腕肥来银钏窄。","前呼苍头後叱婢，问尔因何得如此。","壻作盐商十五年，不属州县属天子。","每年盐利入官时，少入官家多入私。","官家利薄私家厚，盐铁尚书远不知。","何况江头鱼米贱，红脍黄橙香稻饭。","饱食浓妆倚柁楼，两朵红顋花欲绽。","盐商妇，有幸嫁盐商。","终朝美饭食，终岁好衣裳。","好衣美食来何处，亦须慙媿桑弘羊。","桑弘羊，死已久，不独汉时今亦有。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22081":["新乐府 杏爲梁\t刺居处僭也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["杏爲梁，桂爲柱，何人堂室李开府。","碧砌红轩色未乾，去年身殁今移主。","高其墙，大其门，谁家第宅卢将军。","素泥朱版光未灭，今日官收别赐人。","开府之堂将军宅，造未成时头已白。","逆旅重居逆旅中，心是主人身是客。","更有愚夫念身後，心虽甚长计非久。","穷奢极丽越规模，付子传孙令保守。","莫教门外过客闻，抚掌回头笑杀君。","君不见马家宅，尚犹存，宅门题作奉诚园。","君不见魏家宅，属他人，诏赎赐还五代孙。","俭存奢失今在目，安用高墙围大屋。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22082":["新乐府 井底引银缾\t止淫奔也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["井底引银缾，银缾欲上丝绳绝。","石上磨玉簪，玉簪欲成中央折。","缾沈簪折知奈何，似妾今朝与君别。","忆昔在家爲女时，人言举动有殊姿。","婵娟两鬓秋蝉翼，宛转双蛾远山色。","笑随戏伴後园中，此时与君未相识。","妾弄青梅凭短墙，君骑白马傍垂杨。","墙头马上遥相顾，一见知君即断肠。","知君断肠共君语，君指南山松柏树。","感君松柏化爲心，闇合双鬟逐君去。","到君家舍五六年，君家大人频有言。","聘则爲妻奔是妾，不堪主祀奉苹蘩。","终知君家不可住，其奈出门无去处。","岂无父母在高堂，亦有亲情满故乡。","潜来更不通消息，今日悲羞归不得。","爲君一日恩，误妾百年身。","寄言痴小人家女，慎勿将身轻许人。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22083":["新乐府 官牛\t\t讽执政也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["官牛官牛驾官车，滻水岸边般载沙。","一石沙，几斤重，朝载暮载将何用。","载向五门官道西，绿槐阴下铺沙堤。","昨来新拜右丞相，恐怕泥涂汚马蹄。","右丞相，马蹄蹋沙虽净洁，牛领牵车欲流血。","右丞相，但能济人治国调阴阳，官牛领穿亦无妨。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22084":["新乐府 紫毫笔\t讥失职也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["紫毫笔，尖如锥兮利如刀。","江南石上有老兔，吃竹饮泉生紫毫。","宣城之人采爲笔，千万毛中拣一毫。","毫虽轻，功甚重，管勒工名充岁贡。","君兮臣兮勿轻用，勿轻用，将何如。","愿赐东西府御史，愿颁左右台起居。","搦管趋入黄金阙，抽毫立在白玉除。","臣有奸邪正衙奏，君有动言直笔书。","起居郎，侍御史，尔知紫毫不易致。","每岁宣城进笔时，紫毫之价如金贵。","慎勿空将弹失仪，慎勿空将录制词。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22085":["新乐府 隋堤柳\t悯亡国也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["隋堤柳，岁久年深尽衰朽。","风飘飘兮雨萧萧，三株两株汴河口。","老枝病叶愁杀人，曾经大业年中春。","大业年中炀天子，种柳成行夹流水。","西自黄河东至淮，绿阴一千三百里。","大业末年春暮月，柳色如烟絮如雪。","南幸江都恣佚游，应将此柳系龙舟。","紫髯郎将护锦缆，青娥御史直迷楼。","海内财力此时竭，舟中歌笑何日休。","上荒下困势不久，宗社之危如缀旒。","炀天子，自言福祚长无穷，岂知皇子封酅公。","龙舟未过彭城合，义旗已入长安宫。","萧墙祸生人事变，晏驾不得归秦中。","土坟数尺何处葬，吴公台下多悲风。","二百年来汴河路，沙草和烟朝复暮。","後王何以鉴前王，请看隋堤亡国树。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22086":["新乐府 草茫茫\t惩厚葬也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["草茫茫，土苍苍，苍苍茫茫在何处，骊山脚下秦皇墓。","墓中下涸二重泉，当时自以爲深固。","下流水银象江海，上缀珠光作乌兔。","别爲天地於其间，拟将富贵随身去。","一朝盗掘坟陵破，龙椁神堂三月火。","可怜宝玉归人间，暂借泉中买身祸。","奢者狼藉俭者安，一凶一吉在眼前。","凭君回首向南望，汉文葬在霸陵原。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22087":["新乐府 古冢狐\t戒艳色也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["古冢狐，妖且老，化爲妇人颜色好。","头变云鬟面变妆，大尾曳作长红裳。","徐徐行傍荒村路，日欲暮时人静处。","或歌或舞或悲啼，翠眉不举花颜低。","忽然一笑千万态，见者十人八九迷。","假色迷人犹若是，真色迷人应过此。","彼真此假俱迷人，人心恶假贵重真。","狐假女妖害犹浅，一朝一夕迷人眼。","女爲狐媚害即深，日长月增溺人心。","何况褒妲之色善蛊惑，能丧人家覆人国。","君看爲害浅深间，岂将假色同真色。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22088":["新乐府 黑潭龙\t疾贪吏也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["黑潭水深黑如墨，传有神龙人不识。","潭上架屋官立祠，龙不能神人神之。","丰凶水旱与疾疫，乡里皆言龙所爲。","家家养豚漉清酒，朝祈暮赛依巫口。","神之来兮风飘飘，纸钱动兮锦伞摇。","神之去兮风亦静，香火灭兮杯盘冷。","肉堆潭岸石，酒泼庙前草。","不知龙神享几多，林鼠山狐长醉饱。","狐何幸，豚何辜，年年杀豚将餧狐。","狐假龙神食豚尽，九重泉底龙知无。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22089":["新乐府 天可度\t恶诈人也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["天可度，地可量，唯有人心不可防。","但见丹诚赤如血，谁知僞言巧似簧。","劝君掩鼻君莫掩，使君夫妇爲参商。","劝君掇蠭君莫掇，使君父子成豺狼。","海底鱼兮天上鸟，高可射兮深可钓。","唯有人心相对时，咫尺之间不能料。","君不见李义府之辈笑欣欣，笑中有刀潜杀人。","阴阳神变皆可测，不测人间笑是瞋。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22090":["新乐府 秦吉了\t哀冤民也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["秦吉了，出南中，彩毛青黑花颈红。","耳聪心慧舌端巧，鸟语人言无不通。","昨日长爪鸢，今朝大觜乌。","鸢捎乳燕一窠覆，乌琢母鸡双眼枯。","鸡号堕地燕惊去，然後拾卵攫其雏。","岂无鵰与鹗，嗉中肉饱不肯搏。","亦有鸾鹤羣，闲立高扬如不闻。","秦吉了，人云尔是能言鸟。","岂不见鸡燕之冤苦，吾闻凤皇百鸟主。","尔竟不爲凤皇之前致一言，安用噪噪闲言语。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22091":["新乐府 鵶九劒\t思决壅也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["欧冶子死千年後，精灵闇授张鵶九。","鵶九铸劒吴山中，天与日时神借功。","金铁腾精火飜焰，踊跃求爲镆鎁劒。","劒成未试十余年，有客持金买一观。","谁知闭匣长思用，三尺青蛇不肯蟠。","客有心，劒无口，客代劒言告鵶九。","君勿矜我玉可切，君勿夸我钟可刜。","不如持我决浮云，无令漫漫蔽白日。","爲君使无私之光及万物，蛰虫昭苏萌草出。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22092":["新乐府 采诗官\t监前王乱亡之由也","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["采诗官，采诗听歌导人言。","言者无罪闻者诫，下流上通上下泰。","周灭秦兴至隋氏，十代采诗官不置。","郊庙登歌赞君美，乐府艳词悦君意。","若求兴谕规刺言，万句千章无一字。","不是章句无规刺，渐及朝廷绝讽议。","诤臣杜口爲冗员，谏鼓高悬作虚器。","一人负扆常端默，百辟入门两自媚。","夕郎所贺皆德音，春官每奏唯祥瑞。","君之堂兮千里远，君之门兮九重閟。","君耳唯闻堂上言，君眼不见门前事。","贪吏害民无所忌，奸臣蔽君无所畏。","君不见厉王胡亥之末年，羣臣有利君无利。","君兮君兮愿听此，欲开壅蔽达人情。","先向歌诗求讽刺。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22093":["常乐里闲居偶题十六韵兼寄刘十五公舆王十一起吕二炅吕四熲崔十八玄亮元九稹刘三十二敦质张十五仲元时爲校书郎","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["帝都名利场，鸡鸣无安居。","独有嬾慢者，日高头未梳。","工拙性不同，进退迹遂殊。","幸逢太平代，天子好文儒。","小才难大用，典校在秘书。","三旬两入省，因得养顽疎。","茅屋四五间，一马二仆夫。","俸钱万六千，月给亦有余。","既无衣食牵，亦少人事拘。","遂使少年心，日日常晏如。","勿言无知己，躁静各有徒。","兰台七八人，出处与之俱。","旬时阻谈笑，旦夕望轩车。","谁能雠校闲，解带卧吾庐。","窗前有竹玩，门外有酒酤。","何以待君子，数竿对一壶。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22094":["荅元八宗简同游曲江後明日见赠","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["长安千万人，出门各有营。","唯我与夫子，信马悠悠行。","行到曲江头，反照草树明。","南山好颜色，病客有心情。","水禽飜白羽，风荷嫋翠茎。","何必沧浪去，即此可濯缨。","时景不重来，赏心难再幷。","坐愁红尘里，夕鼓冬冬声。","归来经一宿，世虑稍复生。","赖闻瑶华唱，再得尘襟清。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22095":["感时","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["朝见日上天，暮见日入地。","不觉明镜中，忽年三十四。","勿言身未老，冉冉行将至。","白发虽未生，朱颜已先悴。","人生讵几何，在世犹如寄。","虽有七十期，十人无一二。","今我犹未悟，往往不适意。","胡爲方寸间，不贮浩然气。","贫贱非不恶，道在何足避。","富贵非不爱，时来当自致。","所以达人心，外物不能累。","唯当饮美酒，终日陶陶醉。","斯言胜金玉，佩服无失坠。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22096":["首夏同诸校正游开元观因宿玩月","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["我与二三子，策名在京师。","官小无职事，闲於爲客时。","沈沈道观中，心赏期在兹。","到门车马回，入院巾杖随。","清和四月初，树木正华滋。","风清新叶影，鸟恋残花枝。","向夕天又晴，东南余霞披。","置酒西廊下，待月杯行迟。","须臾金魄生，若与吾徒期。","光华一照耀，殿角相参差。","终夜清景前，笑歌不知疲。","长安名利地，此兴几人知。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22097":["永崇里观居","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["季夏中气侯，烦暑自此收。","萧飒风雨天，蝉声暮啾啾。","永崇里巷静，华阳观院幽。","轩车不到处，满地槐花秋。","年光忽冉冉，世事本悠悠。","何必待衰老，然後悟浮休。","真隐岂长远，至道在冥搜。","身虽世界住，心与虚无游。","朝饥有蔬食，夜寒有布裘。","幸免冻与馁，此外复何求。","寡慾虽少病，乐天心不忧。","何以明吾志，周易在牀头。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22098":["早送举人入试","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["夙驾送举人，东方犹未明。","自谓出太早，已有车马行。","骑火高低影，街鼓参差声。","可怜早朝者，相看意气生。","日出尘埃飞，羣动互营营。","营营各何求，无非利与名。","而我常晏起，虚住长安城。","春深官又满，日有归山情。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22099":["招王质夫","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["濯足云水客，折腰簪笏身。","諠闲迹相背，十里别经旬。","忽因乘逸兴，莫惜访嚣尘。","窗前故栽竹，与君爲主人。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22100":["祗役骆口因与王质夫同游秋山偶题三韵","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["石拥百泉合，云破千峰开。","平生烟霞侣，此地重裴回。","今日勤王意，一半爲山来。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22101":["见萧侍御忆旧山草堂诗因以继和","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["琢玉以爲架，缀珠以爲笼。","玉架绊野鹤，珠笼鏁冥鸿。","鸿思云外天，鹤忆松上风。","珠玉信爲美，鸟不恋其中。","台中萧侍御，心与鸿鹤同。","晚起慵冠豸，闲行厌避骢。","昨见忆山诗，诗思浩无穷。","归梦杳何处，旧居茫水东。","秋闲杉桂林，春老芝术丛。","自云别山後，离抱常忡忡。","衣绣非不荣，持宪非不雄。","所乐不在此，怅望草堂空。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22102":["病假中南亭闲望","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["欹沈不视事，两日门掩关。","始知吏役身，不病不得闲。","闲意不在远，小亭方丈间。","西檐竹梢上，坐见太白山。","遥媿峰上云，对此尘中颜。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22103":["仙游寺独宿","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["沙鹤上阶立，潭月当户开。","此中留我宿，两夜不能回。","幸与静境遇，喜无归侣催。","从今独游後，不拟共人来。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22104":["前庭凉夜","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["露簟色似玉，风幌影如波。","坐愁树叶落，中庭明月多。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22105":["官舍小亭闲望","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["风竹散清韵，烟槐凝绿姿。","日高人吏去，闲坐在茅茨。","葛衣御时暑，蔬饭疗朝饥。","持此聊自足，心力少营爲。","亭上独吟罢，眼前无事时。","数峰太白雪，一卷陶潜诗。","人心各自是，我是良在兹。","回谢争名客，甘从君所嗤。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22106":["早秋独夜","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["井梧凉叶动，邻杵秋声发。","独向檐下眠，觉来半牀月。"],"王昌龄诗金井梧桐秋叶黄杜甫诗清秋幕府井梧寒鲍照诗紫兰花已歇碧梧叶方稀周𢎞譲诗木叶动秋声韦应物诗暗窓凉",[["古注·《御选唐诗》","王昌龄诗金井梧桐秋叶黄杜甫诗清秋幕府井梧寒鲍照诗紫兰花已歇碧梧叶方稀周𢎞譲诗木叶动秋声韦应物诗暗窓凉叶动"],["古注·《御选唐诗》","何逊诗砧杵鸣四隣储光羲诗秋山响砧杵刘孝威诗织素起秋声"],["古注·《御选唐诗》","范云诗春草醉春烟深闺人独眠刘长卿诗楼上花枝笑独眠陶潜诗繿缕茅檐下祖鸿勲书檐下流烟共霄气而舒巻"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《御选唐诗》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/御選唐詩_(四庫全書本)）"]],"open_22107":["听弹古渌水","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["闻君古渌水，使我心和平。","欲识慢流意，爲听疎泛声。","西窗竹阴下，竟日有余清。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22108":["松斋自题","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["非老亦非少，年过三纪余。","非贱亦非贵，朝登一命初。","才小分易足，心宽体长舒。","充肠皆美食，容膝即安居。","况此松斋下，一琴数帙书。","书不求甚解，琴聊以自娱。","夜直入君门，晚归卧吾庐。","形骸委顺动，方寸付空虚。","持此将过日，自然多晏如。","昏昏复默默，非智亦非愚。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22109":["冬夜与钱员外同直禁中","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["夜深草诏罢，霜月凄凛凛。","欲卧暖残杯，灯前相对饮。","连铺青缣被，对置通中枕。","髣髴百余宵，与君同此寝。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22110":["和钱员外禁中夙兴见示","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["窗白星汉曙，窗暖灯火余。","坐卷朱里幕，看封紫泥书。","窅窅钟漏尽，曈曈霞景初。","楼台红照曜，松竹青扶疎。","君爱此时好，回头特谓余。","不知上清界，晓景复何如。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22111":["夏日独直寄萧侍御","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["宪台文法地，翰林清切司。","鹰猜课野鹤，骥德责山麋。","课责虽不同，同归非所宜。","是以方寸内，忽忽暗相思。","夏日独上直，日长何所爲。","澹然无他念，虚静是吾师。","形委有事牵，心与无事期。","中臆一以旷，外累都若遗。","地贵身不觉，意闲境来随。","但对松与竹，如在山中时。","情性聊自适，吟咏偶成诗。","此意非夫子，余人多不知。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22112":["松声","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["月好好独坐，双松在前轩。","西南微风来，潜入枝叶间。","萧寥发爲声，半夜明月前。","寒山飒飒雨，秋琴泠泠弦。","一闻涤炎暑，再听破昏烦。","竟夕遂不寐，心体俱翛然。","南陌车马动，西邻歌吹繁。","谁知兹檐下，满耳不爲喧。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22113":["禁中","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["门严九重静，窗幽一室闲。","好是修心处，何必在深山。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22114":["赠吴丹","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["巧者力苦劳，智者心苦忧。","爱君无巧智，终岁闲悠悠。","尝登御史府，亦佐东诸候。","手操纠谬简，心运决胜筹。","宦途似风水，君心如虚舟。","泛然而不有，进退得自由。","今来脱豸冠，时往侍龙楼。","官曹称心静，居处随迹幽。","冬负南荣日，支体甚温柔。","夏卧北窗风，枕席如凉秋。","南山入舍下，酒瓮在牀头。","人间有闲地，何必隐林丘。","顾我愚且昧，劳生殊未休。","一入金门直，星霜三四周。","主恩信难报，近地徒久留。","终当乞闲官，退与夫子游。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22115":["初除户曹喜而言志","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["诏授户曹掾，捧诏感君恩。","感恩非爲己，禄养及吾亲。","弟兄俱簪笏，新妇俨衣巾。","罗列高堂下，拜庆正纷纷。","俸钱四五万，月可奉晨昏。","廪禄二百石，岁可盈仓囷。","喧喧车马来，贺客满我门。","不以我爲贪，知我家内贫。","置酒延贺客，客容亦欢欣。","笑云今日後，不复忧空尊。","荅云如君言，愿君少逡巡。","我有平生志，醉後爲君陈。","人生百岁期，七十有几人。","浮荣及虚位，皆是身之宾。","唯有衣与食，此事粗关身。","苟免饥寒外，余物尽浮云。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22116":["秋居书怀","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["门前少宾客，阶下多松竹。","秋景下西墙，凉风入东屋。","有琴慵不弄，有书闲不读。","尽日方寸中，澹然无所欲。","何须广居处，不用多积蓄。","丈室可容身，斗储可充腹。","况无治道术，坐受官家禄。","不种一株桑，不锄一壠谷。","终朝饱饭餐，卒岁丰衣服。","持此知媿心，自然易爲足。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22117":["禁中晓卧因怀王起居","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["迟迟禁漏尽，悄悄暝鵶喧。","夜雨槐花落，微凉卧北轩。","曙灯残未灭，风帘闲自飜。","每一得静境，思与故人言。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22118":["养拙","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["铁柔不爲劒，木曲不爲辕。","今我亦如此，愚蒙不及门。","甘心谢名利，灭迹归丘园。","坐卧茅茨中，但对琴与尊。","身去缰锁累，耳辞朝市喧。","逍遥无所爲，时窥五千言。","无忧乐性场，寡欲清心源。","始知不才者，可以探道根。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22119":["寄李十一建","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["外事牵我形，外物诱我情。","李君别来久，褊恡从中生。","忆昨访君时，立马扣柴荆。","有时君未起，穉子喜先迎。","连步笑出门，衣飜冠或倾。","埽阶苔纹绿，拂榻藤阴清。","家酝及春熟，园葵乘露烹。","看山东亭坐，待月南原行。","门静唯鸟语，坊远少鼓声。","相对尽日言，不及利与名。","分手来几时，明月三四盈。","别时残花落，及此新蝉鸣。","芳岁忽已晚，离抱怅未平。","岂不思命驾，吏职坐相萦。","前时君有期，访我来山城。","心赏久云阻，言约无自轻。","相去幸非远，走马一日程。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22120":["旅次华州赠袁右丞","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["渭水绿溶溶，华山青崇崇。","山水一何丽，君子在其中。","才与世会合，物随诚感通。","德星降人福，时雨助岁功。","化行人无讼，囹圄千日空。","政顺气亦和，黍稷三年丰。","客自帝城来，驱马出关东。","爱此一郡人，如见太古风。","方今天子心，忧人正忡忡。","安得天下守，尽得如袁公。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22121":["酬杨九弘贞长安病中见寄","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["伏枕君寂寂，折腰我营营。","所嗟经时别，相去一宿程。","携手昨何时，昆明春水平。","离郡来几日，太白夏云生。","之子未得意，贫病客帝城。","贫坚志士节，病长高人情。","隐几自恬澹，闭门无送迎。","龙卧心有待，鹤瘦貌弥清。","清机发爲文，投我如振琼。","何以慰饥渴，捧之吟一声。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22122":["禁中寓直梦游仙游寺","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["西轩草诏暇，松竹深寂寂。","月出清风来，忽似山中夕。","因成西南梦，梦作游仙客。","觉闻宫漏声，犹谓山泉滴。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22123":["赠王山人","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["闻君减寝食，日听神仙说。","闇待非常人，潜求长生诀。","言长本对短，未离生死辙。","假使得长生，才能胜夭折。","松树千年朽，槿花一日歇。","毕竟共虚空，何须夸岁月。","彭殇徒自异，生死终无别。","不如学无生，无生即无灭。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22124":["秋山","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["久病旷心赏，今朝一登山。","山秋云物冷，称我清羸颜。","白石卧可枕，青萝行可攀。","意中如有得，尽日不欲还。","人生无几何，如寄天地间。","心有千载忧，身无一日闲。","何时解尘网，此地来掩关。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22125":["赠能七伦","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["涧松高百寻，四时寒森森。","临风有清韵，向日无曲阴。","如何时俗人，但赏桃李林。","岂不知坚贞，芳馨诱其心。","能生学爲文，气高功亦深。","手中一百篇，句句披沙金。","苦节二十年，无人振陆沈。","今我尚贫贱，徒爲尔知音。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22126":["题杨颖士西亭","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["静得亭上境，远谐尘外踪。","凭轩东南望，鸟灭山重重。","竹露冷烦襟，杉风清病容。","旷然宜真趣，道与心相逢。","即此可遗世，何必蓬壶峰。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22127":["题赠郑秘书徵君石沟溪隐居","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["郑君得自然，虚白生心胸。","吸彼沆瀣精，凝爲冰雪容。","大君贞元初，求贤致时雍。","蒲轮入翠微，迎下天台峰。","赤城别松乔，黄合交夔龙。","俛仰受三命，从容辞九重。","出笼鹤翩翩，归林凤雝雝。","在火辨良玉，经霜识贞松。","新居寄楚山，山碧溪溶溶。","丹竈烧烟煴，黄精花丰茸。","蕙帐夜琴澹，桂尊春酒浓。","时人不到处，苔石无尘踪。","我今何爲者，趋世身龙锺。","不向林壑访，无由朝市逢。","终当解尘缨，卜筑来相从。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22128":["及第後归觐留别诸同年","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["十年常苦学，一上谬成名。","擢第未爲贵，贺亲方始荣。","时辈六七人，送我出帝城。","轩车动行色，丝管举离声。","得意减别恨，半酣轻远程。","翩翩马蹄疾，春日归乡情。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22129":["清夜琴兴","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["月出鸟栖尽，寂然坐空林。","是时心境闲，可以弹素琴。","清泠由木性，恬澹随人心。","心积和平气，木应正始音。","响余羣动息，曲罢秋夜深。","正声感元化，天地清沈沈。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22130":["效陶潜体诗十六首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["不动者厚地，不息者高天。","无穷者日月，长在者山川。","松柏与龟鹤，其寿皆千年。","嗟嗟羣物中，而人独不然。","早出向朝市，暮已归下泉。","形质及寿命，危脆若浮烟。","尧舜与周孔，古来称圣贤。","借问今何在，一去亦不还。","我无不死药，万万随化迁。","所未定知者，修短迟速间。","幸及身健日，当歌一尊前。","何必待人劝，持此自爲欢。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22131":["效陶潜体诗十六首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["翳翳踰月阴，沈沈连日雨。","开帘望天色，黄云暗如土。","行潦毁我墉，疾风坏我宇。","蓬莠生庭院，泥涂失场圃。","村深绝宾客，窗晦无俦侣。","尽日不下牀，跳蛙时入户。","出门无所往，入室还独处。","不以酒自娱，块然与谁语。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22132":["效陶潜体诗十六首 三","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["朝饮一杯酒，冥心合元化。","兀然无所思，日高尚闲卧。","暮读一卷书，会意如嘉话。","欣然有所遇，夜深犹独坐。","又得琴上趣，安弦有余暇。","复多诗中狂，下笔不能罢。","唯兹三四事，持用度昼夜。","所以阴雨中，经旬不出舍。","始悟独往人，心安时亦过。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22133":["效陶潜体诗十六首 四","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["车家采桑妇，雨来苦愁悲。","蔟蚕北堂前，雨冷不成丝。","西家荷锄叟，雨来亦怨咨。","种豆南山下，雨多落爲萁。","而我独何幸，酝酒本无期。","及此多雨日，正遇新熟时。","开缾泻尊中，玉液黄金脂。","持玩已可悦，欢尝有余滋。","一酌发好容，再酌开愁眉。","连延四五酌，酣畅入四肢。","忽然遗我物，谁复分是非。","是时连夕雨，酩酊无所知。","人心苦颠倒，反爲忧者嗤。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22134":["效陶潜体诗十六首 五","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["朝亦独醉歌，暮亦独醉睡。","未尽一壶酒，已成三独醉。","勿嫌饮太少，且喜欢易致。","一杯复两杯，多不过三四。","便得心中适，尽忘身外事。","更复强一杯，陶然遗万累。","一饮一石者，徒以多爲贵。","及其酩酊时，与我亦无异。","笑谢多饮者，酒钱徒自费。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22135":["效陶潜体诗十六首 六","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["天秋无片云，地静无纤尘。","团团新晴月，林外生白轮。","忆昨阴霖天，连连三四旬。","赖逢家酝熟，不觉过朝昏。","私言雨霁後，可以罢余尊。","及对新月色，不醉亦愁人。","牀头残酒榼，欲尽味弥淳。","携置南檐下，举酌自殷勤。","清光入杯杓，白露生衣巾。","乃知阴与晴，安可无此君。","我有乐府诗，成来人未闻。","今宵醉有兴，狂咏惊四邻。","独赏犹复尔，何况有交亲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22136":["效陶潜体诗十六首 七","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["中秋三五夜，明月在前轩。","临觞忽不饮，忆我平生欢。","我有同心人，邈邈崔与钱。","我有忘形友，迢迢李与元。","或飞青云上，或落江湖间。","与我不相见，於今四五年。","我无缩地术，君非驭风仙。","安得明月下，四人来晤言。","良夜信难得，佳期杳无缘。","明月又不驻，渐下西南天。","岂无他时会，惜此清景前。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22137":["效陶潜体诗十六首 八","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["家酝饮已尽，村中无酒酤。","坐愁今夜醒，其奈秋怀何。","有客忽叩门，言语一何佳。","云是南村叟，挈榼来相过。","且喜尊不燥，安问少与多。","重阳虽已过，篱菊有残花。","欢来苦昼短，不觉夕阳斜。","老人[勿]遽起，且待新月华。","客去有余趣，竟夕独酣歌。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22138":["效陶潜体诗十六首 九","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["原生衣百结，颜子食一箪。","欢然乐其志，有以忘饥寒。","今我何人哉，德不及先贤。","衣食幸相属，胡爲不自安。","况兹清渭曲，居处安且闲。","榆柳百余树，茅茨十数间。","寒负檐下日，热濯涧底泉。","日出犹未起，日入已复眠。","西风满村巷，清凉八月天。","但有鸡犬声，不闻车马喧。","时倾一尊酒，坐望东南山。","穉侄初学步，牵衣戏我前。","即此自可乐，庶几颜与原。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22139":["效陶潜体诗十六首 十","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["湛湛尊中酒，有功不自伐。","不伐人不知，我今代其说。","良将临大敌，前驱千万卒。","一箪投河饮，赴死心如一。","壮士磨匕首，勇愤气咆𠷺","一酣忘报雠，四体如无骨。","东海杀孝妇，天旱踰年月。","一酌酹其魂，通宵雨不歇。","咸阳秦狱气，冤痛结爲物。","千岁不肯散，一沃亦销失。","况兹儿女恨，及彼幽忧疾。","快饮无不消，如霜得春日。","方知麴糵灵，万物无与匹。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22140":["效陶潜体诗十六首 十一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["烟霞隔悬圃，风波限瀛州。","我岂不欲往，大海路阻修。","神仙但闻说，灵药不可求。","长生无得者，举世如蜉蝣。","逝者不重回，存者难久留。","踟蹰未死间，何苦怀百忧。","念此忽内热，坐看成白头。","举杯还独饮，顾影自献酬。","心与口相约，未醉勿言休。","今朝不尽醉，知有明朝不。","不见郭门外，累累坟与丘。","月明愁杀人，黄蒿风飕飕。","死者若有知，悔不秉烛游。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22141":["效陶潜体诗十六首 十二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["吾闻浔阳郡，昔有陶徵君。","爱酒不爱名，忧醒不忧贫。","尝爲彭泽令，在官才八旬。","愀然忽不乐，挂印着公门。","口吟归去来，头戴漉酒巾。","人吏留不得，直入故山云。","归来五柳下，还以酒养真。","人间荣与利，摆落如泥尘。","先生去已久，纸墨有遗文。","篇篇劝我饮，此外无所云。","我从老大来，窃慕其爲人。","其他不可及，且傚醉昏昏。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22142":["效陶潜体诗十六首 十三","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楚王疑忠臣，江南放屈平。","晋朝轻高士，林下弃刘伶。","一人常独醉，一人常独醒。","醒者多苦志，醉者多欢情。","欢情信独善，苦志竟何成。","兀傲瓮间卧，顦顇泽畔行。","彼忧而此乐，道理甚分明。","愿君且饮酒，勿思身後名。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22143":["效陶潜体诗十六首 十四","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["有一燕赵士，言貌甚奇瓌。","日日酒家去，脱衣典数杯。","问君何落拓，云仆生草莱。","地寒命且薄，徒抱王佐才。","岂无济时策，君门乏良媒。","三献寝不报，迟迟空手回。","亦有同门生，先升青云梯。","贵贱交道绝，朱门叩不开。","及归种禾黍，三岁旱爲灾。","入山烧黄白，一旦化爲灰。","蹉跎五十余，生世苦不谐。","处处去不得，却归酒中来。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22144":["效陶潜体诗十六首 十五","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["南巷有贵人，高盖驷马车。","我问何所苦，四十垂白须。","荅云君不知，位重多忧虞。","北里有寒士，瓮牖绳爲枢。","出扶桑枣杖，入卧蜗牛庐。","散贱无忧患，心安体亦舒。","东邻有富翁，藏货徧五都。","东京收粟帛，西市鬻金珠。","朝营暮计算，昼夜不安居。","西舍有贫者，匹妇配匹夫。","布帬行赁舂，裋褐坐佣书。","以此求口食，一饱欣有余。","贵贱与贫富，高下虽有殊。","忧乐与利害，彼此不相踰。","是以达人观，万化同一途。","但未知生死，胜负两何如。","迟疑未知间，且以酒爲娱。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22145":["效陶潜体诗十六首 十六","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["济水澄而洁，河水浑而黄。","交流列四渎，清浊不相伤。","太公战牧野，伯夷饿首阳。","同时号贤圣，进退不相妨。","谓天不爱民，胡爲生稻粱。","谓天果爱民，胡爲生豺狼。","谓神福善人，孔圣竟栖遑。","谓神祸淫人，暴秦终霸王。","颜回与黄宪，何辜早夭亡。","蝮蛇与鸩鸟，何得寿延长。","物理不可测，神道亦难量。","举头仰问天，天色但苍苍。","唯当多种黍，日醉手中觞。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22146":["自题写真","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["我貌不自识，李放写我真。","静观神与骨，合是山中人。","蒲柳质易朽，麋鹿心难驯。","何事赤墀上，五年爲侍臣。","况多刚狷性，难与世同尘。","不惟非贵相，但恐生祸因。","宜当早罢去，收取云泉身。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22147":["遣怀","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["寓心身体中，寓性方寸内。","此身是外物，何足苦忧爱。","况有假饰者，华簪及高盖。","此又疎於身，复在外物外。","操之多惴栗，失之又悲悔。","乃知名与器，得丧俱爲害。","颓然环堵客，萝蕙爲巾带。","自得此道来，身穷心甚泰。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22148":["渭上偶钓","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["渭水如镜色，中有鲤与鲂。","偶持一竿竹，悬钓在其傍。","微风吹钓丝，嫋嫋十尺长。","谁知对鱼坐，心在无何乡。","昔有白头人，亦钓此渭阳。","钓人不钓鱼，七十得文王。","况我垂钓意，人鱼又兼忘。","无机两不得，但弄秋水光。","兴尽钓亦罢，归来饮我觞。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22149":["隐几","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["身适忘四支，心适忘是非。","既适又忘适，不知吾是谁。","百体如槁木，兀然无所知。","方寸如死灰，寂然无所思。","今日复明日，身心忽两遗。","行年三十九，岁暮日斜时。","四十心不动，吾今其庶几。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22150":["春眠","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["新浴肢体畅，独寝神魂安。","况因夜深坐，遂成日高眠。","春被薄亦暖，朝窗深更闲。","却忘人间事，似得枕上仙。","至适无梦想，大和难名言。","全胜彭泽醉，欲敌曹溪禅。","何物呼我觉，伯劳声关关。","起来妻子笑，生计春茫然。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22151":["闲居","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["空腹一醆粥，饥食有余味。","南檐半牀日，暖卧因成睡。","緜袍拥两膝，竹几支双臂。","从旦直至昏，身心一无事。","心足即爲富，身闲乃当贵。","富贵在此中，何必居高位。","君看裴相国，金紫光照地。","心苦头尽白，才年四十四。","乃知高盖车，乘者多忧畏。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22152":["夏日","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["东窗晚无热，北户凉有风。","尽日坐复卧，不离一室中。","中心本无系，亦与出门同。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22153":["适意二首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["十年爲旅客，常有饥寒愁。","三年作谏官，复多尸素羞。","有酒不暇饮，有山不得游。","岂无平生志，拘牵不自由。","一朝归渭上，泛如不系舟。","置心世事外，无喜亦无忧。","终日一蔬食，终年一布裘。","寒来弥嬾放，数日一梳头。","朝睡足始起，夜酌醉即休。","人心不过适，适外复何求。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22154":["适意二首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["早岁从旅游，颇谙时俗意。","中年忝班列，备见朝廷事。","作客诚已难，爲臣尤不易。","况余方且介，举动多忤累。","直道速我尤，诡遇非吾志。","胸中十年内，消尽浩然气。","自从返田亩，顿觉无忧媿。","蟠木用难施，浮云心易遂。","悠悠身与世，从此两相弃。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22155":["首夏病间","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["我生来几时，万有四千日。","自省於其间，非忧即有疾。","老去虑渐息，年来病初愈。","忽喜身与心，泰然两无苦。","况兹孟夏月，清和好时节。","微风吹裌衣，不寒复不热。","移榻树阴下，竟日何所爲。","或饮一瓯茗，或吟两句诗。","内无忧患迫，外无职役羁。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22156":["晚春酤酒","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["百花落如雪，两鬓垂作丝。","春去有来日，我老无少时。","人生待富贵，爲乐常苦迟。","不如贫贱日，随分开愁眉。","卖我所乘马，典我旧朝衣。","尽将酤酒饮，酩酊步行归。","名姓日隐晦，形骸日变衰。","醉卧黄公肆，人知我是谁。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22157":["兰若寓居","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["名宦老慵求，退身安草野。","家园病嬾归，寄居在兰若。","薜衣换簪组，藜杖代车马。","行止辄自由，甚觉身潇洒。","晨游南坞上，夜息东庵下。","人间千万事，无有关心者。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22158":["麴生访宿","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["西斋寂已暮，叩门声樀樀。","知是君宿来，自拂尘埃席。","村家何所有，茶果迎来客。","贫静似僧居，竹林依四壁。","厨灯斜影出，檐雨余声滴。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22159":["闻庾七左降因咏所怀","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["我病卧渭北，君老谪巴东。","相悲一长叹，薄命与君同。","既叹还自哂，哂叹两未终。","後心诮前意，所见何迷蒙。","人生大块间，如鸿毛在风。","或飘青云上，或落泥涂中。","衮服相天下，傥来非我通。","布衣委草莽，偶去非吾穷。","外物不可必，中怀须自空。","无令怏怏气，留滞在心胸。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22160":["荅卜者","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["病眼昏似夜，衰鬓飒如秋。","除却须衣食，平生百事休。","知君善易者，问我决疑不。","不卜非他故，人间无所求。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22161":["归田三首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["人生何所欲，所欲唯两端。","中人爱富贵，高士慕神仙。","神仙须有籍，富贵亦在天。","莫恋长安道，莫寻方丈山。","西京尘浩浩，东海浪漫漫。","金门不可入，琪树何由攀。","不如归山下，如法种春田。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22162":["归田三首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["种田意已决，决意复何如。","卖马买犊使，徒步归田庐。","迎春治耒耜，候雨辟菑畲。","策杖田头立，躬亲课仆夫。","吾闻老农言，爲稼慎在初。","所施不卤莽，其报必有余。","上求奉王税，下望备家储。","安得放慵惰，拱手而曳裾。","学农未爲鄙，亲友勿笑余。","更待明年後，自拟执犂锄。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22163":["归田三首 三","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["三十爲近臣，腰间鸣佩玉。","四十爲野夫，田中学锄谷。","何言十年内，变化如此速。","此理固是常，穷通相倚伏。","爲鱼有深水，爲鸟有高木。","何必守一方，窘然自牵束。","化吾足爲马，吾因以行陆。","化吾手爲弹，吾因以求肉。","形骸爲异物，委顺心犹足。","幸得且归农，安知不爲福。","况吾行欲老，瞥若风前烛。","孰能俄顷间，将心系荣辱。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22164":["秋游原上","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["七月行已半，早凉天气清。","清晨起巾栉，徐步出柴荆。","露杖筇竹冷，风襟越蕉轻。","闲携弟侄辈，同上秋原行。","新枣未全赤，晚瓜有余馨。","依依田家叟，设此相逢迎。","自我到此村，往来白发生。","村中相识久，老幼皆有情。","留连向暮归，树树风蝉声。","是时新雨足，禾黍夹道青。","见此令人饱，何必待西成。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22165":["九日登西原宴望","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["病爱枕席凉，日高眠未辍。","弟兄呼我起，今日重阳节。","起登西原望，怀抱同一豁。","移座就菊丛，餻酒前罗列。","虽无丝与管，歌笑随情发。","白日未及倾，颜酡耳已热。","酒酣四向望，六合何空阔。","天地自久长，斯人几时活。","请看原下村，村人死不歇。","一村四十家，哭葬无虚月。","指此各相勉，良辰且欢悦。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22166":["寄同病者","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["三十生二毛，早衰爲沈疴。","四十官七品，拙宦非由他。","年颜日枯槁，时命日蹉跎。","岂独我如此，圣贤无奈何。","回观亲旧中，举目尤可嗟。","或有终老者，沈贱如泥沙。","或有始壮者，飘忽如风花。","穷饿与夭促，不如我者多。","以此反自慰，常得心平和。","寄言同病者，回叹且爲歌。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22167":["游蓝田山卜居","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["脱置腰下组，摆落心中尘。","行歌望山去，意似归乡人。","朝蹋玉峰下，暮寻蓝水滨。","拟求幽僻地，安置疎慵身。","本性便山寺，应须旁悟真。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22168":["村雪夜坐","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["南窗背灯坐，风霰暗纷纷。","寂莫深村夜，残雁雪中闻。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22169":["东园玩菊","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["少年昨已去，芳岁今又阑。","如何寂莫意，复此荒凉园。","园中独立久，日澹风露寒。","秋蔬尽芜没，好树亦凋残。","唯有数丛菊，新开篱落间。","携觞聊就酌，爲尔一留连。","忆我少小日，易爲兴所牵。","见酒无时节，未饮已欣然。","近从年长来，渐觉取乐难。","常恐更衰老，强饮亦无欢。","顾谓尔菊花，後时何独鲜。","诚知不爲我，借尔暂开颜。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22170":["观稼","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["世役不我牵，身心常自若。","晚出看田亩，闲行旁村落。","累累绕场稼，啧啧羣飞雀。","年丰岂独人，禽鸟声亦乐。","田翁逢我喜，默起具尊杓。","敛手笑相延，社酒有残酌。","媿兹勤且敬，藜杖爲淹泊。","言动任天真，未觉农人恶。","停杯问生事，夫种妻儿获。","筋力苦疲劳，衣食常单薄。","自慙禄仕者，曾不营农作。","饱食无所劳，何殊卫人鹤。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22171":["闻哭者","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昨日南邻哭，哭声一何苦。","云是妻哭夫，夫年二十五。","今朝北里哭，哭声又何切。","云是母哭儿，儿年十七八。","四邻尚如此，天下多夭折。","乃知浮世人，少得垂白发。","余今过四十，念彼聊自悦。","从此明镜中，不嫌头似雪。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22172":["新构亭台示诸弟侄","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["平台高数尺，台上结茅茨。","东西疏二牖，南北开两扉。","芦帘前後卷，竹簟当中施。","清泠白石枕，疏凉黄葛衣。","开襟向风坐，夏日如秋时。","啸傲颇有趣，窥临不知疲。","东窗对华山，三峰碧参差。","南檐当渭水，卧见云帆飞。","仰摘枝上果，俯折畦中葵。","足以充饥渴，何必慕甘肥。","况有好羣从，旦夕相追随。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22173":["自吟拙什因有所怀","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["嬾病每多暇，暇来何所爲。","未能抛笔研，时作一篇诗。","诗成澹无味，多被衆人嗤。","上怪落声韵，下嫌拙言词。","时时自吟咏，吟罢有所思。","苏州及彭泽，与我不同时。","此外复谁爱，唯有元微之。","谪向江陵府，三年作判司。","向去二千里，诗成远不知。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22174":["东坡秋意寄元八","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["寥落野陂畔，独行思有余。","秋荷病叶上，白露大如珠。","忽忆同赏地，曲江东北隅。","秋池少游客，唯我与君俱。","啼蛩隐红蓼，瘦马蹋青芜。","当时与今日，俱是暮秋初。","节物苦相似，时景亦无余。","唯有人分散，经年不得书。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22175":["闲居","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["深闭竹间扉，静埽松下地。","独啸晚风前，何人知此意。","看山尽日坐，枕帙移时睡。","谁能从我游，使君心无事。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22176":["咏拙","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["所禀有巧拙，不可改者性。","所赋有厚薄，不可移者命。","我性愚且惷，我命薄且屯。","问我何以知，所知良有因。","亦曾举两足，学人蹋红尘。","从兹知性拙，不解转如轮。","亦曾奋六翮，高飞到青云。","从兹知命薄，摧落不逡巡。","慕贵而厌贱，乐富而恶贫。","同此天地间，我岂异於人。","性命苟如此，反则成苦辛。","以此自安分，虽穷每欣欣。","葺茅爲我庐，编蓬爲我门。","缝布作袍被，种谷充盘飧。","静读古人书，闲钓清渭滨。","优哉复游哉，聊以终吾身。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22177":["咏慵","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["有官慵不选，有田慵不农。","屋穿慵不葺，衣裂慵不缝。","有酒慵不酌，无异尊常空。","有琴慵不弹，亦与无弦同。","家人告饭尽，欲炊慵不舂。","亲朋寄书至，欲读慵开封。","尝闻嵇叔夜，一生在慵中。","弹琴复锻铁，比我未爲慵。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22178":["冬夜","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["家贫亲爱散，身病交游罢。","眼前无一人，独掩村斋卧。","冷落灯火闇，离披帘幕破。","策策窗户前，又闻新雪下。","长年渐省睡，夜半起端坐。","不学坐忘心，寂莫安可过。","兀然身寄世，浩然心委化。","如此来四年，一千三百夜。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22179":["村中留李三固言宿","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["平生早游宦，不道无亲故。","如我与君心，相知应有数。","春明门前别，金氏陂中遇。","村酒两三杯，相留寒日暮。","勿嫌村酒薄，聊酌论心素。","请君少踟蹰，系马门前树。","明年身若健，便拟江湖去。","他日纵相思，知君无觅处。","後会既茫茫，今宵君且住。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22180":["友人夜访","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["檐间清风簟，松下明月杯。","幽意正如此，况乃故人来。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22181":["游悟真寺诗","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["元和九年秋，八月月上弦。","我游悟真寺，寺在王顺山。","去山四五里，先闻水潺湲。","自兹舍车马，始涉蓝溪湾。","手拄青竹杖，足蹋白石滩。","渐怪耳目旷，不闻人世喧。","山下望山上，初疑不可攀。","谁知中有路，盘折通岩巅。","一息幡竿下，再休石龛边。","龛间长丈余，门户无扃关。","仰窥不见人，石发垂若鬟。","惊出白蝙蝠，双飞如雪飜。","回首寺门望，青崖夹朱轩。","如擘山腹开，置寺於其间。","入门无平地，地窄虚空宽。","房廊与台殿，高下随峰峦。","岩崿无撮土，树木多瘦坚。","根株抱石长，屈曲虫蛇蟠。","松桂乱无行，四时郁芊芊。","枝梢嫋青翠，韵若风中弦。","日月光不透，绿阴相交延。","幽鸟时一声，闻之似寒蝉。","首憩宾位亭，就坐未及安。","须臾开北户，万里明豁然。","拂檐虹霏微，绕栋云回旋。","赤日间白雨，阴晴同一川。","野绿簇草树，眼界吞秦原。","渭水细不见，汉陵小於拳。","却顾来时路，萦纡映朱阑。","历历上山人，一一遥可观。","前对多宝墖，风铎鸣四端。","栾栌与户牖，恰恰金碧繁。","云昔迦叶佛，此地坐涅盘。","至今铁鉢在，当底手迹穿。","西开玉像殿，白佛森比肩。","斗薮尘埃衣，礼拜冰雪颜。","叠霜爲袈裟，贯雹爲华鬘。","逼观疑鬼功，其迹非雕镌。","次登观音堂，未到闻栴檀。","上阶脱双履，敛足升净筵。","六楹排玉镜，四座敷金钿。","黑夜自光明，不待灯烛然。","衆宝互低昂，碧佩珊瑚幡。","风来似天乐，相触声珊珊。","白珠垂露凝，赤珠滴血殷。","点缀佛髻上，合爲七宝冠。","双缾白琉璃，色若秋水寒。","隔缾见舍利，圆转如金丹。","玉笛何代物，天人施只园。","吹如秋鹤声，可以降灵仙。","是时秋方中，三五月正圆。","宝堂豁三门，金魄当其前。","月与宝相射，晶光争鲜妍。","照人心骨冷，竟夕不欲眠。","晓寻南墖路，乱竹低婵娟。","林幽不逢人，寒蝶飞翾翾。","山果不识名，离离夹道蕃。","足以疗饥乏，摘尝味甘酸。","道南蓝谷神，紫伞白纸钱。","若岁有水旱，诏使修苹蘩。","以地清净故，献奠无荤膻。","危石叠四五，𡾋嵬欹且刓","造物者何意，堆在岩东偏。","冷滑无人迹，苔点如花牋。","我来登上头，下临不测渊。","目眩手足掉，不敢低头看。","风从石下生，薄人而上抟。","衣服似羽翮，开张欲飞骞。","𡾼𡾼三面峰，峰尖刀劒","往往白云过，决开露青天。","西北日落时，夕晖红团团。","千里翠屏外，走下丹砂丸。","东南月上时，夜气青漫漫。","百丈碧潭底，写出黄金盘。","蓝水色似蓝，日夜长潺潺。","周回绕山转，下视如青环。","或铺爲慢流，或激爲奔湍。","泓澄最深处，浮出蛟龙涎。","侧身入其中，悬磴尤险艰。","扪萝蹋樛木，下逐饮涧猨。","雪迸起白鹭，锦跳惊红鱣。","歇定方盥漱，濯去支体烦。","浅深皆洞彻，可照脑与肝。","但爱清见底，欲寻不知源。","东崖饶怪石，积甃苍琅玕。","温润发於外，其间韫璵璠。","卞和死已久，良玉多弃捐。","或时泄光彩，夜与星月连。","中顶最高峰，拄天青玉竿。","𪕍𪕌上不得，岂我能攀","上有白莲池，素葩覆清澜。","闻名不可到，处所非人寰。","又有一片石，大如方尺甎。","插在半壁上，其下万仞悬。","云有过去师，坐得无生禅。","号爲定心石，长老世相传。","却上谒仙祠，蔓草生緜緜。","昔闻王氏子，羽化升上玄。","其西晒药台，犹对芝术田。","时复明月夜，上闻黄鹤言。","回寻画龙堂，二叟鬓发斑。","想见听法时，欢喜礼印坛。","复归泉窟下，化作龙蜿蜒。","阶前石孔在，欲雨生白烟。","往有写经僧，身静心精专。","感彼云外鸽，羣飞千翩翩。","来添研中水，去吸岩底泉。","一日三往复，时节长不愆。","经成号圣僧，弟子名杨难。","诵此莲花偈，数满百亿千。","身坏口不坏，舌根如红莲。","颅骨今不见，石函尚存焉。","粉壁有吴画，笔彩依旧鲜。","素屏有褚书，墨色如新乾。","灵境与异迹，周览无不殚。","一游五昼夜，欲返仍盘桓。","我本山中人，误爲时网牵。","牵率使读书，推挽令効官。","既登文字科，又忝谏诤员。","拙直不合时，无益同素餐。","以此自慙惕，戚戚常寡欢。","无成心力尽，未老形骸残。","今来脱簪组，始觉离忧患。","及爲山水游，弥得纵疎顽。","野麋断羁绊，行走无拘挛。","池鱼放入海，一往何时还。","身着居士衣，手把南华篇。","终来此山住，永谢区中缘。","我今四十余，从此终身闲。","若以七十期，犹得三十年。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22182":["酬张十八访宿见赠","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昔我爲近臣，君常稀到门。","今我官职冷，君君来往频。","我受狷介性，立爲顽拙身。","平生虽寡合，合即无缁磷。","况君秉高义，富贵视如云。","五侯三相家，眼冷不见君。","问其所与游，独言韩舍人。","其次即及我，我媿非其伦。","胡爲谬相爱，岁晚逾勤勤。","落然颓檐下，一话夜达晨。","牀单食味薄，亦不嫌我贫。","日高上马去，相顾犹逡巡。","长安久无雨，日赤风昏昏。","怜君将病眼，爲我犯埃尘。","远从延康里，来访曲江滨。","所重君子道，不独媿相亲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22183":["朝归书寄元八","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["进入合前拜，退就廊下餐。","归来昭国里，人卧马歇鞍。","却睡至日午，起坐心浩然。","况当好时节，雨後清和天。","柿树绿阴合，王家庭院宽。","缾中鄠县酒，墙上终南山。","独眠仍独坐，开襟当风前。","禅师与诗客，次第来相看。","要语连夜语，须眠终日眠。","除非奉朝谒，此外无别牵。","年长身且健，官贫心甚安。","幸无急病痛，不至苦饥寒。","自此聊以适，外缘不能干。","唯应静者信，难爲动者言。","台中元侍御，早晚作郎官。","未作郎官际，无人相伴闲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22184":["酬吴七见寄","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["曲江有病客，寻常多掩关。","又闻马死来，不出身更闲。","闻有送书者，自起出门看。","素缄署丹字，中有琼瑶篇。","口吟耳自听，当暑忽翛然。","似漱寒玉冰，如闻商风弦。","首章叹时节，末句思笑言。","嬾慢不相访，隔街如隔山。","尝闻陶潜语，心远地自偏。","君住安邑里，左右车徒喧。","竹药闭深院，琴尊开小轩。","谁知市南地，转作壶中天。","君本上清人，名在石堂间。","不知有何过，谪作人间仙。","常恐岁月满，飘然归紫烟。","莫忘蜉蝣内，进士有同年。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22185":["昭国闲居","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["贫闲日高起，门巷昼寂寂。","时暑放朝参，天阴少人客。","槐花满田地，仅绝人行迹。","独在一牀眠，清凉风雨夕。","勿嫌坊曲远，近即多牵役。","勿嫌禄俸薄，厚即多忧责。","平生尚恬旷，老大宜安适。","何以养吾真，官闲居处僻。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22186":["喜陈兄至","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["黄鸟啼欲歇，青梅结半成。","坐怜春物尽，起入东园行。","携觞嬾独酌，忽闻叩门声。","闲人犹喜至，何况是陈兄。","从容尽日语，稠叠长年情。","勿轻一醆酒，可以话平生。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22187":["赠杓直","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["世路重禄位，栖栖者孔宣。","人情爱年寿，夭死者颜渊。","二人如何人，不奈命与天。","我今信多幸，抚己媿前贤。","已年四十四，又爲五品官。","况兹知足外，别有所安焉。","早年以身代，直赴逍遥篇。","近岁将心地，回向南宗禅。","外顺世间法，内脱区中缘。","进不厌朝市，退不恋人寰。","自吾得此心，投足无不安。","体非导引适，意无江湖闲。","有兴或饮酒，无事多掩关。","寂静夜深坐，安稳日高眠。","秋不苦长夜，春不惜流年。","委形老小外，忘怀生死间。","昨日共君语，与余心膂然。","此道不可道，因君聊强言。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22188":["寄张十八","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["饥止一箪食，渴止一壶浆。","出入止一马，寝兴止一牀。","此外无长物，於我有若亡。","胡然不知足，名利心遑遑。","念兹弥嬾放，积习遂爲常。","经旬不出门，竟日不下堂。","同病者张生，贫僻住延康。","慵中每相忆，此意未能忘。","迢迢青槐街，相去八九坊。","秋来未相见，应有新诗章。","早晚来同宿，天气转清凉。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22189":["题玉泉寺","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["湛湛玉泉色，悠悠浮云身。","闲心对定水，清静两无尘。","手把青筇杖，头戴白纶巾。","兴尽下山去，知我是谁人。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22190":["朝回游城南","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["朝退马未困，秋初日犹长。","回辔城南去，郊野正清凉。","水竹夹小径，萦回绕川冈。","仰看晚山色，俯弄秋泉光。","青松系我马，白石爲我牀。","常时簪组累，此日和身忘。","旦随鵷鹭末，暮游鸥鹤旁。","机心一以尽，两处不乱行。","谁辨心与迹，非行亦非藏。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22191":["舟行","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["帆影日渐高，闲眠犹未起。","起问鼓枻人，已行三十里。","船头有行竈，炊稻烹红鲤。","饱食起婆娑，盥漱秋江水。","平生沧浪意，一旦来游此。","何况不失家，舟中载妻子。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22192":["湓浦早冬","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["浔阳孟冬月，草木未全衰。","祗抵长安陌，凉风八月时。","日西湓水曲，独行吟旧诗。","蓼花始零落，蒲叶稍离披。","但作城中想，何异曲江池。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22193":["江州雪","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["新雪满前山，初晴好天气。","日西骑马出，忽有京都意。","城柳方缀花，檐冰才结穗。","须臾风日暖，处处皆飘坠。","行吟赏未足，坐叹销何易。","犹胜岭南看，雰雰不到地。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22194":["题浔阳楼","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["常爱陶彭泽，文思何高玄。","又怪韦江州，诗情亦清闲。","今朝登此楼，有以知其然。","大江寒见底，匡山青倚天。","深夜湓浦月，平旦鑪峰烟。","清辉与灵气，日夕供文篇。","我无二人才，孰爲来其间。","因高偶成句，俯仰媿江山。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22195":["访陶公旧宅","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["垢尘不汚玉，灵凤不啄羶。","呜呼陶靖节，生彼晋宋间。","心实有所守，口终不能言。","永惟孤竹子，拂衣首阳山。","夷齐各一身，穷饿未爲难。","先生有五男，与之同饥寒。","肠中食不充，身上衣不完。","连徵竟不起，斯可谓真贤。","我生君之後，相去五百年。","每读五柳传，目想心拳拳。","昔常咏遗风，着爲十六篇。","今来访故宅，森若君在前。","不慕尊有酒，不慕琴无弦。","慕君遗荣利，老死此丘园。","柴桑古村落，栗里旧山川。","不见篱下菊，但余墟中烟。","子孙虽无闻，族氏犹未迁。","每逢姓陶人，使我心依然。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22196":["北亭","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["庐宫山下州，湓浦沙边宅。","宅北倚高冈，迢迢数千尺。","上有青青竹，竹间多白石。","茅亭居上头，豁达门四辟。","前楹卷帘箔，北牖施牀席。","江风万里来，吹我凉淅淅。","日高公府归，巾笏随手掷。","脱衣恣搔首，坐卧任所适。","时倾一杯酒，旷望湖天夕。","口咏独酌谣，目送归飞翮。","慙无出尘操，未免折腰役。","偶获此闲居，谬似高人迹。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22197":["泛湓水","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["四月未全热，麦凉江气秋。","湖山处处好，最爱湓水头。","湓水从东来，一派入江流。","可怜似萦带，中有随风舟。","命酒一临泛，舍鞍扬櫂讴。","放回岸傍马，去逐波间鸥。","烟浪始渺渺，风襟亦悠悠。","初疑上河汉，中若寻瀛洲。","汀树绿拂地，沙草芳未休。","青萝与紫葛，枝蔓垂相樛。","系缆步平岸，回头望江州。","城雉映水见，隐隐如蜃楼。","日入意未尽，将归复少留。","到官行半岁，今日方一游。","此地来何暮，可以写吾忧。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22198":["荅故人","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["故人对酒叹，叹我在天涯。","见我昔荣遇，念我今蹉跎。","问我爲司马，官意复如何。","荅云且勿叹，听我爲君歌。","我本蓬荜人，鄙贱剧泥沙。","读书未百卷，信口嘲风花。","自从筮仕来，六命三登科。","顾慙虚劣姿，所得亦已多。","散员足庇身，薄俸可资家。","省分辄自媿，岂爲不遇耶。","烦君对杯酒，爲我一咨蹉。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22199":["官舍内新凿小池","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["帘下开小池，盈盈水方积。","中底铺白沙，四隅甃青石。","勿言不深广，但取幽人适。","泛灩微雨朝，泓澄明月夕。","岂无大江水，波浪连天白。","未如牀席间，方丈深盈尺。","清浅可狎弄，昏烦聊漱涤。","最爱晓暝时，一片秋天碧。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22200":["宿简寂观","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["岩白云尚屯，林红叶初陨。","秋光引闲步，不知身远近。","夕投灵洞宿，卧觉尘机泯。","名利心既忘，市朝梦亦尽。","暂来尚如此，况乃终身隐。","何以疗夜饥，一匙云母粉。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22201":["读谢灵运诗","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["吾闻达士道，穷通顺冥数。","通乃朝廷来，穷即江湖去。","谢公才廓落，与世不相遇。","壮志郁不用，须有所泄处。","泄爲山水诗，逸韵谐奇趣。","大必笼天海，细不遗草树。","岂惟玩景物，亦欲摅心素。","往往即事中，未能忘兴谕。","因知康乐作，不独在章句。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22202":["北亭独宿","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["悄悄壁下牀，纱笼耿残烛。","夜半独眠觉，疑在僧房宿。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22203":["约心","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["黑鬓丝雪侵，青袍尘土涴。","兀兀复腾腾，江城一上佐。","朝就高斋上，熏然负暄卧。","晚下小池前，澹然临水坐。","已约终身心，长如今日过。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22204":["晚望","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江城寒角动，沙洲夕鸟还。","独在高亭上，西南望远山。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22205":["早春","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["雪消冰又释，景和风复暄。","满庭田地湿，荠叶生墙根。","官舍悄无事，日西斜掩门。","不开庄老卷，欲与何人言。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22206":["春寝","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处春暄来？微和生血气。","气熏肌骨畅，东窗一昏睡。","是时正月晦，假日无公事。","烂熳不能休，自午将及未。","缅思少健日，甘寝常自恣。","一从衰疾来，枕上无此味。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22207":["睡起晏坐","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["後亭昼眠足，起坐春景暮。","新觉眼犹昏，无思心正住。","澹寂归一性，虚闲遗万虑。","了然此时心，无物可譬喻。","本是无有乡，亦名不用处。","行禅与坐忘，同归无异路。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22208":["咏怀","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["尽日松下坐，有时池畔行。","行立与坐卧，中怀澹无营。","不觉流年过，亦任白发生。","不爲世所薄，安得遂闲情。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22209":["春游二林寺","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["下马二林寺，翛然进轻策。","朝爲公府吏，暮作灵山客。","二月匡庐北，冰雪始消释。","阳丛抽茗芽，阴窦泄泉脉。","熙熙风土暖，蔼蔼云岚积。","散作万壑春，凝爲一气碧。","身闲易飘泊，官散无牵迫。","缅彼十八人，古今同此适。","是年淮寇起，处处兴兵革。","智士劳思谋，戎臣苦征役。","独有不才者，山中弄泉石。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22210":["出山吟","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["朝咏游仙诗，暮歌采薇曲。","卧云坐白石，山中十五宿。","行随出洞水，回别缘岩竹。","早晚重来游，心期瑶草绿。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22211":["岁暮","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["已任时命去，亦从岁月除。","中心一调伏，外累尽空虚。","名宦意已矣，林泉计何如。","拟近东林寺，溪边结一庐。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22212":["闻早莺","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["日出眠未起，屋头闻早莺。","忽如上林晓，万年枝上鸣。","忆爲近臣时，秉笔直承明。","春深视草暇，旦暮闻此声。","今闻在何处，寂莫浔阳城。","鸟声信如一，分别在人情。","不作天涯意，岂殊禁中听。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22213":["栽杉","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["劲叶森利劒，孤茎挺端标。","才高四五尺，势若干青霄。","移栽东窗前，爱尔寒不凋。","病夫卧相对，日夕闲萧萧。","昨爲山中树，今爲檐下条。","虽然遇赏玩，无乃近尘嚣。","犹胜涧谷底，埋没随衆樵。","不见郁郁松，委质山上苗。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22214":["过李生","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["苹小蒲叶短，南湖春水生。","子近湖边住，静境称高情。","我爲郡司马，散拙无所营。","使君知性野，衙退任闲行。","行携小榼出，逢花辄独倾。","半酣到子舍，下马扣柴荆。","何以引我步，绕篱竹万茎。","何以醒我酒，吴音吟一声。","须臾进野饭，饭稻茹芹英。","白瓯青竹箸，俭洁无羶腥。","欲去复裴回，夕鸦已飞鸣。","何当重游此，待君湖水平。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22215":["咏意","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["常闻南华经，巧劳智忧愁。","不如无能者，饱食但遨游。","平生爱慕道，今日近此流。","自来浔阳郡，四序忽已周。","不分物黑白，但与时沈浮。","朝餐夕安寝，用是爲身谋。","此外即闲放，时寻山水幽。","春游慧远寺，秋上庾公楼。","或吟诗一章，或饮茶一瓯。","身心一无系，浩浩如虚舟。","富贵亦有苦，苦在心危忧。","贫贱亦有乐，乐在身自由。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22216":["食笋","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["此州乃竹乡，春笋满山谷。","山夫折盈抱，抱来早市鬻。","物以多爲贱，双钱易一束。","置之炊甑中，与饭同时熟。","紫箨坼故锦，素肌擘新玉。","每日遂加餐，经时不思肉。","久爲京洛客，此味常不足。","且食勿踟蹰，南风吹作竹。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22217":["游石门涧","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["石门无旧径，披榛访遗迹。","时逢山水秋，清辉如古昔。","常闻慧远辈，题诗此岩壁。","云覆莓苔封，苍然无处觅。","萧疎野生竹，崩剥多年石。","自从东晋後，无复人游历。","独有秋涧声，潺湲空旦夕。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22218":["招东邻","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["小榼二升酒，新簟六尺牀。","能来夜话否，池畔欲秋凉。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22219":["题元十八溪亭","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["怪君不喜仕，又不游州里。","今日到幽居，了然知所以。","宿君石溪亭，潺湲声满耳。","饮君螺杯酒，醉卧不能起。","见君五老峰，益悔居城市。","爱君三男儿，始叹身无子。","余方鑪峰下，结室爲居士。","山北与山东，往来从此始。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22220":["香鑪峰下新置草堂即事咏怀题於石上","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["香鑪峰北面，遗爱寺西偏。","白石何凿凿，清流亦潺潺。","有松数十株，有竹千余竿。","松张翠繖盖，竹倚青琅玕。","其下无人居，悠哉多岁年。","有时聚猨鸟，终日空风烟。","时有沈冥子，姓白字乐天。","平生无所好，见此心依然。","如获终老地，忽乎不知还。","架岩结茅宇，斵壑开茶园。","何以洗我耳，屋头飞落泉。","何以净我眼，砌下生白莲。","左手携一壶，右手挈五弦。","傲然意自足，箕踞於其间。","兴酣仰天歌，歌中聊寄言。","言我本野夫，误爲世网牵。","时来昔捧日，老去今归山。","倦鸟得茂树，涸鱼返清源。","舍此欲焉往，人间多险艰。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22221":["草堂前新开一池养鱼种荷日有幽趣","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["淙淙三峡水，浩浩万顷陂。","未如新塘上，微风动涟漪。","小萍加泛泛，初蒲正离离。","红鲤二三寸，白莲八九枝。","绕水欲成径，护堤方插篱。","已被山中客，呼作白家池。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22222":["白云期","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["三十气太状，胷中多是非。","六十身太老，四体不支持。","四十至五十，正是退闲时。","年长识命分，心慵少营爲。","见酒兴犹在，登山力未衰。","吾年幸当此，且与白云期。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22223":["登香炉峰顶","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["迢迢香鑪峰，心存耳目想。","终年牵物役，今日方一往。","攀萝蹋危石，手足劳俛仰。","同游三四人，两人不敢上。","上到峰之顶，目眩神怳怳。","高低有万寻，阔狭无数丈。","不穷视听界，焉识宇宙广。","江水细如绳，湓城小於掌。","纷吾何屑屑，未能脱尘鞅。","归去思自嗟，低头入蚁壤。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22224":["荅崔侍郎钱舍人书问因继以诗","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["旦暮两蔬食，日中一闲眠。","便是了一日，如此已三年。","心不择时适，足不拣地安。","穷通与远近，一贯无两端。","常见今之人，其心或不然。","在劳则念息，处静已思喧。","如是用身心，无乃自伤残。","坐输忧恼便，安得形神全。","吾有二道友，蔼蔼崔与钱。","同飞青云路，独堕黄泥泉。","岁暮物万变，故情何不迁？","应爲平生心，与我同一源。","帝乡远於日，美人高在天。","谁谓万里别，常若在目前。","泥泉乐者鱼，云路游者鸾。","勿言云泥异，同在逍遥间。","因君问心地，书後偶成篇。","慎勿说向人，人多笑此言。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22225":["烹葵","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昨卧不夕食，今起乃朝饥。","贫厨何所有，炊稻烹秋葵。","红粒香复輭，绿英滑且肥。","饥来止於饱，饱後复何思。","忆昔荣遇日，迨今穷退时。","今亦不冻馁，昔亦无余资。","口既不减食，身又不减衣。","抚心私自问，何者是荣衰。","勿学常人意，其间分是非。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22226":["小池二首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昼倦前斋热，晚爱小池清。","映林余景没，近水微凉生。","坐把蒲葵扇，闲吟三两声。"],"",[["古评·《唐诗镜》","三四清快欲絶"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_22227":["小池二首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["有意不在大，湛湛方丈余。","荷侧泻清露，萍开见游鱼。","每一临此坐，忆归青溪居。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22228":["闭关","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["我心忘世久，世亦不我干。","遂成一无事，因得长掩关。","掩关来几时，髣髴二三年。","着书已盈帙，生子欲能言。","始悟身向老，复悲世多艰。","回顾趋时者，役役尘壤间。","岁暮竟何得，不如且安闲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22229":["弄龟罗","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["有侄始六岁，字之爲阿龟。","有女生三年，其名曰罗儿。","一始学笑语，一能诵歌诗。","朝戏抱我足，夜眠枕我衣。","汝生何其晚，我年行已衰。","物情小可念，人意老多慈。","酒美竟须坏，月圆终有亏。","亦如恩爱缘，乃是忧恼资。","举世同此累，吾安能去之。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22230":["截树","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["种树当前轩，树高柯叶繁。","惜哉远山色，隐此蒙笼间。","一朝持斧斤，手自截其端。","万叶落头上，千峰来面前。","忽似决云雾，豁达覩青天。","又如所念人，久别一款颜。","始有清风至，稍见飞鸟还。","开怀东南望，目远心辽然。","人各有偏好，物莫能两全。","岂不爱柔条，不如见青山。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22231":["望江楼上作","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江畔百尺楼，楼前千里道。","凭高望平远，亦足舒怀抱。","驿路使憧憧，关防兵草草。","及兹多事日，尤觉闲人好。","我年过不惑，休退诚非早。","从此拂尘衣，归山未爲老。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22232":["题座隅","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["手不任执殳，肩不能荷锄。","量力揆所用，曾不敌一夫。","幸因笔研功，得升仕进途。","历官凡五六，禄俸及妻孥。","左右有兼仆，出入有单车。","自奉虽不厚，亦不至饥劬。","若有人及此，傍观爲何如。","虽贤亦爲幸，况我鄙且愚。","伯夷古贤人，鲁山亦其徒。","时哉无奈何，俱化爲饿殍。","念彼益自媿，不敢忘斯须。","平生荣利心，破灭无遗余。","犹恐尘妄起，题此於座隅。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22233":["昔与微之在朝日同蓄休退之心迨今十年沦落老人追寻前约且结後期","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["往子爲御史，伊余忝拾遗。","皆逢盛明代，俱登清近司。","予系玉爲佩，子曳绣爲衣。","从容香烟下，同侍白玉墀。","朝见宠者辱，暮见安者危。","纷纷无退者，相顾令人悲。","宦情君早厌，世事我深知。","常於荣显日，已约林泉期。","况今各流落，身病齿发衰。","不作卧云计，携手欲何之。","待君女嫁後，及我官满时。","稍无骨肉累，粗有渔樵资。","岁晚青山路，白首期同归。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22234":["垂钓","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["临水一长啸，忽思十年初。","三登甲乙第，一入承明庐。","浮生多变化，外事有盈虚。","今来伴江叟，沙头坐钓鱼。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22235":["晚鷰","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["百鸟乳雏毕，秋鷰独蹉跎。","去社日已近，衔泥意如何。","不悟时节晚，徒施工用多。","人间事亦尔，不独鷰营窠。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22236":["赎鸡","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["清晨临江望，水禽正諠繁。","凫鴈与鸥鹭，游扬戏朝暾。","适有鬻鸡者，挈之来远村。","飞鸣彼何乐，窘束此何冤。","喔喔十四雏，罩缚同一樊。","足伤金距蹜，头抢花冠飜。","经宿废饮啄，日高诣屠门。","迟回未死间，饥渴欲相吞。","常慕古人道，仁信及鱼豚。","见兹生恻隐，赎放双林园。","开笼解索时，鸡鸡听我言。","与尔镪三百，小惠何足论。","莫学衔环雀，崎岖谩报恩。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22237":["秋日怀杓直","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["晚来天色好，独出江边步。","忆与李舍人，曲江相近住。","常云遇清景，必约同幽趣。","若不访我来，还须觅君去。","开眉笑相见，把手期何处。","西寺老胡僧，南园乱松树。","携持小酒榼，吟咏新诗句。","同出复同归，从朝直至暮。","风雨忽消散，江山眇回互。","浔阳与涔阳，相望空云雾。","心期自乖旷，时景还如故。","今日郡斋中，秋光谁共度。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22238":["食後","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["食罢一觉睡，起来两瓯茶。","举头看日影，已复西南斜。","乐人惜日促，忧人厌年赊。","无忧无乐者，长短任生涯。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22239":["齐物二首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["青松高百尺，绿蕙低数寸。","同生大块间，长短各有分。","长者不可退，短者不可进。","若用此理推，穷通两无闷。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22240":["齐物二首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["椿寿八千春，槿花不经宿。","中间复何有，冉冉孤竹生。","竹身三年老，竹色四时绿。","虽谢椿有余，犹胜槿不足。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22241":["山下宿","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["独到山下宿，静向月中行。","何处水边碓，夜舂云母声。"],"诗敦被独宿亦在车下李白诗白云南山来就我檐下宿",[["古注·《御选唐诗》","诗敦被独宿亦在车下李白诗白云南山来就我檐下宿"],["古注·《御选唐诗》","钱起诗舟向月中行"],["古注·《御选唐诗》","庾信乌夜啼御史府中何处宿晋书刘颂传任河内太守郡界多公主水碓遏塞流水颂表罢之庾信诗决渠移水碓"],["古注·《御选唐诗》","诗或舂或揄李白诗水舂云母碓唐书尉迟敬德传敬德晚节饵云母粉为方士术延年"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《御选唐诗》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/御選唐詩_(四庫全書本)）"]],"open_22242":["题旧写真图","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["我昔三十六，写貌在丹青。","我今四十六，衰顇卧江城。","岂比十年老，曾与衆苦幷。","一照旧图画，无复昔仪形。","形影默相顾，如弟对老兄。","况使他人见，能不昧平生。","羲和鞭日走，不爲我少停。","形骸属日月，老去何足惊。","所恨凌烟阁，不得画功名。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22243":["闲居","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["肺病不饮酒，眼昏不读书。","端然无所作，身意闲有余。","鸡栖篱落晚，雪映林木疎。","幽独已云极，何必山中居。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22244":["对酒示行简","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["今旦一尊酒，欢畅何怡怡。","此乐从中来，他人安得知。","兄弟唯二人，远别恒苦悲。","今春自巴峡，万里平安归。","复有双幼妹，笄年未结褵。","昨日嫁娶毕，良人皆可依。","忧念两消释，如刀断羁縻。","身轻心无系，忽欲凌空飞。","人生苟有累，食肉常如饥。","我心既无苦，饮水亦可肥。","行简劝尔酒，停杯听我辞。","不叹乡国远，不嫌官禄微。","但愿我与尔，终老不相离。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22245":["咏怀","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["冉牛与颜渊，卞和与马迁。","或罹天六极，或被人刑残。","顾我信爲幸，百骸且完全。","五十不爲夭，吾今欠数年。","知分心自足，委顺身常安。","故虽穷退日，而无戚戚颜。","昔有荣先生，从事於其间。","今我不量力，举心欲攀援。","穷通不由己，欢戚不由天。","命即无奈何，心可使泰然。","且务由己者，省躬谅非难。","勿问由天者，天高难与言。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22246":["夜琴","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["蜀[桐]木性实，楚丝音韵清。","调慢弹且缓，夜深十数声。","入耳澹无味，惬心潜有情。","自弄还自罢，亦不要人听。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22247":["山中独吟","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["人各有一癖，我癖在章句。","万缘皆已消，此病独未去。","每逢美风景，或对好亲故。","高声咏一篇，恍若与神遇。","自爲江上客，半在山中住。","有时新诗成，独上东岩路。","身倚白石崖，手攀青桂树。","狂吟惊林壑，猿鸟皆窥覰。","恐爲世所嗤，故就无人处。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22248":["达理二首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何物壮不老，何时穷不通。","如彼音与律，宛转旋爲宫。","我命独何薄，多悴而少丰。","当壮已先衰，暂泰还长穷。","我无奈命何，委顺以待终。","命无奈我何，方寸如虚空。","瞢然与化俱，混然与俗同。","谁能坐自苦，龃龉於其中。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22249":["达理二首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["舒姑化爲泉，牛哀病作虎。","或柳生肘间，或男变爲女。","鸟兽及水木，本不与民伍。","胡然生变迁，不待死归土。","百骸是己物，尚不能爲主。","况彼时命间，倚伏何足数。","时来不可遏，命去焉能取。","唯当养浩然，吾闻达人语。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22250":["湖亭晚望残水","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["湖上秋泬寥，湖边晚萧瑟。","登亭望湖水，水缩湖底出。","清渟得早霜，明灭浮残日。","流注随地势，洼坳无定质。","泓澄白龙卧，宛转青蛇屈。","破镜折劒头，光芒又非一。","久爲山水客，见尽幽奇物。","及来湖亭望，此状难谈悉。","乃知天地间，胜事殊未毕。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22251":["郭虚舟相访","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["朝暖就南轩，暮寒归後屋。","晚酒一两杯，夜棊三数局。","寒灰埋暗火，晓焰凝残烛。","不嫌贫冷人，时来同一宿。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22252":["长庆二年七月自中书舍人出守杭州路次蓝溪作","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["太原一男子，自顾庸且鄙。","老逢不次恩，洗拔出泥滓。","既居可言地，愿助朝廷理。","伏合三上章，戆愚不称旨。","圣人存大体，优贷容不死。","凤诏停舍人，鱼书除刺史。","冥怀齐宠辱，委顺随行止。","我自得此心，於兹十年矣。","余杭乃名郡，郡郭临江汜。","已想海门山，潮声来入耳。","昔予贞元末，羇旅曾游此。","甚觉太守尊，亦谙鱼酒美。","因生江海兴，每羡沧浪水。","尚拟拂衣行，况今兼禄仕。","青山峰峦接，白日烟尘起。","东道既不通，改辕遂南指。","自秦穷楚越，浩荡五千里。","闻有贤主人，而多好山水。","是行颇爲惬，所历良可纪。","策马度蓝溪，胜游从此始。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22253":["初出城留别","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["朝从紫禁归，暮出青门去。","勿言城东陌，便是江南路。","扬鞭簇车马，挥手辞亲故。","我生本无乡，心安是归处。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22254":["过骆山人野居小池","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["茅覆环堵亭，泉添方丈沼。","红芳照水荷，白颈观鱼鸟。","拳石苔苍翠，尺波烟杳渺。","但问有意无，勿论池大小。","门前车马路，奔走无昏晓。","名利驱人心，贤愚同扰扰。","善哉骆处士，安置身心了。","何乃独多君，丘园居者少。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22255":["宿清源寺","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["往谪浔阳去，夜憩辋溪曲。","今爲钱塘行，重经兹寺宿。","尔来几何岁，溪草二八绿。","不见旧房僧，苍然新树木。","虚空走日月，世界迁陵谷。","我生寄其间，孰能逃倚伏。","随缘又南去，好住东廊竹。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22256":["宿蓝溪对月","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昨夜凤池头，今夜蓝溪口。","明月本无心，行人自回首。","新秋松影下，半夜钟声後。","清影不宜昏，聊将茶代酒。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22257":["自秦望赴五松驿马上偶睡睡觉成吟","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["长途发已久，前馆行未至。","体倦目已昏，瞌然遂成睡。","右袂尚垂鞭，左手暂委辔。","忽觉问仆夫，才行百步地。","形神分处所，迟速相乖异。","马上几多时，梦中无限事。","诚哉达人语，百龄同一寐。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22258":["邓州路中作","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["萧萧谁家村，秋棃叶半坼。","漠漠谁家园，秋韭花初白。","路逢故里物，使我嗟行役。","不归渭北村，又作江南客。","去乡徒自苦，济世终无益。","自问波上萍，何如涧中石。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22259":["朱藤杖紫骢吟","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["拄上山之下，骑下山之下。","江州去日朱藤杖，忠州归日紫骢马。","天生二物济我穷，我生合是栖栖者。"],"诗绝如画一笔二笔具得生韵便佳",[["古评·《唐诗镜》","诗绝如画一笔二笔具得生韵便佳"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_22260":["桐树馆重题","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["阶前下马时，梁上题诗处。","惨澹病使君，萧疎老松树。","自嗟还自哂，又向杭州去。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22261":["过紫霞兰若","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["我爱此山头，及此三登历。","紫霞旧精舍，寥落空泉石。","朝市日喧隘，云林长悄寂。","犹存住寺僧，肯有归山客。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22262":["感旧纱帽","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昔君乌纱帽，赠我白头翁。","帽今在顶上，君已归泉中。","物故犹堪用，人亡不可逢。","岐山今夜月，坟树正秋风。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22263":["思竹窗","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["不忆西省松，不忆南宫菊。","惟忆新昌堂，萧萧北窗竹。","窗间枕簟在，来後何人宿。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22264":["马上作","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["处世非不遇，荣身颇有余。","勳爲上柱国，爵乃朝大夫。","自问有何才，两入承明庐。","又问有何政，再驾朱轮车。","矧予东山人，自惟朴且疎。","弹琴复有酒，且慕嵇阮徒。","暗被乡里荐，误上贤能书。","一列朝士籍，遂爲世网拘。","高有罾缴忧，下有陷穽虞。","每觉宇宙窄，未尝心体舒。","蹉跎二十年，颔下生白须。","何言左迁去，尚获专城居。","杭州五千里，往若投渊鱼。","虽未脱簪组，且来泛江湖。","吴中多诗人，亦不少酒酤。","高声咏篇什，大笑飞杯盂。","五十未全老，尚可且欢娱。","用兹送日月，君以爲何如。","秋风起江上，白日落路隅。","回首语五马，去矣勿踟蹰。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22265":["秋蝶","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["秋花紫蒙蒙，秋蝶黄茸茸。","花低蝶新小，飞戏丛西东。","日暮凉风来，纷纷花落丛。","夜深白露冷，蝶已死丛中。","朝生夕俱死，气类各相从。","不见千年鹤，多栖百丈松。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22266":["登商山最高顶","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["高高此山顶，四望唯烟云。","下有一条路，通达楚与秦。","或名诱其心，或利牵其身。","乘者及负者，来去何云云。","我亦斯人徒，未能出嚣尘。","七年三往复，何得笑他人。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22267":["枯桑","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["道傍老枯树，枯来非一朝。","皮黄外尚活，心黑中先焦。","有似多忧者，非因外火烧。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22268":["山路偶兴","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["筋力未全衰，仆马不至弱。","又多山水趣，心赏非寂莫。","扪萝上烟岭，蹋石穿云壑。","谷鸟晚仍啼，洞花秋不落。","提笼复携榼，遇胜时停泊。","泉憩茶数瓯，岚行酒一酌。","独吟还独啸，此兴殊未恶。","假使在城时，终年有何乐。"],"谷鸟二语风味极佳泉憇二语格虽晚要不乏趣",[["古评·《唐诗镜》","谷鸟二语风味极佳泉憇二语格虽晚要不乏趣"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_22269":["山雉","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["五步一啄草，十步一饮水。","适性遂其生，时哉山梁雉。","梁上无罾缴，梁下无鹰鸇。","雌雄与羣雏，皆得终天年。","嗟嗟笼下鸡，及彼池中鴈。","既有稻粱恩，必有牺牲患。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22270":["初下汉江舟中作寄两省给舍","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["秋水淅红粒，朝烟烹白鳞。","一食饱至夜，一卧安达晨。","晨无朝谒劳，夜无直宿勤。","不知两掖客，何似扁舟人。","尚想到郡日，且称守土臣。","犹须副忧寄，恤隐安疲民。","朞年庶报政，三年当退身。","终使沧浪水，濯吾缨上尘。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22271":["自蜀江至洞庭湖口有感而作","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江从西南来，浩浩无旦夕。","长波逐若泻，连山凿如劈。","千年不壅溃，万姓无垫溺。","不尔民爲鱼，大哉禹之绩。","导岷既艰远，距海无咫尺。","胡爲不讫功，余水斯委积。","洞庭与青草，大小两相敌。","混合万丈深，淼茫千里白。","每岁秋夏时，浩大吞七泽。","水族窟穴多，农人土地窄。","我今尚嗟叹，禹岂不爱惜。","邈未究其由，想古观遗迹。","疑此苗人顽，恃险不终役。","帝亦无奈何，留患与今昔。","水流天地内，如身有血脉。","滞则爲疽疣，治之在鍼石。","安得禹复生，爲唐水官伯。","手提倚天劒，重来亲指画。","疏河似翦纸，决壅同裂帛。","渗作膏腴田，蹋平鱼鼈宅。","龙宫变闾里，水府生禾麦。","坐添百万户，书我司徒籍。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22272":["初领郡政衙退登东楼作","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["鳏惸心所念，简牍手自操。","何言符竹贵，未免州县劳。","赖是余杭郡，台榭绕官曹。","凌晨亲政事，向晚恣游遨。","山冷微有雪，波平未生涛。","水心如镜面，千里无纤毫。","直下江最阔，近东楼更高。","烦襟与滞念，一望皆遁逃。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22273":["清调吟","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["索索风戒寒，沈沈日藏耀。","劝君饮浊醪，听我吟清调。","芳节变穷阴，朝光成夕照。","与君生此世，不合长年少。","今晨从此过，明日安能料。","若不结跏禅，即须开口笑。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22274":["狂歌词","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["明月照君席，白露沾我衣。","劝君酒杯满，听我狂歌词。","五十已後衰，二十已前痴。","昼夜又分半，其间几何时。","生前不欢乐，死後有余赀。","焉用黄墟下，珠衾玉匣爲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22275":["郡亭","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["平旦起视事，亭午卧掩关。","除亲簿领外，多在琴书前。","况有虚白亭，坐见海门山。","潮来一凭槛，宾至一开筵。","终朝对云水，有时听管弦。","持此聊过日，非忙亦非闲。","山林太寂莫，朝阙空喧烦。","唯兹郡合内，嚣静得中间。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22276":["咏怀","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昔爲凤合郎，今爲二千石。","自觉不如今，人言不如昔。","昔虽居近密，终日多忧惕。","有诗不敢吟，有酒不敢吃。","今虽在疎远，竟岁无牵役。","饱食坐终朝，长歌醉通夕。","人生百年内，疾速如过隙。","先务身安闲，次要心欢适。","事有得而失，物有损而益。","所以见道人，观心不观迹。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22277":["立春後五日","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["立春後五日，春态纷婀娜。","白日斜渐长，碧云低欲堕。","残冰坼玉片，新萼排红颗。","遇物尽欣欣，爱春非独我。","迎芳後园立，就暖前檐作。","还有惆怅心，欲别红炉火。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22278":["郡中即事","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["漫漫潮初平，熙熙春日至。","空阔远江山，晴明好天气。","外有适意物，中无系心事。","数篇对竹吟，一杯望云醉。","行携杖扶力，卧读书取睡。","久养病形骸，深谙闲气味。","遥思九城陌，扰扰趋名利。","今朝是双日，朝谒多轩骑。","宠者防悔尤，权者怀忧畏。","爲报高车盖，恐非真富贵。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22279":["郡斋暇日辱常州陈郎中使君早春晚坐水西馆书事诗十六韵见寄亦以十六韵酬之","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["新年多暇日，晏起褰帘坐。","睡足心更慵，日高头未裹。","徐倾下药酒，稍爇煎茶火。","谁伴寂寥身，无弦琴在左。","遥思毘陵馆，春深物嫋娜。","波拂黄柳梢，风摇白梅朵。","衙门排晓戟，铃阁开朝锁。","太守水西来，朱衣垂素舸。","良辰不易得，佳会无由果。","五马正相望，双鱼忽前堕。","鱼中获瑰宝，持玩何磊砢。","一百六十言，字字灵珠颗。","上申心款曲，下叙时轗轲。","才富不如君，道孤还似我。","敢辞官远慢，且贵身安妥。","勿复问荣枯，冥心无不可。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22280":["官舍","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["高树换新叶，阴阴覆地隅。","何言太守宅，有似幽人居。","太守卧其下，闲慵两有余。","起尝一瓯茗，行读一卷书。","早梅结青实，残樱落红珠。","穉女弄庭果，嬉戏牵人裾。","是日晚弥静，巢禽下相呼。","啧啧护儿鹊，哑哑母子乌。","岂唯云鸟尔，吾亦引吾雏。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22281":["吾雏","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["吾雏字阿罗，阿罗才七龄。","嗟吾不才子，怜尔无弟兄。","抚养虽骄騃，性识颇聪明。","学母画眉样，效吾咏诗声。","我齿今欲堕，汝齿昨始生。","我头发尽落，汝顶髻初成。","老幼不相待，父衰汝孩婴。","缅想古人心，慈爱亦不轻。","蔡邕念文姬，于公叹缇萦。","敢求得汝力，但未忘父情。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22282":["题小桥前新竹招客","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["鴈齿小红桥，垂檐低白屋。","桥前何所有，苒苒新生竹。","皮开坼褐锦，节露抽青玉。","筠翠如可餐，粉霜不忍触。","闲吟声未已，幽玩心难足。","管领好风烟，轻欺凡草木。","谁能有月夜，伴我林中宿。","爲君倾一杯，狂歌竹枝曲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22283":["病中逢秋招客夜酌","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["不见诗酒客，卧来半月余。","合和新药草，寻检旧方书。","晚霁烟景度，早凉窗户虚。","雪生衰鬓久，秋入病心初。","卧簟蕲竹冷，风襟邛葛疎。","夜来身校健，小饮复何如。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22284":["食饱","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["食饱拂枕卧，睡足起闲吟。","浅酌一杯酒，缓弹数弄琴。","既可畅情性，亦足傲光阴。","谁知利名尽，无复长安心。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22285":["严十八郎中在郡日改制东南楼因名清辉未立标牓徵归郎署予既到郡性爱楼居宴游其间颇有幽致聊成十韵兼戏寄严","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["严郎置兹楼，立名曰清辉。","未及署花牓，遽徵还粉闱。","去来三四年，尘土登者稀。","今春新太守，洒埽施帘帏。","院柳烟婀娜，檐花雪霏微。","看山倚前户，待月阐东扉。","碧窗戛瑶瑟，朱阑飘舞衣。","烧香卷幕坐，风燕双双飞。","君作不得住，我来幸因依。","始知天地间，灵境有所归。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22286":["南亭对酒送春","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["含桃实已落，红薇花尚熏。","冉冉三月尽，晚莺城上闻。","独持一杯酒，南亭送残春。","半酣忽长歌，歌中何所云。","云我五十余，未是苦老人。","刺史二千石，亦不爲贱贫。","天下三品官，多老於我身。","同年登第者，零落无一分。","亲故半爲鬼，僮仆多见孙。","念此聊自解，逢酒且欢欣。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22287":["玩新庭树因咏所怀","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["霭霭四月初，新树叶成阴。","动摇风景丽，盖覆庭院深。","下有无事人，竟日此幽寻。","岂惟玩时物，亦可开烦襟。","时与道人语，或听诗客吟。","度春足芳色，入夜多鸣禽。","偶得幽闲境，遂忘尘俗心。","始知真隐者，不必在山林。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22288":["仲夏斋戒月","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["仲夏斋戒月，三旬断腥羶。","自觉心骨爽，行起身翩翩。","始知绝粒人，四体更轻便。","初能脱病患，久必成神仙。","御寇驭[泠]风，赤松游紫烟。","常疑此说谬，今乃知其然。","我今过半百，气衰神不全。","已垂两鬓丝，难补三丹田。","但减荤血味，稍结清净缘。","脱巾且修养，聊以终天年。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22289":["除官去未间","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["除官去未间，半月恣游讨。","朝寻霞外寺，暮宿波上岛。","新树少於松，平湖半连草。","跻攀有次第，赏玩无昏早。","有时骑马醉，兀兀冥天造。","穷通与生死，其奈吾怀抱。","江山信爲美，齿发行将老。","在郡诚未厌，归乡去亦好。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22290":["三年爲刺史二首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["三年爲刺史，无政在人口。","唯向城郡中，题诗十余首。","慙非甘棠咏，岂有思人不。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22291":["三年爲刺史二首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["三年爲刺史，饮冰复食檗。","唯向天竺山，取得两片石。","此抵有千金，无乃伤清白。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22292":["别萱桂","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["使君竟不住，萱桂徒栽种。","桂有留人名，萱无忘忧用。","不如江畔月，步步来相送。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22293":["自余杭归宿淮口作","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["爲郡已多暇，犹少勤吏职。","罢郡更安闲，无所劳心力。","舟行明月下，夜泊清淮北。","岂止吾一身，举家同燕息。","三年请禄俸，颇有余衣食。","乃至僮仆间，皆无冻馁色。","行行弄云水，步步近乡国。","妻子在我前，琴书在我侧。","此外吾不知，於焉心自得。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22294":["舟中李山人访宿","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["日暮舟悄悄，烟生水沈沈。","何以延宿客，夜酒与秋琴。","来客道门子，来自嵩高岑。","轩轩举云貌，豁豁开清襟。","得意言语断，入玄滋味深。","默然相顾哂，心适而忘心。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22295":["洛下卜居","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["三年典郡归，所得非金帛。","天竺石两片，华亭鹤一只。","饮啄供稻粱，包裹用茵席。","诚知是劳费，其奈心爱惜。","远从余杭郭，同到洛阳陌。","下担拂云根，开笼展霜翮。","贞姿不可杂，高性宜其适。","遂就无尘坊，仍求有水宅。","东南得幽境，树老寒泉碧。","池畔多竹阴，门前少人迹。","未请中庶禄，且脱双骖易。","岂独爲身谋，安吾鹤与石。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22296":["洛中偶作","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["五年职翰林，四年涖浔阳。","一年巴郡守，半年南宫郎。","二年直纶合，三年刺史堂。","凡此十五载，有诗千余章。","境兴周万象，土风备四方。","独无洛中作，能不心悢悢。","今爲青宫长，始来游此乡。","裴回伊涧上，睥睨嵩少傍。","遇物辄一咏，一咏倾一觞。","笔下成释憾，卷中同补亡。","往往顾自哂，眼昏须鬓苍。","不知老将至，犹自放诗狂。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22297":["赠苏少府","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["籍甚二十年，今日方款颜。","相送嵩洛下，论心杯酒间。","河亚嬾出入，府寮多闭关。","苍发彼此老，白日寻常闲。","朝从携手出，暮思联骑还。","何当挈一榼，同宿龙门山。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22298":["移家入新宅","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["移家入新宅，罢郡有余赀。","既可避燥湿，复免忧寒饥。","疾平未还假，官闲得分司。","幸有俸禄在，而无职役羁。","清旦盥漱毕，开轩卷帘帏。","家人及鸡犬，随我亦熙熙。","取兴或寄酒，放情不过诗。","何必苦修道，此即是无爲。","外累信已遣，中怀时有思。","有思一何远，默坐低双眉。","十载囚窜客，万里征戍儿。","春朝鏁笼鸟，冬夜支牀龟。","驿马走四蹄，痛酸无歇期。","磑牛封两目，昏闭何人知。","谁能脱放去，四散任所之。","各得适其性，如吾今日时。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22299":["琴","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["置琴曲几上，慵坐但含情。","何烦故挥弄，风弦自有声。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22300":["鹤","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["人各有所好，物固无常宜。","谁谓尔能舞，不如闲立时。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22301":["自咏","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["夜镜隐白发，朝酒发红颜。","可怜假年少，自笑须臾间。","朱砂贱如土，不解烧爲丹。","玄鬓化爲雪，未闻休得官。","咄哉个丈夫，心性何堕顽。","但遇诗与酒，便忘寝与餐。","高声发一吟，似得诗中仙。","引满饮一醆，尽忘身外缘。","昔有醉先生，席地而幕天。","于今居处在，许我当中眠。","眠罢又一酌，酌罢又一篇。","回面顾妻子，生计方落然。","诚知此事非，又过知非年。","岂不欲自改，改即心不安。","且向安处去，其余皆老闲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22302":["林下闲步寄皇甫庶子","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["扶杖起病初，策马力未任。","既嬾出门去，亦无客来寻。","以此遂成闲，闲步绕园林。","天晓烟景澹，树寒鸟雀深。","一酌池上酒，数声竹间吟。","寄言东曹长，当知幽独心。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22303":["晏起","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["鸟鸣庭树上，日照屋檐时。","老去慵转极，寒来起尤迟。","厚薄被适性，高低枕得宜。","神安体稳暖，此味何人知。","睡足仰头坐，兀然无所思。","如未凿七窍，若都遗四肢。","缅想长安客，早朝霜满衣。","彼此各自适，不知谁是非。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22304":["池畔二首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["结构池西廊，疏理池东树。","此意人不知，欲爲待月处。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22305":["池畔二首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["持刀𠜴密竹，竹少风来多","此意人不会，欲令池有波。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22306":["春葺新居","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江州司马日，忠州刺史时。","栽松满後院，种柳荫前墀。","彼皆非吾土，栽种尚忘疲。","况兹是我宅，葺艺固其宜。","平旦领仆使，乘春亲指挥。","移花夹暖室，徙竹覆寒池。","池水变绿色，池芳动清辉。","寻芳弄水坐，尽日心熙熙。","一物苟可适，万缘都若遗。","设如宅门外，有事吾不知。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22307":["赠言","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["捧籯献千金，彼金何足道。","临觞赠一言，此言真可宝。","流光我已晚，适意君不早。","况君春风面，柔促如芳草。","二十方长成，三十向衰老。","镜中桃李色，不得十年好。","胡爲坐脉脉，不肯倾怀抱。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22308":["泛春池","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["白苹湘渚曲，绿筱剡溪口。","各在天一涯，信美非吾有。","何如此庭内，水竹交左右。","霜竹百千竿，烟波六七亩。","泓澄动阶砌，澹泞映户牖。","蛇皮细有纹，镜面清无垢。","主人过桥来，双童扶一叟。","恐汚清泠波，尘缨先抖擞。","波上一叶舟，舟中一尊酒。","酒开舟不系，去去随所偶。","或绕蒲浦前，或泊桃岛後。","未拨落杯花，低冲拂面柳。","半酣迷所在，倚榜兀回首。","不知此何处，复是人寰否。","谁知始疏凿，几主相传受。","杨家去云远，田氏将非久。","天与爱水人，终焉落吾手。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22309":["西明寺牡丹花时忆元九","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["前年题名处，今日看花来。","一作芸香吏，三见牡丹开。","岂独花堪惜，方知老闇催。","何况寻花伴，东都去未回。","讵知红芳侧，春尽思悠哉。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22310":["伤杨弘贞","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["颜子昔短命，仲尼惜其贤。","杨生亦好学，不幸复徒然。","谁识天地意，独与龟鹤年。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22311":["权摄昭应早秋书事寄元拾遗兼呈李司录","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["夏闰秋候早，七月风骚骚。","渭川烟景晚，骊山宫殿高。","丹殿子司谏，赤县我徒劳。","相去半日程，不得同游遨。","到官来十日，览镜生二毛。","可怜趋走吏，尘土满青袍。","邮传拥两驿，簿书堆六曹。","爲问纲纪掾，何必使铅刀。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22312":["新栽竹","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["佐邑意不适，闭门秋草生。","何以娱野性，种竹百余茎。","见此溪上色，忆得山中情。","有时公事暇，尽日绕阑行。","勿言根未固，勿言阴未成。","已觉庭宇内，稍稍有余清。","最爱近窗卧，秋风枝有声。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22313":["秋霖中过尹纵之仙游山居","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["惨惨八月暮，连连三日霖。","邑居尚愁寂，况乃在山林。","林下有志士，苦学惜光阴。","岁晚千万虑，幷入方寸心。","岩鸟共旅宿，草虫伴愁吟。","秋天牀席冷，夜雨灯火深。","怜君寂莫意，携酒一相寻。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22314":["寄江南兄弟","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["分散骨肉恋，趋驰名利牵。","一奔尘埃马，一泛风波船。","忽忆分手时，悯默秋风前。","别来朝复夕，积日成七年。","花落城中池，春深江上天。","登楼东南望，鸟灭烟苍然。","相去复几许，道里近三千。","平地犹难见，况乃隔山川。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22315":["曲江早秋","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["秋波红蓼水，夕照青芜岸。","独信马蹄行，曲江池四畔。","早凉晴後至，残暑暝来散。","方喜炎燠销，复嗟时节换。","我年三十六，冉冉昏复旦。","人寿七十稀，七十新过半。","且当对酒笑，勿起临风叹。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22316":["寄题盩厔厅前双松","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["忆昨爲吏日，折腰多苦辛。","归来不自适，无计慰心神。","手栽两树松，聊以当嘉宾。","乘春日一溉，生意渐欣欣。","清韵度秋在，绿茸随日新。","始怜涧底色，不忆城中春。","有时昼掩关，双影对一身。","尽日不寂莫，意中如三人。","忽奉宣室诏，徵爲文苑臣。","闲来一惆怅，恰似别交亲。","早知烟翠前，攀玩不逡巡。","悔从白云里，移尔落嚣尘。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22317":["翰林院中感秋怀王质夫","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["何处感时节，新蝉禁中闻。","宫槐有秋意，风夕花纷纷。","寄迹鸳鹭行，归心鸥鹤羣。","唯有王居士，知予忆白云。","何日仙游寺，潭前秋见君。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22318":["禁中月","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["海水明月出，禁中清夜长。","东南楼殿白，稍稍上宫墙。","净落金塘水，明浮玉砌霜。","不比人间见，尘土汚清光。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22319":["赠卖松者","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["一束苍苍色，知从涧底来。","斸掘经几日，枝叶满尘埃。","不买非他意，城中无地栽。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22320":["初见白发","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["白发生一茎，朝来明镜里。","勿言一茎少，满头从此始。","青山方远别，黄绶初从仕。","未料容鬓间，蹉跎忽如此。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22321":["别元九後咏所怀","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["零落桐叶雨，萧条槿花风。","悠悠早秋意，生此幽闲中。","况与故人别，中怀正无悰。","勿云不相送，心到青门东。","相知岂在多，但问同不同。","同心一人去，坐觉长安空。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22322":["禁中秋宿","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["风飜朱里幕，雨冷通中枕。","耿耿背斜灯，秋牀一人寝。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22323":["早秋曲江感怀","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["离离暑云散，嫋嫋凉风起。","池上秋又来，荷花半成子。","朱颜易销歇，白日无穷已。","人寿不如山，年光忽於水。","青芜与红蓼，岁岁秋相似。","去岁此悲秋，今秋复来此。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22324":["寄元九","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["身爲近密拘，心爲名检缚。","月夜与花时，少逢杯酒乐。","唯有元夫子，闲来同一酌。","把手或酣歌，展眉时笑谑。","今春除御史，前月之东洛。","别来未开颜，尘埃满尊杓。","蕙风晚香尽，槐雨余花落。","秋意一萧条，离容两寂莫。","况随白日老，共负青山约。","谁识相念心，韝鹰与笼鹤。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22325":["暮春寄元九","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["棃花结成实，燕卵化爲雏。","时物又若此，道情复何如。","但觉日月促，不嗟年岁徂。","浮生都是梦，老小亦何殊。","唯与故人别，江陵初谪居。","时时一相见，此意未全除。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22326":["早梳头","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["夜沐早梳头，窗明秋镜晓。","飒然握中发，一沐知一少。","年事渐蹉跎，世缘方缴绕。","不学空门法，老病何由了。","未得无生心，白头亦爲夭。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22327":["出关路","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["山川函谷路，尘土游子颜。","萧条去国意，秋风生故关。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22328":["别舍弟後月夜","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["悄悄初别夜，去住两盘桓。","行子孤灯店，居人明月轩。","平生共贫苦，未必日成欢。","及此暂爲别，怀抱已忧烦。","况是庭叶尽，复思山路寒。","如何爲不念，马瘦衣裳单。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22329":["新丰路逢故人","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["尘土长路晚，风烟废宫秋。","相逢立马语，尽日此桥头。","知君不得意，郁郁来西游。","惆怅新丰店，何人识马周。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22330":["金銮子晬日","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["行年欲四十，有女曰金銮。","生来始周岁，学坐未能言。","慙非达者怀，未免俗情怜。","从此累身外，徒云慰目前。","若无夭折患，则有婚嫁牵。","使我归山计，应迟十五年。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22331":["青龙寺早夏","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["尘埃经小雨，地高倚长坡。","日西寺门外，景气含清和。","闲有老僧立，静无凡客过。","残莺意思尽，新叶阴凉多。","春去来几日，夏云忽嵯峨。","朝朝感时节，年鬓闇蹉跎。","胡爲恋朝市，不去归烟萝。","青山寸步地，自问心如何。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22332":["秋题牡丹丛","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["晚丛白露夕，衰叶凉风朝。","红艳久已歇，碧芳今亦销。","幽人坐相对，心事共萧条。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22333":["劝酒寄元九","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["薤叶有朝露，槿枝无宿花。","君今亦如此，促促生有涯。","既不逐禅僧，林下学楞伽。","又不随道士，山中链丹砂。","百年夜分半，一岁春无多。","何不饮美酒？胡然自悲嗟。","俗号销愁药，神速无以加。","一杯驱世虑，两杯反天和。","三杯即酩酊，或笑任狂歌。","陶陶复兀兀，吾孰知其他。","况在名利途，平生有风波。","深心藏陷穽，巧言织网罗。","举目非不见，不醉欲如何。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22334":["曲江感秋","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["沙草新雨地，岸柳凉风枝。","三年感秋意，幷在曲江池。","早蝉已嘹唳，晚荷复离披。","前秋去秋思，一一生此时。","昔人三十二，秋兴已云悲。","我今欲四十，秋怀亦可知。","岁月不虚设，此身随日衰。","闇老不自觉，直到鬓成丝。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22335":["酬张太祝晚秋卧病见寄","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["高才淹礼寺，短羽翔禁林。","西街居处远，北阙官曹深。","君病不来访，我忙难往寻。","差池终日别，寥落经年心。","露湿绿芜地，月寒红树阴。","况兹独愁夕，闻彼相思吟。","上叹言笑阻，下嗟时岁侵。","容衰晓窗镜，思苦秋弦琴。","一章锦绣段，八韵琼瑶音。","何以报珍重，慙无双南金。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22336":["立秋日曲江忆元九","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["下马柳阴下，独上堤上行。","故人千万里，新蝉三两声。","城中曲江水，江上江陵城。","两地新秋思，应同此日情。"],"",[],{"source":"李亮伟","body":["中间两联写景寄情，分别一句写元稹所在地，一句写自己眼前景，应对题目，立足曲江实景展开“忆”，两相关合。友情的纽带，将两地连通。最后两句作绾结，说两人虽身在异地，此日彼此相思，情感相同。此言不虚，因为两人都有这样同日思念对方的印证或感念，如前所举白居易《同李十一醉忆元九》和元稹《纪梦诗》；又如白居易《初与元九别后忽梦见之。及寤而书适至，兼寄》说：“晓来梦见君，应是君相忆。”","友情深挚如此，“元白”之交，难怪乎被后人称美不已。“慕路回之言赠，念元白之神交”（明李东阳《西社别言诗引》），“缅怀元白交，千里梦魂依”（清魏裔介《寄杨犹龙》），后代以为楷模。"]},[],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》（清·曹寅等编，康熙扬州诗局本）"]],"open_22337":["早朝贺雪寄陈山人","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["长安盈尺雪，早朝贺君喜。","将赴银台门，始出新昌里。","上堤马蹄滑，中路蜡烛死。","十里向北行，寒风吹破耳。","待漏午门外，候对三殿里。","须鬓冻生冰，衣裳冷如水。","忽思仙游谷，闇谢陈居士。","暖覆褐裘眠，日高应未起。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22338":["初与元九别後忽梦见之及寤而书适至兼寄桐花诗怅然感怀因以此寄","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["永寿寺中语，新昌坊北分。","归来数行泪，悲事不悲君。","悠悠蓝田路，自去无消息。","计君食宿程，已过商山北。","昨夜云四散，千里同月色。","晓来梦见君，应是君相忆。","梦中握君手，问君意何如。","君言苦相忆，无人可寄书。","觉来未及说，叩门声冬冬。","言是商州使，送君书一封。","枕上忽惊起，颠倒着衣裳。","开缄见手札，一纸十三行。","上论迁谪心，下说离别肠。","心肠都未尽，不暇叙炎凉。","云作此书夜，夜宿商州东。","独对孤灯坐，阳城山馆中。","夜深作书毕，山月向西斜。","月下何所有，一树紫桐花。","桐花半落时，复道正相思。","殷勤书背後，兼寄桐花诗。","桐花诗八韵，思绪一何深。","以我今朝意，忆君此夜心。","一章三徧读，一句十回吟。","珍重八十字，字字化爲金。"],"",[["古注·《才調集》","元九初谪江陵"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《才调集》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/才調集_(四庫全書本)）"]],"open_22339":["和元九悼往","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["美人别君去，自去无处寻。","旧物零落尽，此情安可任。","唯有襭纱幌，尘埃日夜侵。","馨香与颜色，不似旧时深。","透影灯耿耿，笼光月沈沈。","中有孤眠客，秋凉生夜衾。","旧宅牡丹院，新坟松柏林。","梦中咸阳泪，觉後江陵心。","含此隔年恨，发爲中夜吟。","无论君自感，闻者欲沾襟。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22340":["重到渭上旧居","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["旧居清渭曲，开门当蔡渡。","十年方一还，几欲迷归路。","追思昔日行，感伤故游处。","插柳作高林，种桃成老树。","因惊成人者，尽是旧童孺。","试问旧老人，半爲绕村墓。","浮生同过客，前後递来去。","白日如弄珠，出没光不住。","人物日改变，举目悲所遇。","回念念我身，安得不衰暮。","朱颜销不歇，白发生无数。","唯有山门外，三峰色如故。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22341":["白发","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["白发知时节，闇与我有期。","今朝日阳裹，梳落数茎丝。","家人不惯见，悯默爲我悲。","我云何足怪，此意尔不知。","凡人年三十，外壮中已衰。","但思寝食味，已减二十时。","况我今四十，本来形貌羸。","书魔昏两眼，酒病沈四肢。","亲爱日零落，在者仍别离。","身心久如此，白发生已迟。","由来生老死，三病长相随。","除却念无生，人间无药治。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22342":["秋日","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["池残寥落水，窗下悠杨日。","嫋嫋秋风多，槐花半成实。","下有独立人，年来四十一。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22343":["将之饶州江浦夜泊","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["明月满深浦，愁人卧孤舟。","烦冤寝不得，夏夜长於秋。","苦乏衣食资，远爲江海游。","光阴坐迟暮，乡国行阻修。","身病向鄱阳，家贫寄徐州。","前事与後事，岂堪心幷忧。","忧来起长望，但见江水流。","云树霭苍苍，烟波澹悠悠。","故园迷处所，一念堪白头。"],"",[["古评·《唐诗镜》","语有苍色"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_22344":["思归","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["养无晨昏膳，隐无伏腊资。","遂求及亲禄，僶俛来京师。","薄俸未及亲，别家已经时。","冬积温席恋，春违采兰期。","夏至一阴生，稍稍夕漏迟。","块然抱愁者，长夜独先知。","悠悠乡关路，梦去身不随。","坐惜时节变，蝉鸣槐花枝。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22345":["冀城北原作","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["野色何莽苍，秋声亦萧疎。","风吹黄埃起，落日驱征车。","何代此开国，封疆百里余。","古今不相待，朝市无常居。","昔人城邑中，今变爲丘墟。","昔人墓田中，今化爲里闾。","废兴相催迫，日月互居诸。","世变无遗风，焉能知其初。","行人千载後，怀古空踌躇。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22346":["客路感秋寄明准上人","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["日暮天地冷，雨霁山河清。","长风从西来，草木凝秋声。","已感岁倏忽，复伤物凋零。","孰能不憯凄，天时牵人情。","借问空门子，何法易修行。","使我忘得心，不教烦恼生。"],"孰能不憯凄天时牵人情知其随时感动中固无根诗道人情无意中逗漏如此",[["古评·《唐诗镜》","孰能不憯凄天时牵人情知其随时感动中固无根诗道人情无意中逗漏如此"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_22347":["游襄阳怀孟浩然","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["楚山碧岩岩，汉水碧汤汤。","秀气结成象，孟氏之文章。","今我讽遗文，思人至其乡。","清风无人继，日暮空襄阳。","南望鹿门山，蔼若有余芳。","旧隐不知处，云深树苍苍。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22348":["秋暮西归途中书情","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["耿耿旅灯下，愁多常少眠。","思乡贵早发，发在鸡鸣前。","九月草木落，平芜连远山。","秋阴和曙色，万木苍苍然。","去秋偶东游，今秋始西旋。","马瘦衣裳破，别家来二年。","忆归复愁归，归无一囊钱。","心虽非兰膏，安得不自然。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22349":["秋怀","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["月出照北堂，光华满阶墀。","凉风从西至，草木日夜衰。","桐柳减绿阴，蕙兰消碧滋。","感物私自念，我心亦如之。","安得长少壮，盛衰迫天时。","人生如石火，爲乐长苦迟。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22350":["别杨颖士卢克柔殷尧藩","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["倦鸟暮归林，浮云晴归山。","独有行路子，悠悠不知还。","人生苦营营，终日羣动间。","所务虽不同，同归於不闲。","扁舟来楚乡，匹马往秦关。","离忧绕心曲，宛转如循环。","且持一杯酒，聊以开愁颜。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22351":["题赠定光上人","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["二十身出家，四十心离尘。","得径入大道，乘此不退轮。","一坐十五年，林下秋复春。","春花与秋气，不感无情人。","我来如有悟，潜以心照身。","误落闻见中，忧喜伤形神。","安得遗耳目，冥然反天真。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22352":["只役骆口驿喜萧侍御书至兼覩新诗吟讽通宵因寄八韵","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["日暮心无憀，吏役正营营。","忽惊芳信至，复与新诗幷。","是时天无云，山馆有月明。","月下读数徧，风前吟一声。","一吟三四叹，声尽有余清。","雅哉君子文，咏性不咏情。","使我灵府中，鄙恡不得生。","始知听韶濩，可使心和平。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22353":["酬李少府曹长官舍见赠","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["低腰复敛手，心体不遑安。","一落风尘下，方知爲吏难。","公事与日长，宦情随岁阑。","惆怅青袍袖，芸香无半残。","赖有李夫子，此怀聊自宽。","两心如止水，彼此无波澜。","往往簿书暇，相劝强爲欢。","白马晚蹋雪，渌觞春暖寒。","恋月夜同宿，爱山晴共看。","野性自相近，不是爲同官。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22354":["留别","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["秋凉卷朝簟，春暖撤夜衾。","虽是无情物，欲别尚沈吟。","况与有情别，别随情浅深。","二年欢笑意，一旦东西心。","独留诚可念，同行力不任。","前事讵能料，後期谅难寻。","唯有潺湲泪，不惜共沾襟。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22355":["晓别","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["晓鼓声已半，离筵坐难久。","请君断肠歌，送我和泪酒。","月落欲明前，马嘶初别後。","浩浩暗尘中，何由见回首。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22356":["北园","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["北园东风起，杂花次第开。","心知须臾落，一日三四来。","花下岂无酒，欲酌复迟回。","所思眇千里，谁劝我一杯。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22357":["惜栯李花","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["树小花鲜妍，香繁条輭弱。","高低二三尺，重叠千万萼。","朝艳蔼霏霏，夕凋纷漠漠。","辞枝朱粉细，覆地红绡薄。","由来好颜色，常苦易销铄。","不见莨荡花，狂风吹不落。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22358":["照镜","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["皎皎青铜镜，斑斑白丝鬓。","岂复更藏年，实年君不信。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22359":["新秋","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["西风飘一叶，庭前飒已凉。","风池明月水，衰莲白露房。","其奈江南夜，緜緜自此长。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22360":["夜雨","白居易","五言绝句","约元和间","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["早蛩啼复歇，残灯灭又明。","隔窗知夜雨，芭蕉先有声。"],"",[],{},[["隔窗知夜雨，芭蕉先有声。","写雨名句，以声写静。"]],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》卷四四〇","《唐诗鉴赏辞典》白居易条（上海辞书出版社，1983）","《全唐诗》（清·曹寅等编，康熙扬州诗局本）"]],"open_22361":["秋江送客","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["秋鸿次第过，哀猨朝夕闻。","是日孤舟客，此地亦离羣。","蒙蒙润衣雨，漠漠冒帆云。","不醉浔阳酒，烟波愁杀人。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22362":["感逝寄远","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昨日闻甲死，今朝闻乙死。","知识三分中，二分化爲鬼。","逝者不复见，悲哉长已矣。","存者今如何，去我皆万里。","平生知心者，屈指能有几。","通果澧凤州，眇然四君子。","相思俱老大，浮世如流水。","应叹旧交游，凋零日如此。","何当一杯酒，开眼笑相视。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22363":["秋月","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["夜初色苍然，夜深光浩然。","稍转西廊下，渐满南窗前。","况是绿芜地，复兹清露天。","落叶声策策，惊鸟影翩翩。","栖禽尚不稳，愁人安可眠。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22364":["朱陈村","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["徐州古丰县，有村曰朱陈。","去县百余里，桑麻青氛氲。","机梭声札札，牛驴走纭纭。","女汲涧中水，男采山上薪。","县远官事少，山深人俗淳。","有财不行商，有丁不入军。","家家守村业，头白不出门。","生爲村之民，死爲村之尘。","田中老与幼，相见何欣欣。","一村唯两姓，世世爲婚姻。","亲疎居有族，少长游有羣。","黄鸡与白酒，欢会不隔旬。","生者不远别，嫁娶先近邻。","死者不远葬，坟墓多绕村。","既安生与死，不苦形与神。","所以多寿考，往往见玄孙。","我生礼义乡，少小孤且贫。","徒学辨是非，祗自取辛勤。","世法贵名教，士人重冠婚。","以此自桎梏，信爲大谬人。","十岁解读书，十五能属文。","二十举秀才，三十爲谏臣。","下有妻子累，上有君亲恩。","承家与事国，望此不肖身。","忆昨旅游初，迨今十五春。","孤舟三适楚，羸马四经秦。","昼行有饥色，夜寝无安魂。","东西不暂住，来往若浮云。","离乱失故乡，骨肉多散分。","江南与江北，各有平生亲。","平生终日别，逝者隔年闻。","朝忧卧至暮，夕哭坐达晨。","悲火烧心曲，愁霜侵鬓根。","一生苦如此，长羡村中民。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22365":["读邓鲂诗","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["尘架多文集，偶取一卷披。","未及看姓名，疑是陶潜诗。","看名知是君，恻恻令我悲。","诗人多蹇厄，近日诚有之。","京兆杜子美，犹得一拾遗。","襄阳孟浩然，亦闻鬓成丝。","嗟君两不如，三十在布衣。","擢第禄不及，新婚妻未归。","少年无疾患，溘死於路岐。","天不与爵寿，唯与好文词。","此理勿复道，巧历不能推。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22366":["寄元九","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["晨鸡才发声，夕雀俄敛翼。","昼夜往复来，疾如出入息。","非徒改年貌，渐觉无心力。","自念因念君，俱爲老所逼。","君年虽校少，顦顇谪南国。","三年不放归，炎瘴消颜色。","山无杀草霜，水有含沙蜮。","健否远不知，书多隔年得。","愿君少愁苦，我亦加餐食。","各保金石躯，以慰长相忆。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22367":["秋夕","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["叶声落如雨，月色白似霜。","夜深方独卧，谁爲拂尘牀。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22368":["夜雨","白居易","五言绝句","约元和间","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["我有所念人，隔在远远乡。","我有所感事，结在深深肠。","乡远去不得，无日不瞻望。","肠深解不得，无夕不思量。","况此残灯夜，独宿在空堂。","秋天殊未晓，风雨正苍苍。","不学头陀法，前心安可忘。"],"",[],{},[["隔窗知夜雨，芭蕉先有声。","写雨名句，以声写静。"]],["https://github.com/chinese-poetry/chinese-poetry","《全唐诗》卷四四〇","《唐诗鉴赏辞典》白居易条（上海辞书出版社，1983）","《全唐诗》（清·曹寅等编，康熙扬州诗局本）"]],"open_22369":["秋霁","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["金火不相待，炎凉雨中变。","林晴有残蝉，巢冷无留燕。","沈吟卷长簟，怆恻收团扇。","向夕稍无泥，闲步青苔院。","月出砧杵动，家家捣秋练。","独对多病妻，不能理鍼线。","冬衣殊未制，夏服行将绽。","何以迎早秋，一杯聊自劝。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22370":["叹老三首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["晨兴照青镜，形影两寂莫。","少年辞我去，白发随梳落。","万化成於渐，渐衰看不觉。","但恐镜中颜，今朝老於昨。","人年少满百，不得长欢乐。","谁会天地心，千龄与龟鹤。","吾闻善医者，今古称扁鹊。","万病皆可治，唯无治老药。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22371":["叹老三首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["我有一握发，梳理何稠直。","昔似玄云光，今如素丝色。","匣中有旧镜，欲照先叹息。","自从头白来，不欲明磨拭。","鵶头与鹤颈，至老常如墨。","独有人鬓毛，不得终身黑。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22372":["叹老三首 三","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["前年种桃核，今岁成花树。","去岁新婴儿，今年已学步。","但惊物长成，不觉身衰暮。","去矣欲何如，少年留不住。","因书今日意，徧寄诸亲故。","壮岁不欢娱，长年当悔悟。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22373":["送兄弟回雪夜","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["日晦云气黄，东北风切切。","时从村南还，新与兄弟别。","离襟泪犹湿，回马嘶未歇。","欲归一室坐，天阴多无月。","夜长火消尽，岁暮雨凝结。","寂莫满炉灰，飘零上阶雪。","对雪画寒灰，残灯明复灭。","灰死如我心，雪白如我发。","所隅皆如此，顷刻堪愁绝。","回念入坐忘，转忧作禅悦。","平生洗心法，正爲今宵设。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22374":["溪中早春","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["南山雪未尽，阴岭留残白。","西涧冰已消，春溜含新碧。","东风来几日，蛰动萌草坼。","潜知阳和功，一日不虚掷。","爱此天气暖，来拂溪边石。","一坐欲忘归，暮禽声啧啧。","蓬蒿隔桑枣，隐映烟火夕。","归来问夜餐，家人烹荠麦。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22375":["同友人寻涧花","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["闻有涧底花，贳得村中酒。","与君来校迟，已逢摇落後。","临觞有遗恨，怅望空溪口。","记取花发时，期君重携手。","我生日日老，春色年年有。","且作来岁期，不知身健否。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22376":["登村东古冢","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["高低古时冢，上有牛羊道。","独立最高头，悠哉此怀抱。","回头向村望，但见荒田草。","村人不爱花，多种栗与枣。","自来此村住，不觉风光好。","花少莺亦稀，年年春暗老。"],"闲闲语似不关情乃其关情特甚",[["古评·《唐诗镜》","闲闲语似不关情乃其关情特甚"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_22377":["梦裴相公","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["五年生死隔，一夕魂梦通。","梦中如往日，同直金銮宫。","髣髴金紫色，分明冰玉容。","勤勤相眷意，亦与平生同。","既寤知是梦，悯然情未终。","追想当时事，何殊昨夜中。","自我学心法，万缘成一空。","今朝爲君子，流涕一沾胷。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22378":["昼寝","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["坐整白单衣，起穿黄草屦。","朝餐盥漱毕，徐下阶前步。","暑风微变候，昼刻渐加数。","院静地阴阴，鸟鸣新叶树。","独行还独卧，夏景殊未暮。","不作午时眠，日长安可度。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22379":["别行简","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["漠漠病眼花，星星愁鬓雪。","筋骸已衰惫，形影仍分诀。","梓州二千里，劒门五六月。","岂是远行时，火云烧栈热。","何言巾上泪，乃是肠中血。","念此早归来，莫作经年别。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22380":["观儿戏","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["髫龀七八岁，绮纨三四儿。","弄尘复鬭草，尽日乐嬉嬉。","堂上长年客，鬓间新有丝。","一看竹马戏，每忆童騃时。","童騃饶戏乐，老大多忧悲。","静念彼与此，不知谁是痴。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22381":["叹常生","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["西村常氏子，卧疾不须臾。","前旬犹访我，今日忽云殂。","时我病多暇，与之同野居。","园林青蔼蔼，相去数里余。","村邻无好客，所遇唯农夫。","之子何如者，往还犹胜无。","於今亦已矣，可爲一长吁。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22382":["寄元九","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["一病经四年，亲朋书信断。","穷通合易交，自笑知何晚。","元君在荆楚，去日唯云远。","彼独是何人，心如石不转。","忧我贫病身，书来唯劝勉。","上言少愁苦，下道加餐饭。","怜君爲谪吏，穷薄家贫褊。","三寄衣食资，数盈二十万。","岂是贪衣食，感君心缱绻。","念我口中食，分君身上暖。","不因身病久，不因命多蹇。","平生亲友心，岂得知深浅。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22383":["以镜赠别","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["人言似明月，我道胜明月。","明月非不明，一年十二缺。","岂如玉匣里，如水常澄澈。","月破天闇时，圆明独不歇。","我慙貌丑老，绕鬓斑斑雪。","不如赠少年，回照青丝发。","因君千里去，持此将爲别。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22384":["城上对月期友人不至","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["古人惜昼短，劝令秉烛游。","况此迢迢夜，明月满西楼。","复有盈尊酒，置在城上头。","期君君不至，人月两悠悠。","照水烟波白，照人肌发秋。","清光正如此，不醉即须愁。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22385":["念金銮子二首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["衰病四十身，娇痴三岁女。","非男犹胜无，慰情时一抚。","一朝舍我去，魂影无处所。","况念夭札时，呕哑初学语。","始知骨肉爱，乃是忧悲聚。","唯思未有前，以理遣伤苦。","忘怀日已久，三度移寒暑。","今日一伤心，因逢旧乳母。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22386":["念金銮子二首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["与尔爲父子，八十有六旬。","忽然又不见，迩来三四春。","形质本非实，气聚偶成身。","恩爱元是妄，缘合暂爲亲。","念兹庶有悟，聊用遣悲辛。","暂将理自夺，不是忘情人。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22387":["对酒","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["人生一百岁，通计三万日。","何况百岁人，人间百无一。","贤愚共零落，贵贱同埋没。","东岱前後魂，北邙新旧骨。","复闻药误者，爲爱延年术。","又有忧死者，爲贪政事笔。","药误不得老，忧死非因疾。","谁言人最灵，知得不知失。","何如会亲友，饮此杯中物。","能沃烦虑消，能陶真性出。","所以刘阮辈，终年醉兀兀。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22388":["渭村雨归","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["渭水寒渐落，离离蒲稗苗。","闲傍沙边立，看人刈苇苕。","近水风景冷，晴明犹寂寥。","复兹夕阴起，野色重萧条。","萧条独归路，暮雨湿村桥。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22389":["谕怀","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["黑头日已白，白面日已黑。","人生未死间，变化何终极。","常言在己者，莫若形与色。","一朝改变来，止遏不能得。","况彼身外事，悠悠通与塞。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22390":["喜友至留宿","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["村中少宾客，柴门多不开。","忽闻车马至，云是故人来。","况值风雨夕，愁心正悠哉。","愿君且同宿，尽此手中杯。","人生开口笑，百年都几回。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22391":["西原晚望","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["花菊引闲行，行上西原路。","原上晚无人，因高聊四顾。","南阡有烟火，北陌连墟墓。","村邻何萧疎，近者犹百步。","吾庐在其下，寂莫风日暮。","门外转枯蓬，篱根伏寒兔。","故园汴水上，离乱不堪去。","近岁始移家，飘然此村住。","新屋五六间，古槐八九树。","便是衰病身，此生终老处。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22392":["感镜","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["美人与我别，留镜在匣中。","自从花颜去，秋水无芙蓉。","经年不开匣，红埃覆青铜。","今朝一拂拭，自照顦顇容。","照罢重惆怅，背有双盘龙。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22393":["村居卧病三首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["戚戚抱羸病，悠悠度朝暮。","夏木才结阴，秋兰已含露。","前日巢中卵，化作雏飞去。","昨日穴中虫，蜕爲蝉上树。","四时未尝歇，一物不暂住。","唯有病客心，沈然独如故。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22394":["村居卧病三首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["新秋久病客，起步村南道。","尽日不逢人，虫声徧荒草。","西风吹白露，野绿秋仍早。","草木犹爲伤，先伤我怀抱。","朱颜与玄鬓，强健几时好。","况爲忧病侵，不得依年老。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22395":["村居卧病三首 三","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["种黍三十亩，雨来苗渐大。","种薤二十畦，秋来欲堪刈。","望黍作冬酒，留薤爲春菜。","荒村百物无，待此养衰瘵。","葺庐备阴雨，补褐防寒岁。","病身知几时，且作明年计。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22396":["沐浴","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["经年不沐浴，尘垢满肌肤。","今朝一澡濯，衰瘦颇有余。","老色头鬓白，病形支体虚。","衣宽有賸带，发少不胜梳。","自问今年岁，春秋四十初。","四十已如此，七十复何如。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22397":["栽松二首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["小松未盈尺，心爱手自移。","苍然涧底色，云湿烟霏霏。","栽植我年晚，长成君性迟。","如何过四十，种此数寸枝。","得见成阴否，人生七十稀。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22398":["栽松二首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["爱君抱晚节，怜君含直文。","欲得朝朝见，阶前故种君。","知君死则已，不死会凌云。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22399":["病中友人相访","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["卧久不记日，南窗昏复昏。","萧条草檐下，寒雀朝夕闻。","强扶牀前杖，起向庭中行。","偶逢故人至，便当一逢迎。","移榻就斜日，披裘倚前楹。","闲谈胜服药，稍觉有心情。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22400":["自觉二首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["四十未爲老，忧伤早衰恶。","前岁二毛生，今年一齿落。","形骸日损耗，心事同萧索。","夜寝与朝餐，其间味亦薄。","同岁崔舍人，容光方灼灼。","始知年与貌，衰盛随忧乐。","畏老老转迫，忧病病弥缚。","不畏复不忧，是除老病药。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22401":["自觉二首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["朝哭心所爱，暮哭心所亲。","亲爱零落尽，安用身独存。","几许平生欢，无限骨肉恩。","结爲肠间痛，聚作鼻头辛。","悲来四支缓，泣尽双眸昏。","所以年四十，心如七十人。","我闻浮屠教，中有解脱门。","置心爲止水，视身如浮云。","斗擞垢秽衣，度脱生死轮。","胡爲恋此苦，不去犹逡巡。","回念发弘愿，愿此见在身。","但受过去报，不结将来因。","誓以智慧水，永洗烦恼尘。","不将恩爱子，更种悲忧根。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22402":["夜雨有念","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["以道治心气，终岁得晏然。","何乃戚戚意，忽来风雨天。","既非慕荣显，又不恤饥寒。","胡爲悄不乐，抱膝残灯前。","形影闇相问，心默对以言。","骨肉能几人，各在天一端。","吾兄寄宿州，吾弟客东川。","南北五千里，吾身在中间。","欲去病未能，欲住心不安。","有如波上舟，此缚而彼牵。","自我向道来，於今六七年。","链成不二性，消尽千万缘。","唯有恩爱火，往往犹熬煎。","岂是药无効，病多难尽蠲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22403":["寄杨六","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["青宫官冷静，赤县事繁剧。","一闲复一忙，动作经时隔。","清觞久废酌，白日顿虚掷。","念此忽踟蹰，悄然心不适。","岂无旧交结，久别或迁易。","亦有新往还，相见多形迹。","唯君於我分，坚久如金石。","何况老大来，人情重姻戚。","会稀岁月急，此事真可惜。","几回开口笑，便到髭须白。","公门苦鞅掌，尽日无闲隙。","犹冀乘暝来，静言同一夕。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22404":["送春","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["三月三十日，春归日复暮。","惆怅问春风，明朝应不住。","送春曲江上，眷眷东西顾。","但见扑水花，纷纷不知数。","人生似行客，两足无停步。","日日进前程，前程几多路。","兵刀与水火，尽可违之去。","唯有老到来，人间无避处。","感时良爲已，独倚池南树。","今日送春心，心如别亲故。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22405":["哭李三","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["去年渭水曲，秋时访我来。","今年常乐里，春日哭君回。","哭君仰问天，天意安在哉。","若必夺其寿，何如不与才。","落然身後事，妻病女婴孩。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22406":["别李十一後重寄","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["秋日正萧条，驱车出蓬荜。","回望青门道，目极心郁郁。","岂独恋乡土，非关慕簪绂。","所怆别李君，平生同道术。","俱承金马诏，联秉谏臣笔。","共上青云梯，中途一相失。","江湖我方往，朝廷君不出。","蕙带与华簪，相逢是何日。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22407":["初出蓝田路作","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["停骖问前路，路在秋云里。","苍苍县南道，去途从此始。","绝顶忽上盘，衆山皆下视。","下视千万峰，峰头如浪起。","朝经韩公坡，夕次蓝桥水。","浔阳近四千，始行七十里。","人烦马蹄跙，劳苦已如此。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22408":["仙娥峰下作","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["我爲东南行，始登商山道。","商山无数峰，最爱仙娥好。","参差树若插，匼匝云如抱。","渴望寒玉泉，香闻紫芝草。","青崖屏削碧，白石牀铺缟。","向无如此物，安足留四皓。","感彼私自问，归山何不早？","可能尘土中，还随衆人老。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22409":["微雨夜行","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["漠漠秋云起，稍稍夜寒生。","但觉衣裳湿，无点亦无声。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22410":["再到襄阳访问旧居","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昔到襄阳日，髯髯初有髭。","今过襄阳日，髭鬓半成丝。","旧游都是梦，乍到忽如归。","东郭蓬蒿宅，荒凉今属谁。","故知多零落，闾井亦迁移。","独有秋江水，烟波似旧时。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22411":["寄微之三首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江州望通州，天涯与地末。","有山万丈高，有江千里阔。","间之以云雾，飞鸟不可越。","谁知千古险，爲我二人设。","通州君初到，郁郁愁如结。","江州我方去，迢迢行未歇。","道路日乖隔，音信日断绝。","因风欲寄语，地远声不彻。","生当复相逢，死当从此别。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22412":["寄微之三首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["君游襄阳日，我在长安住。","今君在通州，我过襄阳去。","襄阳九里郭，楼堞连云树。","顾此稍依依，是君旧游处。","苍茫蒹葭水，中有浔阳路。","此去更相思，江西少亲故。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22413":["寄微之三首 三","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["去国日已远，喜逢物似人。","如何含此意，江上坐思君。","有如河岳气，相合方氛氲。","狂风吹中绝，两处成孤云。","风回终有时，云合岂无因。","努力各自爱，穷通我尔身。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22414":["舟中雨夜","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江云闇悠悠，江风冷修修。","夜雨滴船背，风浪打船头。","船中有病客，左降向江州。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22415":["夜闻歌者","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["夜泊鹦鹉洲，江月秋澄澈。","邻船有歌者，发词堪愁绝。","歌罢继以泣，泣声通复咽。","寻声见其人，有妇颜如雪。","独倚帆樯立，娉婷十七八。","夜泪如真珠，双双堕明月。","借问谁家妇，歌泣何凄切。","一问一沾襟，低眉终不说。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22416":["江楼闻砧","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江人授衣晚，十月始闻砧。","一夕高楼月，万里故园心。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22417":["宿东林寺","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["经窗灯焰短，僧炉火气深。","索落庐山夜，风雪宿东林。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22418":["忆洛下故园","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["浔阳迁谪地，洛阳离乱年。","烟尘三川上，炎瘴九江边。","乡心坐如此，秋风仍飒然。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22419":["赠别崔五","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["朝送南去客，暮迎北来宾。","孰云当大路，少遇心所亲。","劳者念息肩，热者思濯身。","何如愁独日，忽见平生人。","平生已不浅，是日重殷勤。","问从何处来，及此江亭春。","江天春多阴，夜月隔重云。","移尊树间饮，灯照花纷纷。","一会不易得，余事何足云。","明旦又分手，今夕且欢忻。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22420":["春晚寄微之","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["三月江水阔，悠悠桃花波。","年芳与心事，此地共蹉跎。","南国方谴谪，中原正兵戈。","眼前故人少，头上白发多。","通州更迢遰，春尽复如何。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22421":["渐老","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["今朝复明日，不觉年齿暮。","白发逐梳落，朱颜辞镜去。","当春颇愁寂，对酒寡欢趣。","遇境多怆辛，逢人益敦故。","形质属天地，推迁从不住。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22422":["送幼史","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["淮右寇未散，江西岁再徂。","故里干戈地，行人风雪途。","此时与尔别，江畔立踟蹰。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22423":["夜雪","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["已讶衾枕冷，复见窗户明。","夜深知雪重，时闻折竹声。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22424":["寄行简","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["郁郁眉多敛，默默口寡言。","岂是愿如此，举目谁与欢。","去春尔西征，从事巴蜀间。","今春我南谪，抱疾江海壖。","相去六千里，地绝天邈然。","十书九不达，何以开忧颜。","渴人多梦饮，饥人多梦餐。","春来梦何处，合眼到东川。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22425":["首夏","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["孟夏百物滋，动植一时好。","麋鹿乐深林，虫蛇喜丰草。","翔禽爱密叶，游鳞悦新藻。","天和遗漏处，而我独枯槁。","一身在天末，骨肉皆远道。","旧国无来人，寇戎尘浩浩。","沈忧竟何益，祗自劳怀抱。","不如放身心，冥然任天造。","浔阳多美酒，可使杯不燥。","湓鱼贱如泥，烹炙无昏早。","朝饭山下寺，暮醉湖中岛。","何必归故乡，兹焉可终老。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22426":["孟夏思渭村旧居寄舍弟","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["啧啧雀引雏，稍稍笋成竹。","时物感人情，忆我故乡曲。","故园渭水上，十载事樵牧。","手种榆柳成，阴阴覆墙屋。","兔隐豆苗肥，鸟鸣桑椹熟。","前年当此时，与尔同游瞩。","诗书课弟侄，农圃资童仆。","日暮麦登场，天晴蚕坼簇。","弄泉南涧坐，待月东亭宿。","兴发饮数杯，闷来棊一局。","一朝忽分散，万里仍羁束。","井鲋思反泉，笼莺悔出谷。","九江地卑湿，四月天炎燠。","苦雨初入梅，瘴云稍含毒。","泥秧水畦稻，灰种畲田粟。","已讶殊岁时，仍嗟异风俗。","闲登郡楼望，日落江山绿。","归雁拂乡心，平湖断人目。","殊方我漂泊，旧里君幽独。","何时同一瓢，饮水心亦足。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22427":["早蝉","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["六月初七日，江头蝉始鸣。","石楠深叶里，薄暮两三声。","一催衰鬓色，再动故园情。","西风殊未起，秋思先秋生。","忆昔在东掖，宫槐花下听。","今朝无限思，云树绕湓城。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22428":["感情","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["中庭晒服玩，忽见故乡履。","昔赠我者谁，东邻婵娟子。","因思赠时语，特用结终始。","永愿如履綦，双行复双止。","自吾谪江郡，漂荡三千里。","爲感长情人，提携同到此。","今朝一惆怅，反覆看未已。","人只履犹双，何曾得相似。","可嗟复可惜，锦表绣爲里。","况经梅雨来，色黯花草死。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22429":["南湖晚秋","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["八月白露降，湖中水方老。","旦夕秋风多，衰荷半倾倒。","手攀青枫树，足蹋黄芦草。","惨澹老容颜，冷落秋怀抱。","有兄在淮楚，有弟在蜀道。","万里何时来，烟波白浩浩。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22430":["郡厅有树晚荣早凋人不识名因题其上","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["浔阳郡厅後，有树不知名。","秋先梧桐落，春後桃李荣。","五月始萌动，八月已凋零。","左右皆松桂，四时郁青青。","岂量雨露恩，沾濡不均平。","荣枯各有分，天地本无情。","顾我亦相类，早衰向晚成。","形骸少多病，三十不丰盈。","毛鬓早改变，四十白髭生。","谁教两萧索，相对此江城。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22431":["感秋怀微之","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["叶下湖又波，秋风此时至。","谁知濩落心，先纳萧条气。","推移感流岁，漂泊思同志。","昔爲烟霄侣，今作泥涂吏。","白鸥毛羽弱，青凤文章异。","各闭一笼中，岁晚同顦顇。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22432":["因沐感发寄朗上人二首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["年长身转慵，百事无所欲。","乃至头上发，经年方一沐。","沐稀发苦落，一沐仍半秃。","短鬓经霜蓬，老面辞春木。","强年过犹近，衰相来何速。","应是烦恼多，心焦血不足。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22433":["因沐感发寄朗上人二首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["渐少不满把，渐短不盈尺。","况兹短少中，日夜落复白。","既无神仙术，何除老死籍。","祗有解脱门，能度衰苦厄。","掩镜望东寺，降心谢禅客。","衰白何足言，剃落犹不惜。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22434":["早蝉","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["月出先照山，风生先动水。","亦如早蝉声，先入闲人耳。","一闻愁意结，再听乡心起。","渭上新蝉声，先听浑相似。","衡门有谁听，日暮槐花里。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22435":["苦热喜凉","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["经时苦炎暑，心体但烦倦。","白日一何长，清秋不可见。","岁功成者去，天数极则变。","潜知寒燠间，迁次如乘传。","火云忽朝敛，金风俄夕扇。","枕簟遂清凉，筋骸稍轻健。","因思望月侣，好卜迎秋宴。","竟夜无客来，引杯还自劝。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22436":["早秋晚望兼呈韦侍郎","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["九派绕孤城，城高生远思。","人烟半在船，野水多於地。","穿霞日脚直，驱雁风头利。","去国来几时，江上秋三至。","夫君亦沦落，此地同飘寄。","悯默向隅心，摧颓触笼翅。","且谋眼前计，莫问胸中事。","浔阳酒甚浓，相劝时时醉。"],"人烟二语墅趣最佳湘亭晚望登亭望湘水水缩湖㡳出亦佳",[["古评·《唐诗镜》","人烟二语墅趣最佳湘亭晚望登亭望湘水水缩湖㡳出亦佳"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_22437":["司马宅","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["雨径绿芜合，霜园红叶多。","萧条司马宅，门巷无人过。","唯对大江水，秋风朝夕波。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22438":["司马厅独宿","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["荒凉满庭草，偃亚侵檐竹。","府吏下厅帘，家僮开被襆。","数声城上漏，一点窗间烛。","官曹冷似冰，谁肯来同宿。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22439":["梦与李七庾三十三同访元九","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["夜梦归长安，见我故亲友。","损之在我左，顺之在我右。","云是二月天，春风出携手。","同过靖安里，下马寻元九。","元九正独坐，见我笑开口。","还指西院花，仍开北亭酒。","如言各有故，似惜欢难久。","神合俄顷间，神离欠伸後。","觉来疑在侧，求索无所有。","残灯影闪墙，斜月光穿牖。","天明西北望，万里君知否。","老去无见期，踟蹰搔白首。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22440":["秋槿","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["风露飒已冷，天色亦黄昏。","中庭有槿花，荣落同一晨。","秋开已寂莫，夕陨何纷纷。","正怜少颜色，复叹不逡巡。","感此因念彼，怀哉聊一陈。","男儿老富贵，女子晚婚姻。","头白始得志，色衰方事人。","後时不获已，安得如青春。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22441":["荅元郎中杨员外喜乌见寄","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["南宫鸳鸯地，何忽乌来止。","故人锦帐郎，闻乌笑相视。","疑乌报消息，望我归乡里。","我归应待乌头白，慙媿元郎误欢喜。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22442":["初入峡有感","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["上有万仞山，下有千丈水。","苍苍两崖间，阔狭容一苇。","瞿唐呀直泻，灩澦屹中峙。","未夜黑岩昏，无风白浪起。","大石如刀劒，小石如牙齿。","一步不可行，况千三百里。","苒蒻竹篾𥮘，欹危檝师趾","一跌无完舟，吾生系於此。","常闻仗忠信，蛮貊可行矣。","自古漂沈人，岂尽非君子。","况吾时与命，蹇舛不足恃。","常恐不才身，复作无名死。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22443":["过昭君村","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["灵珠产无种，彩云出无根。","亦如彼姝子，生此遐陋村。","至丽物难掩，遽选入君门。","独美衆所嫉，终弃出塞垣。","唯此希代色，岂无一顾恩。","事排势须去，不得由至尊。","白黑既可变，丹青何足论。","竟埋代北骨，不返巴东魂。","惨澹晚云水，依稀旧乡园。","妍姿化已久，但有村名存。","村中有遗老，指点爲我言。","不敢往者戒，恐贻来者冤。","至今村女面，烧灼成瘢痕。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22444":["自江州至忠州","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["前在浔阳日，已叹宾朋寡。","忽忽抱忧怀，出门无处写。","今来转深僻，穷峡巅山下。","五月断行舟，灩堆正如马。","巴人类猨狖，矍铄满山野。","敢望见交亲，喜逢似人者。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22445":["初到忠州登东楼寄万州杨八使君","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["山束邑居窄，峡牵气候偏。","林峦少平地，雾雨多阴天。","隐隐煮盐火，漠漠烧畲烟。","赖此东楼夕，风月时翛然。","凭轩望所思，目断心涓涓。","背春有去雁，上水无来船。","我怀巴东守，本是关西贤。","平生已不浅，流落重相怜。","水梗漂万里，笼禽囚五年。","新恩同雨露，远郡邻山川。","书信虽往复，封疆徒接连。","其如美人面，欲见杳无缘。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22446":["郡中","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["乡路音信断，山城日月迟。","欲知州近远，阶前摘荔枝。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22447":["西楼夜","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["悄悄复悄悄，城隅隐林杪。","山郭灯火稀，峡天星汉少。","年光东流水，生计南枝鸟。","月没江沈沈，西楼殊未晓。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22448":["东楼晓","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["脉脉复脉脉，东楼无宿客。","城闇云雾多，峡深田地窄。","宵灯尚留焰，晨禽初展翮。","欲知山高低，不见东方白。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22449":["寄王质夫","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["忆始识君时，爱君世缘薄。","我亦吏王畿，不爲名利着。","春寻仙游洞，秋上云居阁。","楼观水潺潺，龙潭花漠漠。","吟诗石上坐，引酒泉边酌。","因话出处心，心期老岩壑。","忽从风雨别，遂被簪缨缚。","君作出山云，我爲入笼鹤。","笼深鹤残顇，山远云飘泊。","去处虽不同，同负平生约。","今来各何在，老去随所托。","我守巴南城，君佐征西幕。","年颜渐衰飒，生计仍萧索。","方含去国愁，且羡从军乐。","旧游疑是梦，往事思如昨。","相忆春又深，故山花正落。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22450":["南宾郡斋即事寄杨万州","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["山上巴子城，山下巴江水。","中有穷独人，强名爲刺史。","时时窃自哂，刺史岂如是。","仓粟餧家人，黄缣裹妻子。","莓苔翳冠带，雾雨霾楼雉。","衙鼓暮复朝，郡斋卧还起。","回头望南浦，亦在烟波里。","而我复何嗟，夫君犹滞此。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22451":["招萧处士","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["峡内岂无人，所逢非所思。","门前亦有客，相对不相知。","仰望但云树，俯顾惟妻儿。","寝食起居外，端然无所爲。","东郊萧处士，聊可与开眉。","能饮满杯酒，善吟长句诗。","庭前吏散後，江畔路乾时。","请君携竹杖，一赴郡斋期。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22452":["庭槐","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["南方饶竹树，唯有青槐稀。","十种七八死，纵活亦支离。","何此郡庭下，一株独华滋。","蒙蒙碧烟叶，嫋嫋黄花枝。","我家渭水上，此树荫前墀。","忽向天涯见，忆在故园时。","人生有情感，遇物牵所思。","树木犹复尔，况见旧亲知。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22453":["送客回晚兴","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["城上云雾开，沙头风浪定。","参差乱山出，澹泞平江净。","行客舟已远，居人酒初醒。","嫋嫋秋竹梢，巴蝉声似磬。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22454":["东楼竹","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["潇洒城东楼，绕楼多修竹。","森然一万竿，白粉封青玉。","卷帘睡初觉，欹枕看未足。","影转色入楼，牀席生浮绿。","空城绝宾客，向夕弥幽独。","楼上夜不归，此君留我宿。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22455":["九日登巴台","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["黍香酒初熟，菊暖花未开。","闲听竹枝曲，浅酌茱萸杯。","去年重阳日，漂泊湓城隈。","今岁重阳日，萧条巴子台。","旅鬓寻已白，乡书久不来。","临觞一搔首，座客亦裴回。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22456":["东城寻春","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["老色日上面，欢情日去心。","今既不如昔，後当不如今。","今犹未甚衰，每事力可任。","花时仍爱出，酒後尚能吟。","但恐如此兴，亦随日销沈。","东城春欲老，勉强一来寻。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22457":["江上送客","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["江花已萎绝，江草已消歇。","远客何处归，孤舟今日发。","杜鹃声似哭，湘竹斑如血。","共是多感人，仍爲此中别。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22458":["桐花","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["春令有常候，清明桐始发。","何此巴峡中，桐花开十月。","岂伊物理变，信是土宜别。","地气反寒暄，天时倒生杀。","草木坚强物，所禀固难夺。","风候一参差，荣枯遂乖剌。","况吾北人性，不耐南方热。","强羸寿夭间，安得依时节。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22459":["早祭风伯因怀李十一舍人","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["远郡虽褊陋，时祀奉朝经。","夙兴祭风伯，天气晓冥冥。","导骑与从吏，引我出东垧。","水雾重如雨，山火高於星。","忽忆早朝日，与君趋紫庭。","步登龙尾道，却望终南青。","一别身向老，所思心未宁。","至今想在耳，玉音尚玲玲。"],"水雾二语甚有景色",[["古评·《唐诗镜》","水雾二语甚有景色"]],{},[],["https://github.com/chinese-poetry/chinese-poetry","古籍注评：《唐诗镜》（中文维基文库，CC BY-SA 4.0，https://zh.wikisource.org/wiki/唐詩鏡_(四庫全書本)）"]],"open_22460":["花下对酒二首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["蔼蔼江气春，南宾闰正月。","梅樱与桃杏，次第城上发。","红房烂簇火，素艳纷团雪。","香惜委风飘，愁牵压枝折。","楼中老太守，头上新白发。","冷澹病心情，暄和好时节。","故园音信断，远郡亲宾绝。","欲问花前尊，依然爲谁设。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22461":["花下对酒二首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["引手攀红樱，红樱落似霰。","仰首看白日，白日走如箭。","年芳与时景，顷刻犹衰变。","况是血肉身，安能长强健。","人心苦迷执，慕贵忧贫贱。","愁色常在眉，欢容不上面。","况吾头半白，把镜非不见。","何必花下杯，更待他人劝。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22462":["不二门","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["两眼日将闇，四肢渐衰瘦。","束带賸昔围，穿衣妨宽袖。","流年似江水，奔注无昏昼。","志气与形骸，安得长依旧。","亦曾登玉陛，举措多纰缪。","至今金阙籍，名姓独遗漏。","亦曾烧大药，消息乖火候。","至今残丹砂，烧乾不成就。","行藏事两失，忧恼心交鬬。","化作顦顇翁，抛身在荒陋。","坐看老病逼，须得医王救。","唯有不二门，其间无夭寿。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22463":["我身","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["我身何所似，似彼孤生蓬。","秋霜翦根断，浩浩随长风。","昔游秦雍间，今落巴蛮中。","昔爲意气郎，今作寂寥翁。","外貌虽寂莫，中怀颇冲融。","赋命有厚薄，委心任穷通。","通当爲大鹏，举翅摩苍穹。","穷则爲鹪鹩，一枝足自容。","苟知此道者，身穷心不穷。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22464":["哭王质夫","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["仙游寺前别，别来十年余。","生别犹怏怏，死别复何如。","客从梓潼来，道君死不虚。","惊疑心未信，欲哭复踟蹰。","踟蹰寝门侧，声发涕亦俱。","衣上今日泪，箧中前月书。","怜君古人风，重有君子儒。","篇咏陶谢辈，风流嵇阮徒。","出身既蹇屯，生世仍须臾。","诚知天至高，安得不一呼。","江南有毒蟒，江北有妖狐。","皆享千年寿，多於王质夫。","不知彼何德，不识此何辜。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22465":["东坡种花二首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["持钱买花树，城东坡上栽。","但购有花者，不限桃杏梅。","百果参杂种，千枝次第开。","天时有早晚，地力无高低。","红者霞艳艳，白者雪皑皑。","游蠭逐不去，好鸟亦来栖。","前有长流水，下有小平台。","时拂台上石，一举风前杯。","花枝荫我头，花蘂落我怀。","独酌复独咏，不觉月平西。","巴俗不爱花，竟春无人来。","唯此醉太守，尽日不能回。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22466":["东坡种花二首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["东坡春向暮，树木今何如。","漠漠花落尽，翳翳叶生初。","每日领童仆，荷鉏仍决渠。","剗土壅其本，引泉溉其枯。","小树低数尺，大树长丈余。","封植来几时，高下随扶疎。","养树既如此，养民亦何殊。","将欲茂枝叶，必先救根株。","云何救根株，劝农均赋租。","云何茂枝叶，省事宽刑书。","移此爲郡政，庶几甿俗苏。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22467":["登城东古台","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["迢迢东郊上，有土青崔嵬。","不知何代物，疑是巴王台。","巴歌久无声，巴宫没黄埃。","靡靡春草合，牛羊缘四隈。","我来一登眺，目极心悠哉。","始见江山势，峰叠水环回。","凭高视听旷，向远胷襟开。","唯有故园念，时时东北来。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22468":["哭诸故人因寄元八","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["昨日哭寝门，今日哭寝门。","借问所哭谁，无非故交亲。","伟卿既长往，质夫亦幽沦。","屈指数年世，收涕自思身。","彼皆少於我，先爲泉下人。","我今头半白，焉得身久存。","好狂元郎中，相识二十春。","昔见君生子，今闻君抱孙。","存者尽老大，逝者已成尘。","早晚升平宅，开眉一见君。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22469":["郡中春讌因赠诸客","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["仆本儒家子，待诏金马门。","尘忝亲近地，孤负圣明恩。","一旦奉优诏，万里牧远人。","可怜岛夷帅，自称爲使君。","身骑牂牁马，口食涂江鳞。","闇澹绯衫故，斓斑白发新。","是时岁二月，玉历布春分。","颁条示皇泽，命宴及良辰。","冉冉趋府吏，蚩蚩聚州民。","有如蛰虫鸟，亦应天地春。","薰草席铺坐，藤枝酒注樽。","中庭无平地，高下随所陈。","蛮鼓声坎坎，巴女舞蹲蹲。","使君居上头，掩口语衆宾。","勿笑风俗陋，勿欺官府贫。","蠭巢与蚁穴，随分有君臣。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22470":["开元寺东池早春","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["池水暖温暾，水清波潋灩。","簇簇青泥中，新蒲叶如劒。","梅房小白裹，柳彩轻黄染。","顺气草熏熏，适情鸥泛泛。","旧游成梦寐，往事随阳焱。","芳物感幽怀，一动平生念。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22471":["东溪种柳","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["野性爱栽植，植柳水中坻。","乘春持斧斫，裁截而树之。","长短既不一，高下随所宜。","倚岸埋大干，临流插小枝。","松柏不可待，楩柟固难移。","不如种此树，此树易荣滋。","无根亦可活，成阴况非迟。","三年未离郡，可以见依依。","种罢水边憩，仰头闲自思。","富贵本非望，功名须待时。","不种东溪柳，端坐欲何爲。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22472":["卧小斋","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["朝起视事毕，晏坐饱食终。","散步长廊下，卧退小斋中。","拙政自多暇，幽情谁与同。","孰云二千石，心如田野翁。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22473":["步东坡","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["朝上东坡步，夕上东坡步。","东坡何所爱，爱此新成树。","种植当岁初，滋荣及春暮。","信意取次栽，无行亦无数。","绿阴斜景转，芳气微风度。","新叶鸟下来，萎花蝶飞去。","闲携斑竹杖，徐曳黄麻屦。","欲识往来频，青芜成白路。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22474":["徵秋税毕题郡南亭","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["高城直下视，蠢蠢见巴蛮。","安可施政教，尚不通语言。","且喜赋敛毕，幸闻闾井安。","岂伊循良化，赖此丰登年。","案牍既简少，池馆亦清闲。","秋雨檐果落，夕钟林鸟还。","南亭日潇洒，偃卧恣疎顽。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22475":["蚊蟆","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["巴徼炎毒早，二月蚊蟆生。","咂肤拂不去，绕耳薨薨声。","斯物颇微细，中人初甚轻。","如有肤受谮，久则疮痏成。","痏成无奈何，所要防其萌。","麽虫何足道，潜喻儆人情。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22476":["登龙昌上寺望江南山怀钱舍人","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["骑马出西郭，悠悠欲何之。","独上高寺去，一与白云期。","虚槛晚潇洒，前山碧参差。","忽似青龙合，同望玉峰时。","因咏松雪句，永怀鸾鹤姿。","六年不相见，况乃隔荣衰。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22477":["郊下","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["西日照高树，树头子规鸣。","东风吹野水，水畔江蓠生。","尽日看山立，有时寻涧行。","兀兀长如此，何许似专城。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22478":["遣怀","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["乐往必悲生，泰来由否极。","谁言此数然，吾道何终塞。","尝求詹尹卜，拂龟竟默默。","亦曾仰问天，天但苍苍色。","自兹唯委命，名利心双息。","近日转安闲，乡园亦休忆。","回看世间苦，苦在求不得。","我今无所求，庶离忧悲域。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22479":["岁晚","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["霜降水返壑，风落木归山。","冉冉岁将宴，物皆复本源。","何此南迁客，五年独未还。","命屯分已定，日久心弥安。","亦尝心与口，静念私自言。","去国固非乐，归乡未必欢。","何须自生苦，舍易求其难。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22480":["负冬日","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["杲杲冬日出，照我屋南隅。","负暄闭目坐，和气生肌肤。","初似饮醇醪，又如蛰者苏。","外融百骸畅，中适一念无。","旷然忘所在，心与虚空俱。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22481":["委顺","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["山城虽荒芜，竹树有嘉色。","郡俸诚不多，亦足充衣食。","外累由心起，心宁累自息。","尚欲忘家乡，谁能算官职。","宜怀齐远近，委顺随南北。","归去诚可怜，天涯住亦得。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22482":["宿溪翁","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["衆心爱金玉，衆口贪酒肉。","何如此溪翁，饮瓢亦自足。","溪南刈薪草，溪北修墙屋。","岁种一顷田，春驱两黄犊。","於中甚安适，此外无营欲。","溪畔偶相逢，庵中遂同宿。","醉翁向朝市，问我何官禄。","虚言笑杀翁，郎官应列宿。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22483":["重过寿泉忆与杨九别时因题店壁","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["商州南十里，有水名寿泉。","涌出石崖下，流经山店前。","忆昔相送日，我去君言还。","寒波与老泪，此地共潺湲。","一去历万里，再来经六年。","形容已变改，处所犹依然。","他日君过此，殷懃吟此篇。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22484":["西掖早秋直夜书意","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["凉风起禁掖，新月生宫沼。","夜半秋闇来，万年枝嫋嫋。","炎凉递时节，钟鼓交昏晓。","遇圣惜年衰，报恩愁力小。","素餐无补益，朱绶虚缠绕。","冠盖栖野云，稻粱养山鸟。","量能私自省，所得已非少。","五品不爲贱，五十不爲夭。","若无知足心，贪求何日了。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22485":["庭松","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["堂下何所有，十松当我阶。","乱立无行次，高下亦不齐。","高者三丈长，下者十尺低。","有如野生物，不知何人栽。","接以青瓦屋，承之白沙台。","朝昏有风月，燥湿无尘泥。","疎韵秋槭槭，凉阴夏凄凄。","春深微雨夕，满叶珠蓑蓑。","岁暮大雪天，压枝玉皑皑。","四时各有趣，万木非其侪。","去年买此宅，多爲人所咍。","一家二十口，移转就松来。","移来有何得，但得烦襟开。","即此是益友，岂必交贤才。","顾我犹俗士，冠带走尘埃。","未称爲松主，时时一媿怀。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22486":["竹窗","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["常爱辋川寺，竹窗东北廊。","一别十余载，见竹未曾忘。","今春二月初，卜居在新昌。","未暇作廐库，且先营一堂。","开窗不糊纸，种竹不依行。","意取北檐下，窗与竹相当。","绕屋声淅淅，逼人色苍苍。","烟通杳蔼气，月透玲珑光。","是时三伏天，天气热如汤。","独此竹窗下，朝回解衣裳。","轻纱一幅巾，小簟六尺牀。","无客尽日静，有风终夜凉。","乃知前古人，言事颇谙详。","清风北窗卧，可以傲羲皇。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22487":["同韩侍郎游郑家池吟诗小饮","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["野艇容三人，晚池流浼浼。","悠然依櫂坐，水思如江海。","宿雨洗沙尘，晴风荡烟霭。","残阳上竹树，枝叶生光彩。","我本偶然来，景物如相待。","白鸥惊不起，绿芡行堪采。","齿发虽已衰，性灵未云改。","逢诗遇杯酒，尚有心情在。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22488":["晚归有感","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["朝吊李家孤，暮问崔家疾。","回马独归来，低眉心郁郁。","平生所善者，多不过六七。","如何十年间，零落三无一。","刘曾梦中见，元向花前失。","渐老与谁游，春城好风日。"],"此诗原题为《自河南经乱，关内阻饥，兄弟离散，各在一处。因望月有感，聊书所怀，寄上浮梁大兄、於潜七兄、乌江十五兄，兼示符离及下邽弟妹》。题甚长，盖白居易因河南战乱、关内饥荒，兄弟离散各处，望月有感而作此诗，寄诸兄及弟妹。时约贞元十五年至十八年间，白居易二十八九岁，尚未登第。诗写战乱中骨肉离散之悲，情真意切。",[["1. **时难**","时世艰难，此指战乱。"],["2. **年荒**","年成荒歉，饥荒。"],["3. **世业**","祖传之产业。"],["4. **羁旅**","客居异乡，漂泊流浪。"],["5. **寥落**","荒芜冷落。"],["6. **干戈**","兵器，借指战争。"],["7. **骨肉**","喻至亲。"],["8. **流离**","流亡离散。"],["9. **吊影**","自顾其影，形影相吊，写孤独之状。"],["10. **千里雁**","雁群飞千里，此喻兄弟分散各地如失群之雁。"],["11. **辞根**","离开树根。喻兄弟离散，离开故土。"],["12. **九秋蓬**","秋日之飞蓬。蓬草秋枯风拔，根离而飞。九秋，深秋。"],["13. **乡心**","思乡之心。"],["14. **五处**","白居易与浮梁大兄、於潜七兄、乌江十五兄及符离、下邽弟妹，分散五处。"]],{"source":"霍松林","body":["> **出处**：本节主要据霍松林《唐诗鉴赏辞典》“望月有感”条（上海辞书出版社，1983 年版，第 905—907 页），参以袁行霈《中国文学史》第二卷白居易章。","此诗写战乱中骨肉离散之悲。首联“时难年荒世业空，弟兄羁旅各西东”直点时代背景与离散之状——时世艰难、年成荒歉，祖传世业已空；弟兄羁旅，各在西东。此联将战乱、饥荒、家业、弟兄四事一气写出，笼罩全篇，沉痛之至。","颔联“田园寥落干戈后，骨肉流离道路中”承之具体写战乱之苦。上句写“田园”之寥落——干戈之后，田园荒芜；下句写“骨肉”之流离——道路之中，骨肉流亡。一“田园”一“骨肉”，一“寥落”一“流离”，将战乱之苦写得淋漓尽致。此联对仗工整，沉痛之至。","颈联“吊影分为千里雁，辞根散作九秋蓬”乃名句，以比喻写兄弟离散之状。上句以“千里雁”喻兄弟之分散——雁群失散，飞往千里之外；下句以“九秋蓬”喻兄弟之漂泊——蓬草离根，随风飞转。“吊影”写孤独，“辞根”写离散，二词皆含深悲。雁尚有群，而兄弟则“分为千里雁”；蓬尚有根，而兄弟则“辞根散作九秋蓬”——人不如物，悲何如之。","尾联“共看明月应垂泪，一夜乡心五处同”以望月作结，点明题旨。天下共此一月，分散五处之兄弟，此夜皆望月而垂泪，乡心相同。此联之妙，在于以“明月”为纽带，将分散五处之兄弟之心连在一起——虽身各一方，而望月之心则同。此即所谓“千里共婵娟”之意，然白居易此诗写于苏轼之前二百余年，已先得此意。","全诗以战乱为背景，以望月为线索，以兄弟离散为内容，以乡心相同为归结，结构严密，情感真挚。白居易此诗作于青年时期，已见其关心民瘼之精神，与后来《新乐府》之作一脉相承。诗中“千里雁”“九秋蓬”之喻，已成为写离散之经典意象。"]},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22489":["曲江感秋二首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["元和二年秋，我年三十七。","长庆二年秋，我年五十一。","中间十四年，六年居谴黜。","穷通与荣悴，委运随外物。","遂师庐山远，重吊湘江屈。","夜听竹枝愁，秋看灩堆没。","近辞巴郡印，又秉纶闱笔。","晚遇何足言，白发映朱绂。","销沈昔意气，改换旧容质。","独有曲江秋，风烟如往日。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22490":["曲江感秋二首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["疎芜南岸草，萧飒西风树。","秋到未几时，蝉声又无数。","莎平绿茸合，莲落青房露。","今日临望时，往年感秋处。","池中水依旧，城上山如故。","独我鬓间毛，昔黑今垂素。","荣名与壮齿，相避如朝暮。","时命始欲来，年颜已先去。","当春不欢乐，临老徒惊误。","故作咏怀诗，题於曲江路。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22491":["玩松竹二首 一","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["龙蛇隐大泽，麋鹿游丰草。","栖凤安於梧，潜鱼乐於藻。","吾亦爱吾庐，庐中乐吾道。","前松後修竹，偃卧可终老。","各附其所安，不知他物好。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22492":["玩松竹二首 二","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["坐爱前檐前，卧爱北窗北。","窗竹多好风，檐松有嘉色。","幽怀一以合，俗念随缘息。","在尔虽无情，於予即有得。","乃知性相近，不必动与植。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22493":["衰病无趣因吟所怀","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["朝餐多不饱，夜卧常少睡。","自觉寝食间，多无少年味。","平生好诗酒，今亦将舍弃。","酒唯下药饮，无复曾欢醉。","诗多听人吟，自不题一字。","病姿与衰相，日夜相继至。","况当尚少朝，弥慙居近侍。","终当求一郡，聚少渔樵费。","合口便归山，不问人间事。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22494":["逍遥咏","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["亦莫恋此身，亦莫厌此身。","此身何足恋，万劫烦恼根。","此身何足厌，一聚虚空尘。","无恋亦无厌，始是逍遥人。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22495":["短歌行","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["曈曈太阳如火色，上行千里下一刻。","出爲白昼入爲夜，圆转如珠住不得。","住不得，可奈何，爲君举酒歌短歌。","歌声苦，词亦苦，四座少年君听取。","今夕未竟明夕催，秋风才往春风回。","人无根蔕时不驻，朱颜白日相隳颓。","劝君且强笑一面，劝君且强饮一杯。","人生不得长欢乐，年少须臾老到来。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22496":["生离别","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["食檗不易食梅难，檗能苦兮梅能酸。","未如生别之爲难，苦在心兮酸在肝。","晨鸡再鸣残月没，征马连嘶行人出。","回看骨肉哭一声，梅酸檗苦甘如蜜。","黄河水白黄云秋，行人河边相对愁。","天寒野旷何处宿？棠棃叶战风飕飕。","生离别，生离别，忧从中来无断绝。","忧极心劳血气衰，未年三十生白发。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22497":["浩歌行","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["天长地久无终毕，昨夜今朝又明日。","鬓发苍浪牙齿疎，不觉身年四十七。","前去五十有几年，把镜照面心茫然。","既无长绳系白日，又无大药驻朱颜。","朱颜日渐不如故，青史功名在何处？","欲留年少待富贵，富贵不来年少去。","去复去兮如长河，东流赴海无回波。","贤愚贵贱同归尽，北邙冢墓高嵯峨。","古来如此非独我，未死有酒且高歌。","颜回短命伯夷饿，我今所得亦已多。","功名富贵须待命，命若不来知奈何。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22498":["王夫子","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["王夫子，送君爲一尉，东南三千五百里。","道途虽远位虽卑，月俸犹堪活妻子。","男儿口读古人书，束带敛手来从事。","近将徇禄给一家，远则行道佐时理。","行道佐时须待命，委身下位无爲耻。","命苟未来且求食，官无卑高及远迩。","男儿上既未能济天下，下又不至饥寒死。","吾观九品至一品，其间气味都相似。","紫绶朱绂青布衫，颜色不同而已矣。","王夫子，别有一事欲劝君，遇酒逢春且欢喜。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]],"open_22499":["江南遇天宝乐叟","白居易","未知","约809前后","《全唐诗》开放数据合并版（chinese-poetry，MIT）",["白头病叟泣且言，禄山未乱入棃园。","能弹琵琶和法曲，多在华清随至尊。","是时天下太平久，年年十月坐朝元。","千官起居环佩合，万国会同车马奔。","金钿照耀石瓮寺，兰麝熏煮温汤源。","贵妃宛转侍君侧，体弱不胜珠翠繁。","冬雪飘颻锦袍暖，春风荡漾霓裳飜。","欢娱未足燕寇至，弓劲马肥胡语喧。","豳土人迁避夷狄，鼎湖龙去哭轩辕。","从此漂沦落南土，万人死尽一身存。","秋风江上浪无限，暮雨舟中酒一尊。","涸鱼久失风波势，枯草曾沾雨露恩。","我自秦来君莫问，骊山渭水如荒村。","新丰树老笼明月，长生殿闇锁春云。","红叶纷纷盖欹瓦，绿苔重重封坏垣。","唯有中官作宫使，每年寒食一开门。"],"",[],{},[],["https://github.com/chinese-poetry/chinese-poetry"]]};